def deg_to_16dir(deg):
    if pd.isna(deg):
        return ""
    try:
        value = float(deg)
        if value <= 0 or value > 360:
            return ""
        dirs = [
            "N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE",
            "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW",
        ]
        return dirs[int((value + 11.25) / 22.5) % 16]
    except Exception:
        return ""


# =============================================================================
# 3. 기상자료개방포털 안개/뇌전/결빙 CSV 파서
# =============================================================================


def decode_csv_bytes(raw: bytes) -> str:
    """기상자료개방포털 CSV 인코딩을 유연하게 처리."""
    for enc in ("utf-8-sig", "cp949", "euc-kr", "utf-8"):
        try:
            return raw.decode(enc)
        except UnicodeDecodeError:
            continue
    return raw.decode("cp949", errors="replace")


def safe_climate_number(value):
    """실제 0은 0, 빈칸/― 등 미관측은 NaN."""
    if value is None or pd.isna(value):
        return np.nan
    s = str(value).strip()
    if s in {"", "-", "―", "—", "–", "null", "None", "nan", "NaN"}:
        return np.nan
    try:
        return float(s.replace(",", ""))
    except Exception:
        return np.nan


def parse_kma_climate_csv_bytes(raw: bytes, source_name: str = "") -> dict:
    """
    사용자가 제공한 실제 포털 CSV 형식에 맞춘 파서.

    예시 구조:
        뇌전일수
        지점/지역명 : 포항

        평균 뇌전일수
        연도,1월,...,12월,연합계,순위
        1990,...
        ...
        평균,...

        평균 계절별 뇌전일수
        ...

    첫 번째 월별 표만 읽는다.
    """
    text = decode_csv_bytes(raw).replace("\r\n", "\n").replace("\r", "\n")
    lines = [line.rstrip("\n") for line in text.split("\n")]

    kind = None
    for line in lines[:12]:
        normalized = line.replace("젼", "전")
        if "안개일수" in normalized:
            kind = "안개"
            break
        if "뇌전일수" in normalized:
            kind = "뇌전"
            break
        if "결빙일수" in normalized:
            kind = "결빙"
            break

    if kind is None:
        name_hint = str(source_name).replace("젼", "전")
        if "안개" in name_hint:
            kind = "안개"
        elif "뇌전" in name_hint:
            kind = "뇌전"
        elif "결빙" in name_hint:
            kind = "결빙"

    station_name = None
    observation_period = None
    for line in lines[:20]:
        if "지점/지역명" in line:
            station_name = line.split(":", 1)[1].strip() if ":" in line else None
        if "목측 관측 수행 기간" in line:
            observation_period = line.split(":", 1)[1].strip() if ":" in line else line.strip()

    # 월별 주표 헤더 자동 탐색
    header_idx = None
    for i, line in enumerate(lines):
        compact = line.replace(" ", "")
        if compact.startswith("연도,1월,2월,3월"):
            header_idx = i
            break

    if header_idx is None:
        raise ValueError("월별 표의 '연도,1월,2월...' 헤더를 찾지 못했습니다.")

    header = [x.strip() for x in lines[header_idx].split(",")]
    rows = []

    for line in lines[header_idx + 1 :]:
        if not line.strip():
            break
        first = line.split(",", 1)[0].strip()
        if first == "평균" or not re.fullmatch(r"\d{4}", first):
            break

        parts = [x.strip() for x in line.split(",")]
        if len(parts) < len(header):
            parts += [""] * (len(header) - len(parts))
        elif len(parts) > len(header):
            parts = parts[: len(header)]
        rows.append(parts)

    if not rows:
        raise ValueError("월별 연도 자료를 찾지 못했습니다.")

    df = pd.DataFrame(rows, columns=header)
    df["연도"] = pd.to_numeric(df["연도"], errors="coerce")
    df = df[df["연도"].notna()].copy()
    df["연도"] = df["연도"].astype(int)

    for col in [f"{m}월" for m in range(1, 13)] + ["연합계", "순위"]:
        if col in df.columns:
            df[col] = df[col].map(safe_climate_number)

    return {
        "kind": kind,
        "station_name": station_name,
        "observation_period": observation_period,
        "data": df,
        "source_name": source_name,
    }


def parse_kma_climate_csv_path(path: Path) -> dict:
    return parse_kma_climate_csv_bytes(path.read_bytes(), path.name)


def climate_file_candidates() -> list[Path]:
    candidates: list[Path] = []
    for root in (BASE_DIR, CLIMATE_DIR):
        if not root.exists():
            continue
        for path in root.glob("*.csv"):
            name = path.name.replace("젼", "전")
            if "안개일수" in name or "뇌전일수" in name or "결빙일수" in name:
                candidates.append(path)
    # 중복 경로 제거
    unique = []
    seen = set()
    for p in candidates:
        key = str(p.resolve())
        if key not in seen:
            seen.add(key)
            unique.append(p)
    return unique


def build_climate_file_index() -> tuple[dict, list[str]]:
    """(종류, 지점명) -> 파싱결과"""
    index = {}
    errors = []
    for path in climate_file_candidates():
        try:
            parsed = parse_kma_climate_csv_path(path)
            kind = parsed.get("kind")
            station = parsed.get("station_name")
            if kind and station:
                index[(kind, station.strip())] = parsed
        except Exception as exc:
            errors.append(f"{path.name}: {exc}")
    return index, errors


def find_climate_for_station(index: dict, kind: str, selected_label: str) -> Optional[dict]:
    base = station_base_name(selected_label)
    aliases = STATION_NAME_ALIASES.get(base, [base])

    for alias in aliases:
        key = (kind, alias)
        if key in index:
            return index[key]

    # 파일의 지점명이 조금 다를 경우 부분일치 허용
    for (k, station), parsed in index.items():
        if k != kind:
            continue
        for alias in aliases:
            if alias in station or station in alias:
                return parsed
    return None


def climate_table_to_monthly_records(
    parsed: Optional[dict],
    start_year: int,
    end_year: int,
    value_name: str,
) -> pd.DataFrame:
    """포털의 연도 x 12개월 표를 연도/월 long-form으로 변환."""
    records = []
    lookup = {}
    if parsed is not None:
        df = parsed["data"].set_index("연도")
        for yr in df.index:
            for m in range(1, 13):
                col = f"{m}월"
                lookup[(int(yr), m)] = safe_climate_number(df.at[yr, col]) if col in df.columns else np.nan

    for yr in range(int(start_year), int(end_year) + 1):
        for m in range(1, 13):
            records.append({"연도": yr, "월": m, value_name: lookup.get((yr, m), np.nan)})
    return pd.DataFrame(records)


def climate_value_coverage(parsed: Optional[dict]) -> dict:
    """공식 CSV에서 실제 숫자값이 존재하는 최초/최종 연월과 개수를 반환한다."""
    if not parsed or not isinstance(parsed.get("data"), pd.DataFrame):
        return {"count": 0, "first": None, "last": None, "label": "자료없음"}

    df = parsed["data"].copy()
    found = []
    for _, row in df.iterrows():
        try:
            yr = int(row.get("연도"))
        except Exception:
            continue
        for m in range(1, 13):
            col = f"{m}월"
            if col not in df.columns:
                continue
            val = safe_climate_number(row.get(col))
            if pd.notna(val):
                found.append((yr, m, float(val)))

    if not found:
        return {"count": 0, "first": None, "last": None, "label": "자료없음"}

    found.sort(key=lambda x: (x[0], x[1]))
    first = (found[0][0], found[0][1])
    last = (found[-1][0], found[-1][1])
    return {
        "count": len(found),
        "first": first,
        "last": last,
        "label": f"{first[0]}-{first[1]:02d} ~ {last[0]}-{last[1]:02d}",
    }


def build_climate_monthly(
    selected_label: str,
    start_year: int,
    end_year: int,
) -> Tuple[pd.DataFrame, dict]:
    index, errors = build_climate_file_index()
    fog = find_climate_for_station(index, "안개", selected_label)
    thunder = find_climate_for_station(index, "뇌전", selected_label)
    freezing = find_climate_for_station(index, "결빙", selected_label)

    fg = climate_table_to_monthly_records(
        fog, start_year, end_year, "안개일수_월간"
    )
    th = climate_table_to_monthly_records(
        thunder, start_year, end_year, "뇌전일수_월간"
    )
    fr = climate_table_to_monthly_records(
        freezing, start_year, end_year, "결빙일수_월간"
    )
    merged = pd.merge(fg, th, on=["연도", "월"], how="outer")
    merged = pd.merge(merged, fr, on=["연도", "월"], how="outer").sort_values(["연도", "월"])

    status = {
        "fog": fog,
        "thunder": thunder,
        "freezing": freezing,
        "fog_coverage": climate_value_coverage(fog),
        "thunder_coverage": climate_value_coverage(thunder),
        "freezing_coverage": climate_value_coverage(freezing),
        "errors": errors,
        "file_count": len(index),
    }
    return merged, status


def save_uploaded_climate_files(uploaded_files) -> list[str]:
    messages = []
    for uploaded in uploaded_files or []:
        raw = uploaded.getvalue()
        try:
            parsed = parse_kma_climate_csv_bytes(raw, uploaded.name)
            kind = parsed.get("kind")
            station = parsed.get("station_name")
            if not kind or not station:
                messages.append(f"❌ {uploaded.name}: 종류 또는 지점명을 판별하지 못했습니다.")
                continue
            safe_station = re.sub(r"[^0-9A-Za-z가-힣_-]+", "_", station)
            out_name = f"{kind}일수_{safe_station}.csv"
            out_path = CLIMATE_DIR / out_name
            out_path.write_bytes(raw)
            messages.append(f"✅ {uploaded.name} → {out_name} 저장")
        except Exception as exc:
            messages.append(f"❌ {uploaded.name}: {exc}")
    return messages


