@st.cache_data(show_spinner=False)
def load_hourly_local():
    paths = [BASE_DIR / "hourly_wind.csv", Path("hourly_wind.csv")]
    path = next((p for p in paths if p.exists()), None)
    if path is None:
        return None, "hourly_wind.csv 없음"

    for enc in ("cp949", "utf-8-sig", "utf-8", "euc-kr"):
        try:
            return pd.read_csv(path, encoding=enc, low_memory=False), "성공"
        except Exception:
            continue
    return None, "hourly_wind.csv 인코딩 실패"


@st.cache_data(show_spinner=False)
def load_daily_local():
    csv_paths = [BASE_DIR / "daily_weather.csv", Path("daily_weather.csv")]
    for path in csv_paths:
        if path.exists():
            for enc in ("cp949", "utf-8-sig", "utf-8", "euc-kr"):
                try:
                    return pd.read_csv(path, encoding=enc, low_memory=False), "CSV 성공"
                except Exception:
                    continue

    xlsx_paths = [BASE_DIR / "daily_weather.xlsx", Path("daily_weather.xlsx")]
    for path in xlsx_paths:
        if path.exists():
            try:
                return pd.read_excel(path), "XLSX 성공"
            except Exception as exc:
                return None, f"엑셀 오류: {exc}"
    return None, "일자료 파일 없음"



WIND16_ORDER = [
    "N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE",
    "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW",
]
WINDROSE_SPEED_BINS = [
    ("0.5~3.3", 0.5, 3.3),
    ("3.4~7.9", 3.4, 7.9),
    ("8.0~13.8", 8.0, 13.8),
    ("13.9이상", 13.9, None),
]
WINDROSE_PERIODS = [
    # 보고서 표기순서: 계절 4개 → 전년
    ("봄", "3~5월", [3, 4, 5]),
    ("여름", "6~8월", [6, 7, 8]),
    ("가을", "9~11월", [9, 10, 11]),
    ("겨울", "12~2월", [12, 1, 2]),
    ("전년", "1~12월", list(range(1, 13))),
]


def _classify_windrose_speed(ws):
    if pd.isna(ws):
        return None
    try:
        v = float(ws)
    except Exception:
        return None
    if v < 0.5:
        return "CALM"
    for label, lo, hi in WINDROSE_SPEED_BINS:
        if hi is None and v >= lo:
            return label
        if hi is not None and lo <= v <= hi:
            return label
    return None


def build_windrose_occurrence_table(df_hourly, station_name, start_year, end_year):
    """hourly_wind.csv에서 계급별 관측백분율 표와 바람장미도용 데이터를 만든다."""
    empty_result = pd.DataFrame()
    status = {"ok": False, "message": "hourly_wind.csv 자료가 없습니다.", "periods": {}}
    if df_hourly is None or df_hourly.empty:
        return empty_result, status

    work = df_hourly.copy()
    work.columns = [str(c).strip() for c in work.columns]

    stn_col = next((c for c in work.columns if "지점명" in c), None)
    date_col = next((c for c in work.columns if "일시" in c or "시간" in c), None)
    ws_col = next((c for c in work.columns if "풍속" in c and "풍향" not in c), None)
    wd_col = next((c for c in work.columns if "풍향" in c), None)
    if not all([stn_col, date_col, ws_col, wd_col]):
        return empty_result, {
            "ok": False,
            "message": "hourly_wind.csv에서 지점명/일시/풍속/풍향 열을 찾지 못했습니다.",
            "periods": {},
        }

    base = station_base_name(station_name)
    h = work[work[stn_col].astype(str).str.contains(base, na=False)].copy()
    if h.empty:
        return empty_result, {
            "ok": False,
            "message": f"hourly_wind.csv에서 {station_name} 자료를 찾지 못했습니다.",
            "periods": {},
        }

    h["일시_dt"] = pd.to_datetime(h[date_col], errors="coerce")
    h = h.dropna(subset=["일시_dt"]).copy()
    if h.empty:
        return empty_result, {
            "ok": False,
            "message": "hourly_wind.csv의 일시 형식을 읽지 못했습니다.",
            "periods": {},
        }

    h["연도"] = h["일시_dt"].dt.year.astype(int)
    h["월"] = h["일시_dt"].dt.month.astype(int)
    h = h[h["연도"].between(int(start_year), int(end_year))].copy()
    if h.empty:
        return empty_result, {
            "ok": False,
            "message": f"선택 기간({start_year}~{end_year})에 해당하는 시간풍 자료가 없습니다.",
            "periods": {},
        }

    h["풍속값"] = pd.to_numeric(h[ws_col], errors="coerce")
    h["풍향값"] = pd.to_numeric(h[wd_col], errors="coerce")
    h = h.dropna(subset=["풍속값"]).copy()
    h["방위"] = h["풍향값"].apply(deg_to_16dir)
    h["풍속계급"] = h["풍속값"].apply(_classify_windrose_speed)
    h = h[h["풍속계급"].notna()].copy()
    if h.empty:
        return empty_result, {
            "ok": False,
            "message": "풍속계급을 만들 수 있는 유효한 시간풍 자료가 없습니다.",
            "periods": {},
        }

    speed_labels = [x[0] for x in WINDROSE_SPEED_BINS]
    display_rows = []
    period_map = {}

    for period_name, month_label, months in WINDROSE_PERIODS:
        sub = h[h["월"].isin(months)].copy()
        if sub.empty:
            continue
        total = len(sub)
        calm_mask = (sub["풍속계급"] == "CALM") | (sub["방위"] == "")
        calm_pct = float(calm_mask.sum()) / total * 100.0 if total else 0.0

        plot_df = pd.DataFrame(0.0, index=WIND16_ORDER, columns=speed_labels)
        directional = sub[~calm_mask].copy()
        if not directional.empty:
            counts = directional.groupby(["방위", "풍속계급"]).size().unstack(fill_value=0)
            for d in WIND16_ORDER:
                for label in speed_labels:
                    if d in counts.index and label in counts.columns:
                        plot_df.loc[d, label] = float(counts.loc[d, label]) / total * 100.0

        for i, label in enumerate(speed_labels):
            row = {
                "구분": period_name,
                "월": month_label,
                "풍향/풍속": label,
                "CALM": round(calm_pct, 2) if i == 0 else 0.0,
            }
            subtotal = row["CALM"]
            for d in WIND16_ORDER:
                val = round(float(plot_df.loc[d, label]), 2)
                row[d] = val
                subtotal += val
            row["소계"] = round(subtotal, 2)
            display_rows.append(row)

        total_row = {
            "구분": period_name,
            "월": month_label,
            "풍향/풍속": "계",
            "CALM": round(calm_pct, 2),
        }
        subtotal = total_row["CALM"]
        for d in WIND16_ORDER:
            v = round(float(plot_df.loc[d].sum()), 2)
            total_row[d] = v
            subtotal += v
        total_row["소계"] = round(subtotal, 2)
        display_rows.append(total_row)

        period_map[period_name] = {
            "months": month_label,
            "total_obs": int(total),
            "calm_pct": round(calm_pct, 2),
            "plot_df": plot_df.round(2),
        }

    if not display_rows:
        return empty_result, {
            "ok": False,
            "message": "계절별 바람장미도용 자료를 만들지 못했습니다.",
            "periods": {},
        }

    table = pd.DataFrame(display_rows)
    desired_cols = [
        "구분", "월", "풍향/풍속", "CALM", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE",
        "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW", "N", "소계"
    ]
    for c in desired_cols:
        if c not in table.columns:
            table[c] = np.nan
    table = table[desired_cols]

    period_text = ", ".join(f"{k}({v['total_obs']}개 관측)" for k, v in period_map.items())
    return table, {
        "ok": True,
        "message": f"계급별 관측백분율 생성 완료 · {period_text}",
        "periods": period_map,
    }


def build_windrose_yearly_tables(
    hourly_df: pd.DataFrame,
    station_name: str,
    start_year: int,
    end_year: int,
) -> dict:
    """선택 기간의 각 연도별 계급별 관측백분율 표를 만든다.

    Excel의 '연도별 관측백분율' 한 시트에 여러 연도를 순서대로
    쌓아 넣기 위한 자료이다.
    """
    if hourly_df is None or getattr(hourly_df, "empty", True):
        return {}

    work = hourly_df.copy()
    date_col = next((c for c in work.columns if "일시" in str(c) or "시간" in str(c)), None)
    if date_col is None:
        return {}

    dt = pd.to_datetime(work[date_col], errors="coerce")
    result = {}
    for year in range(int(start_year), int(end_year) + 1):
        mask = dt.dt.year.eq(int(year))
        if not bool(mask.any()):
            continue
        sub = work.loc[mask].copy()
        table_y, status_y = build_windrose_occurrence_table(
            sub,
            station_name,
            int(year),
            int(year),
        )
        if status_y.get("ok") and table_y is not None and not table_y.empty:
            result[int(year)] = table_y
    return result



def _windrose_fmt_pct(value, total_row=False):
    """보고서용 숫자표기: 0은 '-', 나머지는 2자리, 합계 100은 100.0."""
    try:
        if pd.isna(value):
            return "-"
        v = float(value)
    except Exception:
        return str(value)
    if abs(v) < 0.005:
        return "-"
    if total_row and abs(v - 100.0) < 0.05:
        return "100.0"
    return f"{v:.2f}"


def _windrose_report_order(table: pd.DataFrame) -> pd.DataFrame:
    if table is None or table.empty:
        return pd.DataFrame()
    x = table.copy()
    period_order = ["봄", "여름", "가을", "겨울", "전년"]
    speed_order = ["0.5~3.3", "3.4~7.9", "8.0~13.8", "13.9이상", "계"]
    x["_p"] = x["구분"].map({p: i for i, p in enumerate(period_order)}).fillna(99)
    x["_s"] = x["풍향/풍속"].map({s: i for i, s in enumerate(speed_order)}).fillna(99)
    x = x.sort_values(["_p", "_s"]).drop(columns=["_p", "_s"]).reset_index(drop=True)
    return x


def render_windrose_report_html(table: pd.DataFrame, station_name: str, start_year: int, end_year: int) -> str:
    """두 번째 참고사진처럼 계절/월 셀을 병합한 보고서형 HTML 표."""
    x = _windrose_report_order(table)
    if x.empty:
        return ""

    dir_cols = ["CALM", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE", "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW", "N", "소계"]
    groups = []
    for period in ["봄", "여름", "가을", "겨울", "전년"]:
        g = x[x["구분"] == period].copy()
        if not g.empty:
            groups.append((period, g))

    css = """
    <style>
      .wr-wrap{width:100%; overflow-x:auto; margin-top:6px;}
      table.wr-report{border-collapse:collapse; width:100%; min-width:1480px; table-layout:fixed; font-size:12px; color:#222; background:white;}
      .wr-report th,.wr-report td{border:1px dotted #777; padding:5px 4px; text-align:center; vertical-align:middle; white-space:nowrap;}
      .wr-report thead th{background:#f7f7f7; font-weight:700; border-top:1.5px solid #222; border-bottom:1.5px solid #222;}
      .wr-report .grp{font-weight:700; background:#fbfbfb; width:42px;}
      .wr-report .month{font-weight:600; width:50px;}
      .wr-report .speed{font-weight:600; width:72px;}
      .wr-report .sumrow td{font-weight:700; background:#fcfcfc; border-bottom:1.5px solid #222;}
      .wr-report .group-start td{border-top:1.5px solid #222;}
      .wr-report .subtotal{font-weight:700;}
      .wr-title{font-size:14px; font-weight:700; margin:8px 0 6px 0;}
      .wr-source{font-size:11px; color:#555; margin-top:5px;}
    </style>
    """

    out = [css, '<div class="wr-title">계절별 풍속에 의한 계급별 풍향 출현백분율(%)</div>', '<div class="wr-wrap"><table class="wr-report">']
    out.append('<thead><tr>')
    out.append('<th style="width:44px">구분</th><th style="width:52px">월</th><th style="width:76px">풍속<br>(m/s)</th>')
    for c in dir_cols:
        out.append(f'<th>{c}</th>')
    out.append('</tr></thead><tbody>')

    for period, g in groups:
        rows = g.to_dict('records')
        rowspan = len(rows)
        month_label = str(rows[0].get('월', '')) if rows else ''
        for i, row in enumerate(rows):
            is_sum = str(row.get('풍향/풍속')) == '계'
            cls = []
            if i == 0:
                cls.append('group-start')
            if is_sum:
                cls.append('sumrow')
            out.append(f'<tr class="{" ".join(cls)}">')
            if i == 0:
                out.append(f'<td class="grp" rowspan="{rowspan}">{period}</td>')
                out.append(f'<td class="month" rowspan="{rowspan}">{month_label}</td>')
            speed = str(row.get('풍향/풍속', ''))
            speed_text = '→ 13.9' if speed == '13.9이상' else speed
            out.append(f'<td class="speed">{speed_text}</td>')
            for c in dir_cols:
                out.append(f'<td class="{"subtotal" if c == "소계" else ""}">{_windrose_fmt_pct(row.get(c), total_row=is_sum)}</td>')
            out.append('</tr>')

    out.append('</tbody></table></div>')
    base = station_base_name(station_name)
    out.append(f'<div class="wr-source">자료 : 기상청 시간풍 자료 · {base} · {int(start_year)}~{int(end_year)}년</div>')
    return ''.join(out)


def build_windrose_report_excel_bytes(
    table: pd.DataFrame,
    station_name: str,
    start_year: int,
    end_year: int,
    yearly_tables: Optional[dict] = None,
) -> bytes:
    """계급별 관측백분율 Excel 보고서.

    - '계급별 관측백분율' : 사용자가 지정한 전체 기간의 종합값
    - '연도별 관측백분율' : 시작~종료연도의 각 연도 표를 한 시트에 같은 양식으로 연속 배치
    """
    from openpyxl import Workbook
    from openpyxl.styles import Alignment, Border, Side, Font, PatternFill
    from openpyxl.utils import get_column_letter

    cols = [
        "구분", "월", "풍속(m/s)", "CALM",
        "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE",
        "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW", "N", "소계"
    ]
    value_cols = [
        "CALM", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE",
        "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW", "N", "소계"
    ]
    ncols = len(cols)

    thin = Side(style="thin", color="666666")
    medium = Side(style="medium", color="222222")
    dotted = Side(style="dotted", color="777777")
    title_font = Font(name="돋움", size=12, bold=True)
    header_font = Font(name="돋움", size=9, bold=True)
    body_font = Font(name="돋움", size=9)
    source_font = Font(name="돋움", size=8)

    def _write_block(ws, source_table, start_row, block_title, source_text):
        x = _windrose_report_order(source_table)
        if x.empty:
            return start_row

        # 제목
        ws.merge_cells(
            start_row=start_row, start_column=1,
            end_row=start_row, end_column=ncols
        )
        ws.cell(start_row, 1, block_title)
        ws.cell(start_row, 1).font = title_font
        ws.cell(start_row, 1).alignment = Alignment(horizontal="left", vertical="center")

        header_row = start_row + 2
        for j, c in enumerate(cols, 1):
            cell = ws.cell(header_row, j, c)
            cell.font = header_font
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            cell.fill = PatternFill("solid", fgColor="F2F2F2")
            cell.border = Border(left=dotted, right=dotted, top=medium, bottom=medium)

        r = header_row + 1
        for period in ["봄", "여름", "가을", "겨울", "전년"]:
            g = x[x["구분"] == period].copy()
            if g.empty:
                continue

            start_r = r
            for _, row in g.iterrows():
                speed = str(row.get("풍향/풍속", ""))
                is_sum = speed == "계"

                ws.cell(r, 3, "→ 13.9" if speed == "13.9이상" else speed)
                ws.cell(r, 3).font = header_font if is_sum else body_font

                for j, c in enumerate(value_cols, 4):
                    v = row.get(c)
                    cell = ws.cell(r, j)
                    if pd.isna(v) or abs(float(v)) < 0.005:
                        cell.value = "-"
                    else:
                        cell.value = float(v)
                        cell.number_format = "0.00"
                    cell.font = header_font if is_sum else body_font

                for c in range(3, ncols + 1):
                    ws.cell(r, c).alignment = Alignment(
                        horizontal="center", vertical="center"
                    )
                r += 1

            end_r = r - 1
            ws.merge_cells(start_row=start_r, start_column=1, end_row=end_r, end_column=1)
            ws.merge_cells(start_row=start_r, start_column=2, end_row=end_r, end_column=2)
            ws.cell(start_r, 1, period)
            ws.cell(start_r, 2, str(g.iloc[0]["월"]))

            for c in (1, 2):
                ws.cell(start_r, c).alignment = Alignment(
                    horizontal="center", vertical="center"
                )
                ws.cell(start_r, c).font = header_font if c == 1 else body_font

            for rr in range(start_r, end_r + 1):
                for cc in range(1, ncols + 1):
                    cell = ws.cell(rr, cc)
                    top = medium if rr == start_r else dotted
                    bottom = medium if rr == end_r else dotted
                    cell.border = Border(
                        left=dotted, right=dotted, top=top, bottom=bottom
                    )
                    if cell.font is None:
                        cell.font = body_font

        source_row = r + 1
        ws.merge_cells(
            start_row=source_row, start_column=1,
            end_row=source_row, end_column=ncols
        )
        ws.cell(source_row, 1, source_text)
        ws.cell(source_row, 1).font = source_font

        return source_row + 3

    wb = Workbook()

    # 1) 선택기간 종합 시트
    ws = wb.active
    ws.title = "계급별 관측백분율"
    _write_block(
        ws,
        table,
        1,
        "계절별 풍속에 의한 계급별 풍향 출현백분율(%)",
        f"자료 : 기상청 시간풍 자료 ({station_base_name(station_name)}, {int(start_year)}~{int(end_year)}년)",
    )

    # 2) 연도별 전체 결과 시트 - 시트는 하나만 추가하고 연도별 표를 아래로 이어 붙임
    yearly_tables = yearly_tables or {}
    if yearly_tables:
        ws_y = wb.create_sheet("연도별 관측백분율")
        row_cursor = 1
        for year in sorted(yearly_tables):
            t = yearly_tables.get(year)
            if t is None or getattr(t, "empty", True):
                continue
            row_cursor = _write_block(
                ws_y,
                t,
                row_cursor,
                f"{int(year)}년 계절별 풍속에 의한 계급별 풍향 출현백분율(%)",
                f"자료 : 기상청 시간풍 자료 ({station_base_name(station_name)}, {int(year)}년)",
            )
    else:
        ws_y = wb.create_sheet("연도별 관측백분율")
        ws_y["A1"] = "연도별 관측백분율 자료가 없습니다."
        ws_y["A1"].font = body_font

    # 공통 서식
    for ws_item in wb.worksheets:
        widths = {1: 7, 2: 8, 3: 11}
        for cc in range(1, ncols + 1):
            ws_item.column_dimensions[get_column_letter(cc)].width = widths.get(cc, 8.5)
        ws_item.sheet_view.showGridLines = False
        ws_item.page_setup.orientation = "landscape"
        ws_item.page_setup.fitToWidth = 1
        ws_item.page_setup.fitToHeight = 0
        ws_item.sheet_properties.pageSetUpPr.fitToPage = True
        ws_item.freeze_panes = "D4"

    bio = io.BytesIO()
    wb.save(bio)
    bio.seek(0)
    return bio.getvalue()


def draw_windrose_figure(plot_df: pd.DataFrame, title: str, calm_pct: float = 0.0):
    if plot_df is None or plot_df.empty:
        return None

    plt.rcParams["font.family"] = ["Malgun Gothic", "AppleGothic", "NanumGothic", "DejaVu Sans"]
    plt.rcParams["axes.unicode_minus"] = False

    dirs = WIND16_ORDER
    theta = np.deg2rad(np.arange(0, 360, 360 / len(dirs)))
    width = np.deg2rad(360 / len(dirs) * 0.82)

    fig = plt.figure(figsize=(8.2, 8.2))
    ax = fig.add_subplot(111, projection="polar")
    ax.set_theta_zero_location("N")
    ax.set_theta_direction(-1)

    bottom = np.zeros(len(dirs))
    speed_labels = [x[0] for x in WINDROSE_SPEED_BINS]
    for label in speed_labels:
        values = plot_df.reindex(dirs)[label].fillna(0.0).to_numpy(dtype=float)
        ax.bar(theta, values, width=width, bottom=bottom, align="center", edgecolor="white", linewidth=0.8, label=label)
        bottom += values

    ax.set_xticks(theta)
    ax.set_xticklabels(dirs)
    max_r = float(np.nanmax(bottom)) if len(bottom) else 0.0
    upper = max(5.0, np.ceil(max_r / 5.0) * 5.0)
    ax.set_ylim(0, upper)
    rticks = np.linspace(upper / 5, upper, 5)
    ax.set_yticks(rticks)
    ax.set_yticklabels([f"{x:.0f}%" for x in rticks])
    ax.set_rlabel_position(22.5)
    ax.grid(True, alpha=0.5)
    ax.set_title(f"{title}\nCALM {calm_pct:.2f}%", pad=28, fontsize=13)
    ax.legend(loc="upper right", bbox_to_anchor=(1.22, 1.12), title="풍속계급")
    fig.tight_layout()
    return fig


def build_windrose_dxf_bytes(plot_df: pd.DataFrame, title: str, calm_pct: float = 0.0):
    """AutoCAD에서 열 수 있는 DXF 바람장미도를 만든다."""
    if ezdxf is None or plot_df is None or plot_df.empty:
        return None

    try:
        doc = ezdxf.new("R2010")
        msp = doc.modelspace()

        # 레이어
        layer_defs = {
            "GRID": 8,
            "AXIS": 7,
            "TEXT": 7,
            "BAND1": 1,
            "BAND2": 3,
            "BAND3": 5,
            "BAND4": 6,
        }
        for lname, color in layer_defs.items():
            if lname not in doc.layers:
                doc.layers.add(lname, color=color)

        dirs = WIND16_ORDER
        speed_labels = [x[0] for x in WINDROSE_SPEED_BINS]
        radius_scale = 3.0  # 1% = 3 drawing units
        ring_step = 5.0 * radius_scale
        max_r_pct = float(np.nanmax(plot_df.sum(axis=1).to_numpy(dtype=float))) if not plot_df.empty else 0.0
        max_r_pct = max(max_r_pct, 5.0)
        outer_r = max(20.0, np.ceil(max_r_pct / 5.0) * 5.0 * radius_scale)

        # 제목/설명
        msp.add_text(title, dxfattribs={"height": 4.5, "layer": "TEXT"}).set_placement(( -outer_r, outer_r + 20))
        msp.add_text(f"CALM {calm_pct:.2f}%", dxfattribs={"height": 3.2, "layer": "TEXT"}).set_placement((-outer_r, outer_r + 13))
        msp.add_text("풍속계급: 0.5~3.3 / 3.4~7.9 / 8.0~13.8 / 13.9이상", dxfattribs={"height": 2.8, "layer": "TEXT"}).set_placement((-outer_r, -outer_r - 18))

        # 동심원 격자
        n_rings = max(4, int(round(outer_r / ring_step)))
        for i in range(1, n_rings + 1):
            rr = i * ring_step
            msp.add_circle((0, 0), rr, dxfattribs={"layer": "GRID"})
            msp.add_text(f"{int(round(rr / radius_scale))}%", dxfattribs={"height": 2.2, "layer": "TEXT"}).set_placement((1.5, rr + 0.8))

        # 방위축/라벨
        for idx, d in enumerate(dirs):
            ang_deg = 90.0 - idx * 22.5
            ang = np.deg2rad(ang_deg)
            x = (outer_r + 3.0) * np.cos(ang)
            y = (outer_r + 3.0) * np.sin(ang)
            msp.add_line((0, 0), (outer_r * np.cos(ang), outer_r * np.sin(ang)), dxfattribs={"layer": "AXIS"})
            msp.add_text(d, dxfattribs={"height": 2.5, "layer": "TEXT"}).set_placement((x, y))

        # 막대 부채꼴
        colors = {speed_labels[0]: "BAND1", speed_labels[1]: "BAND2", speed_labels[2]: "BAND3", speed_labels[3]: "BAND4"}
        half_width = 22.5 * 0.82 / 2.0
        for idx, d in enumerate(dirs):
            center_deg = 90.0 - idx * 22.5
            bottom = 0.0
            for label in speed_labels:
                value = float(plot_df.reindex(dirs).loc[d, label])
                if value <= 0:
                    continue
                inner_r = bottom * radius_scale
                outer_band_r = (bottom + value) * radius_scale
                start_deg = center_deg - half_width
                end_deg = center_deg + half_width
                angles = np.linspace(start_deg, end_deg, 10)
                outer_pts = [(outer_band_r * np.cos(np.deg2rad(a)), outer_band_r * np.sin(np.deg2rad(a))) for a in angles]
                inner_angles = np.linspace(end_deg, start_deg, 10)
                if inner_r <= 0:
                    pts = [(0.0, 0.0)] + outer_pts
                else:
                    inner_pts = [(inner_r * np.cos(np.deg2rad(a)), inner_r * np.sin(np.deg2rad(a))) for a in inner_angles]
                    pts = outer_pts + inner_pts
                msp.add_lwpolyline(pts, format="xy", close=True, dxfattribs={"layer": colors[label]})
                try:
                    hatch = msp.add_hatch(color=doc.layers.get(colors[label]).color, dxfattribs={"layer": colors[label]})
                    hatch.paths.add_polyline_path(pts, is_closed=True)
                except Exception:
                    pass
                bottom += value

        # 범례
        legend_x = outer_r + 18
        legend_y = outer_r
        for i, label in enumerate(speed_labels):
            y = legend_y - i * 8
            layer = colors[label]
            pts = [(legend_x, y), (legend_x + 6, y), (legend_x + 6, y - 4), (legend_x, y - 4)]
            msp.add_lwpolyline(pts, format="xy", close=True, dxfattribs={"layer": layer})
            try:
                hatch = msp.add_hatch(color=doc.layers.get(layer).color, dxfattribs={"layer": layer})
                hatch.paths.add_polyline_path(pts, is_closed=True)
            except Exception:
                pass
            msp.add_text(label, dxfattribs={"height": 2.5, "layer": "TEXT"}).set_placement((legend_x + 8, y - 3))

        with tempfile.NamedTemporaryFile(delete=False, suffix=".dxf") as tmp:
            tmp_path = tmp.name
        doc.saveas(tmp_path)
        data = Path(tmp_path).read_bytes()
        try:
            os.remove(tmp_path)
        except Exception:
            pass
        return data
    except Exception:
        return None


CALM_FIXED_DIAMETER = 8.0  # 실제 바람장미도 중심 CALM 원 지름
LEGEND_CALM_DIAMETER = 3.0  # LEGEND용 CALM 원: 다른 범례기호 길이(3.0)와 동일


def _windrose_rect_points(cx, cy, angle_deg, r0, r1, width):
    """방사방향 직사각형 4점."""
    a = np.deg2rad(angle_deg)
    ux, uy = np.cos(a), np.sin(a)
    px, py = -uy, ux
    hw = width / 2.0
    return [
        (cx + r0 * ux + hw * px, cy + r0 * uy + hw * py),
        (cx + r1 * ux + hw * px, cy + r1 * uy + hw * py),
        (cx + r1 * ux - hw * px, cy + r1 * uy - hw * py),
        (cx + r0 * ux - hw * px, cy + r0 * uy - hw * py),
    ]


def build_windrose_template_dxf_bytes(periods: dict, station_label: str, start_year: int, end_year: int):
    """
    제공된 기존 CAD 바람장미도 양식을 재현한다.

    풍속계급별 표현:
    - CALM       : 중심 원 안의 정온 빈도 숫자
    - 0.5~3.3    : 단일 선
    - 3.4~7.9    : 폭 1의 가는 사각형
    - 8.0~13.8   : 폭 2의 사각형
    - 13.9 이상  : 폭 3의 사각형

    각 구간의 방사길이 = 계급별 관측백분율 표의 소수점 둘째 자리 값 × 2로 사용한다. 즉 4.3447%도 표에 4.34로 표시되므로 CAD 길이는 8.68이다.
    CALM 원의 지름은 8.0 CAD unit으로 고정하고, 실제 CALM 값은 원 안에 숫자로 표기한다.
    모든 풍속계급 도형은 중심점이 아니라 CALM 원 외곽(R=4.0)에서 시작한다.
    사각형의 폭은 LEGEND와 실제 바람장미도에서 동일하게 1 / 2 / 3 CAD unit을 사용하고, LEGEND의 CALM 원 지름은 3.0으로 표시한다.
    """
    if ezdxf is None or not isinstance(periods, dict) or not periods:
        return None

    try:
        doc = ezdxf.new("R2010")
        doc.header["$INSUNITS"] = 4  # mm
        msp = doc.modelspace()

        # AutoCAD 텍스트는 Windows 기본 '돋움' 글꼴을 사용.
        try:
            if "DOTUM" not in doc.styles:
                doc.styles.add("DOTUM", font="dotum.ttc")
        except Exception:
            pass

        layer_defs = {
            "FRAME": 2,
            "ROSE": 7,
            "TEXT": 7,
            "LEGEND": 7,
        }
        for lname, color in layer_defs.items():
            if lname not in doc.layers:
                doc.layers.add(lname, color=color)

        centers = {
            "전년": (45.0, 185.0),
            "봄": (45.0, 115.0),
            "여름": (115.0, 115.0),
            "가을": (45.0, 45.0),
            "겨울": (115.0, 45.0),
        }
        english = {
            "전년": "ANNUAL",
            "봄": "SPRING",
            "여름": "SUMMER",
            "가을": "AUTUMN",
            "겨울": "WINTER",
        }
        dirs = WIND16_ORDER
        speed_labels = [x[0] for x in WINDROSE_SPEED_BINS]
        if len(speed_labels) < 4:
            return None

        length_scale = 2.0  # 1% = 2 CAD unit
        widths = {
            speed_labels[1]: 1.0,
            speed_labels[2]: 2.0,
            speed_labels[3]: 3.0,
        }

        def add_text(txt, xy, height=2.5, layer="TEXT", korean=False, center=False):
            attrs = {"height": height, "layer": layer}
            if "DOTUM" in doc.styles:
                attrs["style"] = "DOTUM"
            ent = msp.add_text(str(txt), dxfattribs=attrs)
            try:
                if center:
                    from ezdxf.enums import TextEntityAlignment
                    ent.set_placement(xy, align=TextEntityAlignment.MIDDLE_CENTER)
                else:
                    ent.set_placement(xy)
            except Exception:
                pass
            return ent

        def add_open_rect(cx, cy, angle_deg, r0, r1, width):
            if r1 <= r0 + 1e-9:
                return
            pts = _windrose_rect_points(cx, cy, angle_deg, r0, r1, width)
            msp.add_lwpolyline(pts, format="xy", close=True, dxfattribs={"layer": "ROSE"})

        def add_rose(period_name, info):
            if period_name not in centers or not isinstance(info, dict):
                return
            plot_df = info.get("plot_df")
            if plot_df is None or getattr(plot_df, "empty", True):
                return

            cx, cy = centers[period_name]
            p = plot_df.reindex(index=dirs, columns=speed_labels).fillna(0.0)

            # CALM: 원 크기는 값과 무관하게 고정. 실제 정온율은 원 안 숫자로 표시.
            calm = max(0.0, float(info.get("calm_pct", 0.0) or 0.0))
            calm_radius = CALM_FIXED_DIAMETER / 2.0
            msp.add_circle((cx, cy), calm_radius, dxfattribs={"layer": "ROSE"})
            add_text(f"{calm:.2f}", (cx, cy), height=1.9, center=True)

            for idx, d in enumerate(dirs):
                angle_deg = 90.0 - idx * 22.5
                a = np.deg2rad(angle_deg)
                ux, uy = np.cos(a), np.sin(a)

                try:
                    vals = [round(max(0.0, float(p.loc[d, lab])), 2) for lab in speed_labels]
                except Exception:
                    vals = [0.0, 0.0, 0.0, 0.0]

                r = calm_radius

                # 1계급: 단일 선 — 선 길이 = 해당 관측백분율 × 2
                r1 = r + vals[0] * length_scale
                if r1 > r + 1e-9:
                    msp.add_line(
                        (cx + r * ux, cy + r * uy),
                        (cx + r1 * ux, cy + r1 * uy),
                        dxfattribs={"layer": "ROSE"},
                    )
                r = r1

                # 2~4계급: 계급이 커질수록 폭이 넓어지는 개방 사각형
                for lab, val in zip(speed_labels[1:], vals[1:]):
                    r_next = r + val * length_scale
                    if val > 0:
                        add_open_rect(cx, cy, angle_deg, r, r_next, widths[lab])
                    r = r_next

            # 계절명
            add_text(english[period_name], (cx - 10.0, cy - 27.0), height=3.2)

        for name in ["전년", "봄", "여름", "가을", "겨울"]:
            if name in periods:
                add_rose(name, periods[name])

        # 외곽 도곽
        frame_pts = [(0.0, 10.0), (160.0, 10.0), (160.0, 240.0), (0.0, 240.0)]
        msp.add_lwpolyline(frame_pts, format="xy", close=True, dxfattribs={"layer": "FRAME"})

        # 제목/지점/기간
        add_text("WIND ROSE", (55.0, 220.0), height=5.0)
        add_text(station_base_name(station_label), (97.0, 208.0), height=2.4, korean=True)
        add_text(f"{int(start_year)}~{int(end_year)}", (110.0, 208.0), height=2.4)

        # LEGEND
        add_text("LEGEND", (105.0, 201.0), height=3.2)
        legend_x = 90.0
        legend_y = 195.0
        sym_x0, sym_x1 = 90.0, 93.0
        txt_x = 96.0

        # CALM symbol
        msp.add_circle((92.0, legend_y + 1.2), LEGEND_CALM_DIAMETER / 2.0, dxfattribs={"layer": "LEGEND"})
        add_text(": FREQUENCY OF CALMS", (txt_x, legend_y), height=2.0)

        # class 1: line
        y = legend_y - 5.0
        msp.add_line((sym_x0, y + 1.2), (sym_x1, y + 1.2), dxfattribs={"layer": "LEGEND"})
        add_text(": 0.5 - 3.3 M/SEC", (txt_x, y), height=2.0)

        # class 2: narrow rectangle
        y -= 5.0
        box = [(sym_x0, y + 0.7), (sym_x1, y + 0.7), (sym_x1, y + 1.7), (sym_x0, y + 1.7)]
        msp.add_lwpolyline(box, format="xy", close=True, dxfattribs={"layer": "LEGEND"})
        add_text(": 3.4 - 7.9 M/SEC", (txt_x, y), height=2.0)

        # class 3: medium rectangle
        y -= 5.0
        box = [(sym_x0, y + 0.2), (sym_x1, y + 0.2), (sym_x1, y + 2.2), (sym_x0, y + 2.2)]
        msp.add_lwpolyline(box, format="xy", close=True, dxfattribs={"layer": "LEGEND"})
        add_text(": 8.0 - 13.8 M/SEC", (txt_x, y), height=2.0)

        # class 4: wide rectangle
        y -= 5.0
        box = [(sym_x0, y - 0.3), (sym_x1, y - 0.3), (sym_x1, y + 2.7), (sym_x0, y + 2.7)]
        msp.add_lwpolyline(box, format="xy", close=True, dxfattribs={"layer": "LEGEND"})
        add_text(": 13.9 M/SEC OVER &", (txt_x, y), height=2.0)
        add_text("27.0 KNOTS", (txt_x, y - 3.2), height=2.0)

        # SCALE 0~20, 1% minor tick + 5% major tick
        scale_x0, scale_y = 96.0, 159.0
        add_text("SCALE", (108.0, 165.0), height=3.0)
        scale_len = 20.0 * length_scale
        msp.add_line((scale_x0, scale_y), (scale_x0 + scale_len, scale_y), dxfattribs={"layer": "LEGEND"})
        for pct in range(0, 21):
            x = scale_x0 + pct * length_scale
            tick = 2.5 if pct % 5 == 0 else 1.5
            msp.add_line((x, scale_y), (x, scale_y - tick), dxfattribs={"layer": "LEGEND"})
            if pct % 5 == 0:
                add_text(str(pct), (x - 1.0, scale_y - 6.0), height=2.0)

        with tempfile.NamedTemporaryFile(delete=False, suffix=".dxf") as tmp:
            tmp_path = tmp.name
        doc.saveas(tmp_path)
        data = Path(tmp_path).read_bytes()
        try:
            os.remove(tmp_path)
        except Exception:
            pass
        return data
    except Exception:
        return None


def draw_windrose_template_preview(periods: dict, station_label: str, start_year: int, end_year: int):
    """DXF와 동일하게 CALM Ø8, 관측백분율 1:2, 원 외곽 시작 규칙을 Streamlit에서 미리보기."""
    if not isinstance(periods, dict) or not periods:
        return None

    try:
        # Streamlit 미리보기는 CAD용 돋움 글꼴에 의존하지 않는다.
        # SVG의 generic sans-serif를 브라우저가 운영체제 글꼴로 직접 대체한다.
        plt.rcParams["font.family"] = "sans-serif"
        plt.rcParams["axes.unicode_minus"] = False
        fig, ax = plt.subplots(figsize=(7.2, 10.5), dpi=150)
        fig.patch.set_facecolor("#20262d")
        ax.set_facecolor("#20262d")
        ax.set_xlim(-5, 165)
        ax.set_ylim(5, 245)
        ax.set_aspect("equal")
        ax.axis("off")

        fg = "white"
        frame_color = "#d8e500"
        text_zorder = 20
        centers = {
            "전년": (45.0, 185.0),
            "봄": (45.0, 115.0),
            "여름": (115.0, 115.0),
            "가을": (45.0, 45.0),
            "겨울": (115.0, 45.0),
        }
        english = {
            "전년": "ANNUAL", "봄": "SPRING", "여름": "SUMMER",
            "가을": "AUTUMN", "겨울": "WINTER",
        }
        dirs = WIND16_ORDER
        speed_labels = [x[0] for x in WINDROSE_SPEED_BINS]
        length_scale = 2.0
        widths = {speed_labels[1]: 1.0, speed_labels[2]: 2.0, speed_labels[3]: 3.0}

        from matplotlib.patches import Circle, Polygon, Rectangle

        def add_preview_text(x, y, text, fontsize, ha="left", va="center", fontweight="medium", **kwargs):
            """축소 렌더링에서도 사라지지 않도록 미리보기 문자를 최상위 레이어에 표시."""
            return ax.text(
                x,
                y,
                str(text),
                color=fg,
                ha=ha,
                va=va,
                fontsize=fontsize,
                fontweight=fontweight,
                alpha=1.0,
                zorder=text_zorder,
                clip_on=False,
                **kwargs,
            )

        def rect_patch(cx, cy, angle_deg, r0, r1, width, lw=0.8):
            pts = _windrose_rect_points(cx, cy, angle_deg, r0, r1, width)
            ax.add_patch(Polygon(pts, closed=True, fill=False, edgecolor=fg, linewidth=lw, zorder=3))

        def add_rose(name, info):
            if name not in centers or not isinstance(info, dict):
                return
            plot_df = info.get("plot_df")
            if plot_df is None or getattr(plot_df, "empty", True):
                return
            cx, cy = centers[name]
            p = plot_df.reindex(index=dirs, columns=speed_labels).fillna(0.0)
            calm = max(0.0, float(info.get("calm_pct", 0.0) or 0.0))
            calm_radius = CALM_FIXED_DIAMETER / 2.0
            ax.add_patch(Circle((cx, cy), calm_radius, fill=False, edgecolor=fg, linewidth=1.0, zorder=3))
            add_preview_text(
                cx,
                cy,
                f"{calm:.2f}",
                fontsize=10,
                ha="center",
                bbox={"facecolor": "#20262d", "edgecolor": "none", "pad": 0.15},
            )

            for idx, d in enumerate(dirs):
                angle_deg = 90.0 - idx * 22.5
                a = np.deg2rad(angle_deg)
                ux, uy = np.cos(a), np.sin(a)
                vals = [round(max(0.0, float(p.loc[d, lab])), 2) for lab in speed_labels]
                r = calm_radius
                r1 = r + vals[0] * length_scale
                if r1 > r + 1e-9:
                    ax.plot(
                        [cx + r*ux, cx + r1*ux],
                        [cy + r*uy, cy + r1*uy],
                        color=fg,
                        linewidth=0.9,
                        zorder=3,
                    )
                r = r1
                for lab, val in zip(speed_labels[1:], vals[1:]):
                    r_next = r + val * length_scale
                    if val > 0:
                        rect_patch(cx, cy, angle_deg, r, r_next, widths[lab])
                    r = r_next
            add_preview_text(cx, cy - 27.0, english[name], fontsize=11, ha="center")

        for name in ["전년", "봄", "여름", "가을", "겨울"]:
            if name in periods:
                add_rose(name, periods[name])

        # Frame
        ax.add_patch(Rectangle((0, 10), 160, 230, fill=False, edgecolor=frame_color, linewidth=1.2, zorder=2))

        # Title / station / years
        add_preview_text(80, 220, "WIND ROSE", fontsize=15, ha="center")
        add_preview_text(101, 208, station_base_name(station_label), fontsize=10, ha="right")
        add_preview_text(110, 208, f"{int(start_year)}~{int(end_year)}", fontsize=10)

        # Legend
        add_preview_text(113, 201, "LEGEND", fontsize=11, ha="center")
        lx0, lx1, tx = 90, 93, 95
        ly = 195
        ax.add_patch(Circle((92, ly+1.1), LEGEND_CALM_DIAMETER / 2.0, fill=False, edgecolor=fg, linewidth=0.9, zorder=3))
        add_preview_text(tx, ly+1.1, ": FREQUENCY OF CALMS", fontsize=9.5)
        ly -= 5
        ax.plot([lx0,lx1],[ly+1.1,ly+1.1],color=fg,linewidth=0.9,zorder=3)
        add_preview_text(tx, ly+1.1, ": 0.5 - 3.3 M/SEC", fontsize=9.5)
        ly -= 5
        ax.add_patch(Rectangle((lx0,ly+0.7),3,1.0,fill=False,edgecolor=fg,linewidth=0.9,zorder=3))
        add_preview_text(tx, ly+1.1, ": 3.4 - 7.9 M/SEC", fontsize=9.5)
        ly -= 5
        ax.add_patch(Rectangle((lx0,ly+0.2),3,2.0,fill=False,edgecolor=fg,linewidth=0.9,zorder=3))
        add_preview_text(tx, ly+1.1, ": 8.0 - 13.8 M/SEC", fontsize=9.5)
        ly -= 5
        ax.add_patch(Rectangle((lx0,ly-0.3),3,3.0,fill=False,edgecolor=fg,linewidth=0.9,zorder=3))
        add_preview_text(tx, ly+1.1, ": 13.9 M/SEC OVER &", fontsize=9.5)
        add_preview_text(tx, ly-1.8, "27.0 KNOTS", fontsize=9.5)

        # Scale
        sy=159
        sx=96
        add_preview_text(116, 165, "SCALE", fontsize=10, ha="center")
        ax.plot([sx,sx+20*length_scale],[sy,sy],color=fg,linewidth=0.9,zorder=3)
        for pct in range(21):
            x=sx+pct*length_scale
            tick=2.5 if pct%5==0 else 1.5
            ax.plot([x,x],[sy,sy-tick],color=fg,linewidth=0.7,zorder=3)
            if pct%5==0:
                add_preview_text(x, sy-5.0, str(pct), fontsize=9, ha="center")

        # tight_layout / Agg 사전 draw는 설치 글꼴을 조회하므로 사용하지 않는다.
        # 고정 여백을 사용해 SVG 텍스트가 Matplotlib 폰트 캐시에 의존하지 않게 한다.
        fig.subplots_adjust(left=0.03, right=0.97, bottom=0.03, top=0.97)
        return fig
    except Exception:
        return None


def render_windrose_preview_svg(fig):
    """문자를 SVG <text>로 유지해 브라우저가 시스템 글꼴로 직접 렌더링한다."""
    if fig is None:
        return None
    try:
        output = io.BytesIO()
        with warnings.catch_warnings():
            warnings.filterwarnings("ignore", message=r"Glyph .* missing from font")
            with matplotlib.rc_context({"svg.fonttype": "none"}):
                fig.savefig(
                    output,
                    format="svg",
                    dpi=150,
                    facecolor=fig.get_facecolor(),
                    edgecolor="none",
                    bbox_inches=None,
                    pad_inches=0,
                )
        svg_text = output.getvalue().decode("utf-8")
        if not svg_text or "<text" not in svg_text:
            return None
        browser_font_stack = (
            "'Malgun Gothic', '맑은 고딕', 'Apple SD Gothic Neo', "
            "'Noto Sans KR', 'Noto Sans CJK KR', Arial, sans-serif"
        )
        svg_text = re.sub(
            r"font-family:\s*[^;]+;",
            f"font-family: {browser_font_stack};",
            svg_text,
        )
        return svg_text.encode("utf-8")
    except Exception:
        return None



def _windrose_api_cache_path(stn_id: int, year: int) -> Path:
    return WINDROSE_API_CACHE_DIR / f"asos_hourly_wind_{int(stn_id)}_{int(year)}.pkl"


def _parse_api_items(data):
    body = data.get("response", {}).get("body", {}) if isinstance(data, dict) else {}
    items_obj = body.get("items", {}) if isinstance(body, dict) else {}
    items = items_obj.get("item", []) if isinstance(items_obj, dict) else []
    if isinstance(items, dict):
        items = [items]
    return items if isinstance(items, list) else []







def fetch_asos_hourly_wind_api(
    stn_id: int,
    station_label: str,
    start_year: int,
    end_year: int,
    service_key: str,
    force_refresh: bool = False,
) -> tuple[pd.DataFrame, dict]:
    """
    공공데이터포털 '기상청_지상(종관, ASOS) 시간자료 조회서비스'에서
    시간별 풍향(wd)·풍속(ws)을 수집한다.

    v46 핵심 수정
    ----------------
    이전 v44/v45는 numOfRows=1000을 사용했다. 실제 오류 화면을 보면
    2일 범위까지 줄여도 동일한 오류99가 반복되므로 '조회기간이 길어서'가 아니라
    numOfRows=1000 자체가 해당 게이트웨이에서 문제를 일으키는 것으로 판단한다.

    v46은 실제 사용 사례에서 안정적으로 쓰이는 구조로 변경:
    - 월별 조회(최대 744시간 정도)
    - numOfRows=900 기본
    - 오류99가 나오면 500 → 200으로 자동 축소
    - totalCount가 page size를 넘으면 pageNo 자동 증가
    - 최대 2개 연도 × 연도당 3개월 병렬
    - 정상 완료된 연도만 캐시
    - 실패 메시지는 월별 상태표로 요약
    """
    from concurrent.futures import ThreadPoolExecutor, as_completed
    import math

    key = urllib.parse.unquote(str(service_key or "").strip())
    if not key:
        return pd.DataFrame(), {
            "ok": False,
            "message": "공공데이터포털 API Key가 없습니다.",
            "year_status": pd.DataFrame(),
            "month_status": pd.DataFrame(),
        }

    url = "https://apis.data.go.kr/1360000/AsosHourlyInfoService/getWthrDataList"
    today = pd.Timestamp.now().normalize()
    years = list(range(int(start_year), int(end_year) + 1))

    def _cache_path_v46(year: int) -> Path:
        return WINDROSE_API_CACHE_DIR / (
            f"asos_hourly_wind_v46_{int(stn_id)}_{int(year)}.pkl"
        )

    def _csv_path(year: int) -> Path:
        # 사람이 Excel 등에서 바로 열어 연도별로 재사용할 수 있는 CSV 캐시
        return WINDROSE_API_CACHE_DIR / (
            f"asos_hourly_wind_{int(stn_id)}_{int(year)}.csv"
        )

    def _ensure_csv_cache(d: pd.DataFrame, year: int):
        if d is None or getattr(d, "empty", True):
            return None
        cp = _csv_path(year)
        try:
            d.to_csv(cp, index=False, encoding="utf-8-sig", date_format="%Y-%m-%d %H:%M:%S")
            return cp
        except Exception:
            return None

    def _friendly_error(code: str, msg: str) -> str:
        code = str(code or "").strip()
        msg = str(msg or "").strip()
        upper = msg.upper()

        if code == "99":
            return f"API 오류 99: {msg or '요청 제한 오류'}"
        if code == "20" or "SERVICE_ACCESS_DENIED" in upper:
            return (
                "시간자료 API 활용승인 없음(20). "
                "공공데이터포털에서 '기상청_지상(종관, ASOS) 시간자료 조회서비스' "
                "활용신청 여부를 확인하세요."
            )
        if code == "30" or "SERVICE_KEY_IS_NOT_REGISTERED" in upper:
            return "인증키 오류(30): 시간자료 API에 등록된 인증키인지 확인하세요."
        if code == "22" or "LIMITED_NUMBER" in upper:
            return "트래픽 한도 초과(22). 잠시 후 다시 시도하세요."
        if code == "10" or "INVALID_REQUEST_PARAMETER" in upper:
            return f"요청 파라미터 오류(10): {msg}"
        if code in {"03", "3"} or "NO_DATA" in upper:
            return f"자료 없음({code or '03'} / {msg or 'NO_DATA'})"
        if code:
            return f"API 오류 {code} / {msg or '메시지 없음'}"
        return msg or "알 수 없는 API 오류"

    def _decode_response(res):
        try:
            data = res.json()
            if isinstance(data, dict):
                header = data.get("response", {}).get("header", {}) or {}
                return (
                    data,
                    str(header.get("resultCode", "")).strip(),
                    str(header.get("resultMsg", "")).strip(),
                )
        except Exception:
            pass

        body_text = (res.text or "")[:6000]
        code_m = re.search(
            r"<resultCode>\s*([^<]+)\s*</resultCode>",
            body_text,
            re.I,
        )
        msg_m = re.search(
            r"<resultMsg>\s*([^<]+)\s*</resultMsg>",
            body_text,
            re.I,
        )
        return (
            None,
            code_m.group(1).strip() if code_m else "",
            msg_m.group(1).strip() if msg_m else "",
        )

    def _request_page(start_dt, end_dt, page_no, page_size, retries=3):
        params = {
            "ServiceKey": key,
            "pageNo": str(int(page_no)),
            "numOfRows": str(int(page_size)),
            "dataType": "JSON",
            "dataCd": "ASOS",
            "dateCd": "HR",
            "startDt": pd.Timestamp(start_dt).strftime("%Y%m%d"),
            "startHh": "00",
            "endDt": pd.Timestamp(end_dt).strftime("%Y%m%d"),
            "endHh": "23",
            "stnIds": str(int(stn_id)),
        }

        last_error = ""
        for attempt in range(1, retries + 1):
            try:
                res = requests.get(
                    url,
                    params=params,
                    timeout=(6, 30),
                    headers={"User-Agent": "Mozilla/5.0"},
                )

                data, code, msg = _decode_response(res)

                if res.status_code in (401, 403):
                    return [], {
                        "ok": False,
                        "fatal": True,
                        "code": str(res.status_code),
                        "message": (
                            f"HTTP {res.status_code}: 활용승인/인증키를 확인하세요."
                        ),
                    }

                res.raise_for_status()

                if code and code != "00":
                    upper = str(msg).upper()
                    nodata = code in {"03", "3"} or "NO_DATA" in upper
                    fatal = (
                        code in {"20", "30", "22"}
                        or "ACCESS_DENIED" in upper
                        or "KEY_IS_NOT_REGISTERED" in upper
                    )
                    return [], {
                        "ok": nodata,
                        "nodata": nodata,
                        "fatal": fatal,
                        "code": code,
                        "message": _friendly_error(code, msg),
                    }

                if not isinstance(data, dict):
                    snippet = (res.text or "").strip().replace("\n", " ")[:180]
                    raise RuntimeError(f"JSON 응답이 아닙니다: {snippet}")

                body = data.get("response", {}).get("body", {}) or {}
                items = _parse_api_items(data)

                try:
                    total_count = int(body.get("totalCount", 0) or 0)
                except Exception:
                    total_count = len(items)

                return items, {
                    "ok": True,
                    "fatal": False,
                    "code": "00",
                    "total_count": total_count,
                    "message": f"{len(items):,}건",
                }

            except Exception as exc:
                last_error = f"{type(exc).__name__}: {exc}"
                if attempt < retries:
                    time.sleep(0.7 * attempt)

        return [], {
            "ok": False,
            "fatal": False,
            "code": "",
            "message": last_error or "요청 실패",
        }

    def _fetch_one_month(year, month):
        start_dt = pd.Timestamp(year=year, month=month, day=1)
        end_dt = start_dt + pd.offsets.MonthEnd(0)
        end_dt = min(end_dt, today - pd.Timedelta(days=1))

        if end_dt < start_dt:
            return month, [], {
                "연도": year,
                "월": month,
                "상태": "⚠️ 미래기간",
                "건수": 0,
                "페이지수": 0,
                "페이지크기": 0,
                "메시지": "제공가능 기간 아님",
            }, None

        # 1000은 사용하지 않는다.
        # 900에서 오류99면 500, 그마저 오류99면 200.
        page_sizes = [900, 500, 200]
        first_items = None
        first_info = None
        chosen_size = None

        for size in page_sizes:
            items, info = _request_page(
                start_dt, end_dt, page_no=1, page_size=size, retries=3
            )

            if info.get("fatal"):
                return month, [], {
                    "연도": year,
                    "월": month,
                    "상태": "❌ 인증/승인 오류",
                    "건수": 0,
                    "페이지수": 0,
                    "페이지크기": size,
                    "메시지": info.get("message", ""),
                }, info.get("message", "")

            if info.get("ok"):
                first_items = items
                first_info = info
                chosen_size = size
                break

            # 오류99일 때만 더 작은 페이지 크기로 재시도.
            # 다른 오류는 같은 요청을 더 작게 해도 해결되지 않는 경우가 많다.
            if str(info.get("code", "")) != "99":
                return month, [], {
                    "연도": year,
                    "월": month,
                    "상태": "❌ API 실패",
                    "건수": 0,
                    "페이지수": 0,
                    "페이지크기": size,
                    "메시지": info.get("message", ""),
                }, None

        if first_info is None or not first_info.get("ok"):
            return month, [], {
                "연도": year,
                "월": month,
                "상태": "❌ 오류99 지속",
                "건수": 0,
                "페이지수": 0,
                "페이지크기": page_sizes[-1],
                "메시지": (
                    "numOfRows를 900→500→200으로 낮춰도 오류99가 계속되었습니다."
                ),
            }, None

        total_count = int(first_info.get("total_count", 0) or 0)

        if total_count <= 0 and not first_items:
            return month, [], {
                "연도": year,
                "월": month,
                "상태": "⚠️ 자료없음",
                "건수": 0,
                "페이지수": 1,
                "페이지크기": chosen_size,
                "메시지": "해당 월 자료 없음",
            }, None

        total_pages = max(
            1,
            int(math.ceil(total_count / chosen_size))
            if total_count > 0 else 1,
        )

        all_items = list(first_items)
        errors = []

        # 한 달 자료는 보통 744건 이하라 page 1로 끝난다.
        # 혹시 totalCount가 더 크면 이후 페이지를 순차적으로 안전하게 받는다.
        for page_no in range(2, total_pages + 1):
            items, info = _request_page(
                start_dt,
                end_dt,
                page_no=page_no,
                page_size=chosen_size,
                retries=3,
            )
            if info.get("fatal"):
                return month, [], {
                    "연도": year,
                    "월": month,
                    "상태": "❌ 인증/승인 오류",
                    "건수": 0,
                    "페이지수": total_pages,
                    "페이지크기": chosen_size,
                    "메시지": info.get("message", ""),
                }, info.get("message", "")

            if not info.get("ok"):
                errors.append(
                    f"{page_no}페이지: {info.get('message', '실패')}"
                )
            else:
                all_items.extend(items)

        if errors:
            return month, [], {
                "연도": year,
                "월": month,
                "상태": "❌ 일부 페이지 실패",
                "건수": 0,
                "페이지수": total_pages,
                "페이지크기": chosen_size,
                "메시지": " | ".join(errors[:3]),
            }, None

        return month, all_items, {
            "연도": year,
            "월": month,
            "상태": "✅ API",
            "건수": len(all_items),
            "페이지수": total_pages,
            "페이지크기": chosen_size,
            "메시지": f"{len(all_items):,}건",
        }, None

    def _records_to_df(records, year):
        rows = []
        wrong_station_ids = set()

        for it in records:
            if not isinstance(it, dict):
                continue

            # stnIds 필터가 실제로 적용됐는지 확인
            raw_stn = str(it.get("stnId", "") or "").strip()
            if raw_stn:
                try:
                    if int(float(raw_stn)) != int(stn_id):
                        wrong_station_ids.add(raw_stn)
                        continue
                except Exception:
                    pass

            tm = pd.to_datetime(it.get("tm"), errors="coerce")
            wd = pd.to_numeric(it.get("wd"), errors="coerce")
            ws = pd.to_numeric(it.get("ws"), errors="coerce")

            if pd.isna(tm) or pd.isna(ws):
                continue

            wd_qc = str(it.get("wdQcflag", "") or "").strip()
            ws_qc = str(it.get("wsQcflag", "") or "").strip()

            if ws_qc not in ("", "0"):
                continue
            if (
                wd_qc not in ("", "0")
                and not (float(ws) < 0.5)
            ):
                continue

            rows.append({
                "지점명": str(
                    it.get("stnNm")
                    or station_base_name(station_label)
                ),
                "일시": tm,
                "풍향": wd,
                "풍속": ws,
            })

        d = pd.DataFrame(rows)
        if d.empty:
            return d, wrong_station_ids

        d = d[
            pd.to_datetime(d["일시"], errors="coerce").dt.year
            == int(year)
        ].copy()

        d = (
            d.drop_duplicates(subset=["일시"], keep="last")
            .sort_values("일시")
            .reset_index(drop=True)
        )
        return d, wrong_station_ids

    def _fetch_one_year(year):
        cache_path = _cache_path_v46(year)

        if cache_path.exists() and not force_refresh:
            try:
                d = pd.read_pickle(cache_path)
                if not d.empty:
                    csv_path = _ensure_csv_cache(d, year)
                    return year, d, {
                        "연도": year,
                        "상태": "✅ 캐시",
                        "건수": len(d),
                        "성공월": 12,
                        "실패월": 0,
                        "메시지": f"{cache_path.name}" + (f" / {csv_path.name}" if csv_path else ""),
                    }, [], None
            except Exception:
                pass

        months = []
        for month in range(1, 13):
            start_dt = pd.Timestamp(year=year, month=month, day=1)
            if start_dt <= today - pd.Timedelta(days=1):
                months.append(month)

        month_results = {}
        month_statuses = {}
        fatal_message = None

        # 월별로 최대 3개 동시 요청.
        with ThreadPoolExecutor(max_workers=min(3, len(months))) as ex:
            futures = {
                ex.submit(_fetch_one_month, year, month): month
                for month in months
            }

            for fut in as_completed(futures):
                month = futures[fut]
                try:
                    m, items, status_row, fatal = fut.result()
                except Exception as exc:
                    m = month
                    items = []
                    fatal = None
                    status_row = {
                        "연도": year,
                        "월": month,
                        "상태": "❌ 예외",
                        "건수": 0,
                        "페이지수": 0,
                        "페이지크기": 0,
                        "메시지": f"{type(exc).__name__}: {exc}",
                    }

                month_statuses[m] = status_row

                if fatal:
                    fatal_message = str(fatal)

                if status_row.get("상태") in {"✅ API", "⚠️ 자료없음"}:
                    month_results[m] = items

        month_status_df = pd.DataFrame([
            month_statuses[m]
            for m in sorted(month_statuses)
        ])

        if fatal_message:
            return year, pd.DataFrame(), {
                "연도": year,
                "상태": "❌ 인증/승인 오류",
                "건수": 0,
                "성공월": int(
                    month_status_df["상태"].astype(str).str.startswith("✅").sum()
                ) if not month_status_df.empty else 0,
                "실패월": int(
                    (~month_status_df["상태"].astype(str).isin(["✅ API", "⚠️ 자료없음"])).sum()
                ) if not month_status_df.empty else len(months),
                "메시지": fatal_message,
            }, month_status_df.to_dict("records"), fatal_message

        failed_months = [
            m for m in months
            if m not in month_results
        ]

        if failed_months:
            fail_msgs = []
            for m in failed_months[:3]:
                s = month_statuses.get(m, {})
                fail_msgs.append(
                    f"{m}월: {s.get('메시지', '실패')}"
                )

            return year, pd.DataFrame(), {
                "연도": year,
                "상태": "❌ 일부 월 실패",
                "건수": 0,
                "성공월": len(month_results),
                "실패월": len(failed_months),
                "메시지": " | ".join(fail_msgs),
            }, month_status_df.to_dict("records"), None

        all_records = []
        for month in sorted(month_results):
            all_records.extend(month_results[month])

        d, wrong_stations = _records_to_df(all_records, year)

        if wrong_stations:
            return year, pd.DataFrame(), {
                "연도": year,
                "상태": "❌ 지점필터 이상",
                "건수": 0,
                "성공월": len(month_results),
                "실패월": 0,
                "메시지": (
                    f"요청 지점 {stn_id} 외 지점자료가 응답에 포함됨: "
                    f"{sorted(wrong_stations)[:5]}"
                ),
            }, month_status_df.to_dict("records"), None

        if d.empty:
            return year, d, {
                "연도": year,
                "상태": "⚠️ 유효 wd/ws 없음",
                "건수": 0,
                "성공월": len(month_results),
                "실패월": 0,
                "메시지": (
                    f"원자료 {len(all_records):,}건 중 "
                    "사용 가능한 풍향·풍속 자료 없음"
                ),
            }, month_status_df.to_dict("records"), None

        try:
            d.to_pickle(cache_path)
        except Exception:
            pass
        _ensure_csv_cache(d, year)

        return year, d, {
            "연도": year,
            "상태": "✅ API",
            "건수": len(d),
            "성공월": len(month_results),
            "실패월": 0,
            "메시지": f"유효 시간풍 {len(d):,}건",
        }, month_status_df.to_dict("records"), None

    # ------------------------------------------------------------------
    # 연도 최대 2개 동시 처리 × 각 연도 월 3개 동시 = 최대 6개 요청
    # ------------------------------------------------------------------
    frames_by_year = {}
    year_status_map = {}
    all_month_status = []
    fatal_errors = []

    progress = st.progress(0)
    progress_text = st.empty()

    total_years = max(1, len(years))
    completed = 0

    cached_years = []
    api_years = []

    for year in years:
        cp = _cache_path_v46(year)
        if cp.exists() and not force_refresh:
            try:
                d = pd.read_pickle(cp)
                if not d.empty:
                    csv_path = _ensure_csv_cache(d, year)
                    frames_by_year[year] = d
                    year_status_map[year] = {
                        "연도": year,
                        "상태": "✅ 캐시",
                        "건수": len(d),
                        "성공월": 12,
                        "실패월": 0,
                        "메시지": f"{cp.name}" + (f" / {csv_path.name}" if csv_path else ""),
                    }
                    cached_years.append(year)
                    completed += 1
                    continue
            except Exception:
                pass
        api_years.append(year)

    progress.progress(min(completed / total_years, 1.0))
    progress_text.caption(
        f"캐시 {len(cached_years)}개년 · "
        f"API 수집 대상 {len(api_years)}개년 · "
        "월별 조회 / numOfRows 900"
    )

    if api_years:
        with ThreadPoolExecutor(
            max_workers=min(2, len(api_years))
        ) as year_executor:
            futures = {
                year_executor.submit(_fetch_one_year, year): year
                for year in api_years
            }

            for fut in as_completed(futures):
                year = futures[fut]
                try:
                    y, d, y_status, month_rows, fatal = fut.result()
                except Exception as exc:
                    y = year
                    d = pd.DataFrame()
                    month_rows = []
                    fatal = None
                    y_status = {
                        "연도": year,
                        "상태": "❌ 예외",
                        "건수": 0,
                        "성공월": 0,
                        "실패월": 12,
                        "메시지": f"{type(exc).__name__}: {exc}",
                    }

                year_status_map[y] = y_status
                all_month_status.extend(month_rows)

                if isinstance(d, pd.DataFrame) and not d.empty:
                    frames_by_year[y] = d

                if fatal:
                    fatal_errors.append(str(fatal))

                completed += 1
                progress.progress(min(completed / total_years, 1.0))
                progress_text.caption(
                    f"{station_label} {completed}/{total_years}개년 완료 · "
                    f"방금 완료: {y}년 · "
                    f"{y_status.get('성공월', 0)}/12개월"
                )

    progress.progress(1.0)
    time.sleep(0.1)
    progress.empty()
    progress_text.empty()

    year_status_df = pd.DataFrame([
        year_status_map[y]
        for y in sorted(year_status_map)
    ])
    month_status_df = pd.DataFrame(all_month_status)

    frames = [
        frames_by_year[y]
        for y in sorted(frames_by_year)
        if isinstance(frames_by_year[y], pd.DataFrame)
        and not frames_by_year[y].empty
    ]

    if fatal_errors and not frames:
        return pd.DataFrame(), {
            "ok": False,
            "message": fatal_errors[0],
            "year_status": year_status_df,
            "month_status": month_status_df,
        }

    if not frames:
        failed_examples = []
        if not month_status_df.empty:
            bad = month_status_df[
                ~month_status_df["상태"].astype(str).isin(
                    ["✅ API", "⚠️ 자료없음"]
                )
            ]
            for _, r in bad.head(3).iterrows():
                failed_examples.append(
                    f"{int(r['연도'])}-{int(r['월']):02d}: {r.get('메시지', '')}"
                )

        return pd.DataFrame(), {
            "ok": False,
            "message": (
                "ASOS 시간자료 API에서 사용 가능한 풍향·풍속 자료를 가져오지 못했습니다."
                + (
                    " 상세: " + " / ".join(failed_examples)
                    if failed_examples else ""
                )
            ),
            "year_status": year_status_df,
            "month_status": month_status_df,
        }

    result = pd.concat(frames, ignore_index=True)
    result = (
        result.drop_duplicates(subset=["일시"], keep="last")
        .sort_values("일시")
        .reset_index(drop=True)
    )

    ok_years = sorted(frames_by_year.keys())
    failed_years = []
    if not year_status_df.empty:
        failed_years = year_status_df.loc[
            ~year_status_df["상태"].astype(str).str.startswith("✅"),
            "연도",
        ].astype(int).tolist()

    message = (
        f"ASOS 시간자료 수집 완료 · {len(result):,}시간 · "
        f"{min(ok_years)}~{max(ok_years)}"
    )
    if failed_years:
        message += f" · 미적용 연도 {_year_list_text(failed_years)}"

    return result, {
        "ok": True,
        "message": message,
        "year_status": year_status_df,
        "month_status": month_status_df,
        "failed_years": failed_years,
    }

# =============================================================================
# 5. 공공데이터포털 ASOS 일자료 API
# =============================================================================


def _safe_float(value):
    if value is None:
        return np.nan
    text = str(value).strip()
    if text == "" or text.lower() in {"null", "nan", "none"}:
        return np.nan
    try:
        return float(text)
    except Exception:
        return np.nan


def _compress_years(years) -> str:
    """[1994, 1995, 1996, 1999] -> '1994~1996, 1999' 형태로 표시."""
    vals = sorted({int(y) for y in (years or [])})
    if not vals:
        return "없음"
    groups = []
    s = p = vals[0]
    for y in vals[1:]:
        if y == p + 1:
            p = y
            continue
        groups.append(str(s) if s == p else f"{s}~{p}")
        s = p = y
    groups.append(str(s) if s == p else f"{s}~{p}")
    return ", ".join(groups)


def fetch_daily_api(stn_id: int, start_yr: int, end_yr: int, key: str) -> pd.DataFrame:
    """ASOS 일자료 수집.

    중요한 처리 원칙
    - API의 03 / NO_DATA는 오류창을 연도별로 띄우지 않고 '자료없음'으로 기록한다.
    - timeout/502/503/504 등 실제 통신 오류도 연도별 경고창을 만들지 않고 상태정보로 모은다.
    - 정상적으로 받은 연도 자료는 그대로 사용하고, 없는 연도는 계산에서 자동 제외된다.
    """
    records = []
    progress_bar = st.progress(0)
    status_text = st.empty()
    years = list(range(start_yr, end_yr + 1))
    safe_key = urllib.parse.unquote(str(key).strip())

    fetch_status = {
        "ok_years": [],
        "no_data_years": [],
        "error_years": [],
        "error_messages": {},
    }

    url = "https://apis.data.go.kr/1360000/AsosDalyInfoService/getWthrDataList"

    for i, yr in enumerate(years, start=1):
        status_text.text(f"📡 {yr}년 ASOS 일자료 수집 중... ({i}/{len(years)})")

        # 현재 연도는 미래 날짜를 요청하지 않도록 오늘/어제 범위에서 자른다.
        today = pd.Timestamp.now().normalize()
        year_end = pd.Timestamp(year=yr, month=12, day=31)
        end_date = min(year_end, today - pd.Timedelta(days=1))
        year_start = pd.Timestamp(year=yr, month=1, day=1)
        if end_date < year_start:
            progress_bar.progress(i / len(years))
            continue

        params = {
            "ServiceKey": safe_key,
            "pageNo": "1",
            "numOfRows": "366",
            "dataType": "JSON",
            "dataCd": "ASOS",
            "dateCd": "DAY",
            "startDt": year_start.strftime("%Y%m%d"),
            "endDt": end_date.strftime("%Y%m%d"),
            "stnIds": str(stn_id),
        }

        success = False
        no_data = False
        last_error = None

        for attempt in range(3):
            try:
                res = requests.get(url, params=params, timeout=20)
                res.raise_for_status()
                data = res.json()
                header = data.get("response", {}).get("header", {})
                result_code = str(header.get("resultCode", "")).strip()
                result_msg = str(header.get("resultMsg", "")).strip()

                # 공공데이터포털의 '자료 없음' 응답은 재시도해도 달라지지 않으므로 즉시 기록한다.
                if result_code != "00":
                    msg_upper = result_msg.upper()
                    if result_code == "03" or "NO_DATA" in msg_upper or "NODATA" in msg_upper:
                        no_data = True
                        last_error = f"{result_code} / {result_msg or 'NO_DATA'}"
                        break
                    raise RuntimeError(f"API 오류: {result_code} / {result_msg}")

                items_obj = data.get("response", {}).get("body", {}).get("items", {})
                items = items_obj.get("item", []) if isinstance(items_obj, dict) else []
                if isinstance(items, dict):
                    items = [items]

                # 정상코드지만 item이 비어 있는 경우도 자료없음으로 처리한다.
                if not items:
                    no_data = True
                    last_error = "정상응답 / 자료없음"
                    break

                for item in items:
                    tm = str(item.get("tm", ""))
                    if len(tm) < 10:
                        continue
                    records.append({
                        "연도": int(tm[:4]),
                        "월": int(tm[5:7]),
                        "일": int(tm[8:10]),
                        "평균기온": _safe_float(item.get("avgTa")),
                        "최고기온": _safe_float(item.get("maxTa")),
                        "최저기온": _safe_float(item.get("minTa")),
                        "평균해면기압": _safe_float(item.get("avgPs")),
                        "최고해면기압": _safe_float(item.get("maxPs")),
                        "최저해면기압": _safe_float(item.get("minPs")),
                        "평균상대습도": _safe_float(item.get("avgRhm")),
                        "최소상대습도": _safe_float(item.get("minRhm")),
                        "일강수량": _safe_float(item.get("sumRn")),
                        "1시간최다강수량": _safe_float(item.get("hr1MaxRn")),
                        "평균풍속": _safe_float(item.get("avgWs")),
                        "최대풍속": _safe_float(item.get("maxWs")),
                        "최대풍속풍향": _safe_float(item.get("maxWsWd")),
                        "최대순간풍속": _safe_float(item.get("maxInsWs")),
                        "최대순간풍속풍향": _safe_float(item.get("maxInsWsWd")),
                        # ddMefs = 일 최심신적설. 기존 코드의 "적설"도 호환을 위해 유지
                        "적설": _safe_float(item.get("ddMefs")),
                        "일최심신적설": _safe_float(item.get("ddMefs")),
                        "합계3시간신적설": _safe_float(item.get("sumDpthFhsc")),
                        "평균전운량": _safe_float(item.get("avgTca")),
                        "일기현상": item.get("iscs", "") or "",
                    })
                success = True
                break
            except Exception as exc:
                last_error = exc
                if attempt < 2:
                    time.sleep(1.5)

        if success:
            fetch_status["ok_years"].append(yr)
        elif no_data:
            fetch_status["no_data_years"].append(yr)
        else:
            fetch_status["error_years"].append(yr)
            fetch_status["error_messages"][yr] = str(last_error)

        progress_bar.progress(i / len(years))

    status_text.empty()
    progress_bar.empty()

    df = pd.DataFrame(records)
    df.attrs["asos_fetch_status"] = fetch_status
    return df


# =============================================================================
# 5-1. 개정 작업일수용 추가자료 (에어코리아 최종확정 PM10 + WINK 파랑)
#      안개는 기존 작업일수의 안개일수를 그대로 사용
# =============================================================================


def _extract_json_items(obj, required_keys=None):
    """공공데이터포털 JSON 응답의 중첩 구조가 조금 달라도 레코드를 재귀적으로 찾는다."""
    found = []
    required_keys = set(required_keys or [])

    def walk(x):
        if isinstance(x, dict):
            if not required_keys or required_keys.intersection(x.keys()):
                found.append(x)
            for v in x.values():
                walk(v)
        elif isinstance(x, list):
            for v in x:
                walk(v)

    walk(obj)
    return found


def _response_result_code(data):
    if not isinstance(data, dict):
        return "", ""
    for d in _extract_json_items(data, ["resultCode", "resultMsg"]):
        if "resultCode" in d:
            return str(d.get("resultCode", "")), str(d.get("resultMsg", ""))
    return "", ""


def _month_range(start_year: int, end_year: int):
    today = pd.Timestamp.now().normalize()
    for yr in range(int(start_year), int(end_year) + 1):
        for mon in range(1, 13):
            first = pd.Timestamp(year=yr, month=mon, day=1)
            if first > today:
                continue
            yield yr, mon


@st.cache_data(show_spinner=False, ttl=6 * 3600)
def fetch_visibility_revised(stn_id: int, start_yr: int, end_yr: int, key: str):
    """
    ASOS 시간자료의 시정(vs, m)을 이용해 '시정거리 1 km 이하 일수'를 월별 집계.
    하루 중 유효 시정 관측값이 하나라도 있고 최저 시정 <= 1000m 이면 1일.
    """
    if not key:
        return pd.DataFrame(), {"ok": False, "message": "ASOS API Key 없음"}

    url = "https://apis.data.go.kr/1360000/AsosHourlyInfoService/getWthrDataList"
    safe_key = urllib.parse.unquote(str(key).strip())
    rows = []
    errors = []

    today = pd.Timestamp.now().normalize()
    for yr in range(int(start_yr), int(end_yr) + 1):
        y_start = pd.Timestamp(year=yr, month=1, day=1)
        y_end = min(pd.Timestamp(year=yr, month=12, day=31), today - pd.Timedelta(days=1))
        if y_end < y_start:
            continue

        page = 1
        while True:
            params = {
                "ServiceKey": safe_key,
                "pageNo": str(page),
                "numOfRows": "10000",
                "dataType": "JSON",
                "dataCd": "ASOS",
                "dateCd": "HR",
                "startDt": y_start.strftime("%Y%m%d"),
                "startHh": "00",
                "endDt": y_end.strftime("%Y%m%d"),
                "endHh": "23",
                "stnIds": str(stn_id),
            }
            try:
                r = requests.get(url, params=params, timeout=30)
                r.raise_for_status()
                data = r.json()
                code, msg = _response_result_code(data)
                if code and code not in {"00", "0", "000"}:
                    errors.append(f"{yr}: {code} / {msg}")
                    break
                body = data.get("response", {}).get("body", {}) if isinstance(data, dict) else {}
                total = int(body.get("totalCount") or 0) if isinstance(body, dict) else 0
                items_obj = body.get("items", {}) if isinstance(body, dict) else {}
                items = items_obj.get("item", []) if isinstance(items_obj, dict) else []
                if isinstance(items, dict):
                    items = [items]
                for item in items:
                    tm = item.get("tm")
                    vs = _safe_float(item.get("vs"))
                    if tm:
                        rows.append({"tm": tm, "vs": vs})
                if page * 10000 >= total or not items:
                    break
                page += 1
            except Exception as exc:
                errors.append(f"{yr}: {exc}")
                break

    if not rows:
        return pd.DataFrame(), {"ok": False, "message": "시정 시간자료를 받지 못했습니다.", "errors": errors}

    h = pd.DataFrame(rows)
    h["날짜"] = pd.to_datetime(h["tm"], errors="coerce").dt.normalize()
    h["vs"] = pd.to_numeric(h["vs"], errors="coerce")
    h = h.dropna(subset=["날짜"])

    daily = h.groupby("날짜").agg(
        최저시정_m=("vs", "min"),
        시정관측횟수=("vs", "count"),
    ).reset_index()
    daily["시정1km이하_개정"] = np.where(
        daily["시정관측횟수"] > 0,
        (daily["최저시정_m"] <= 1000.0).astype(float),
        np.nan,
    )
    daily["연도"] = daily["날짜"].dt.year
    daily["월"] = daily["날짜"].dt.month

    monthly = daily.groupby(["연도", "월"], as_index=False).agg(
        시정1km이하_개정=("시정1km이하_개정", lambda x: x.sum(min_count=1)),
        시정관측일수=("시정관측횟수", lambda x: int((x > 0).sum())),
    )
    return monthly, {
        "ok": True,
        "message": f"시정 시간자료 {len(h):,}건 / 일자료 {len(daily):,}일",
        "errors": errors,
    }


def _compact_pdf_text(text: str) -> str:
    """PDF 추출 텍스트의 공백/특수문자를 정규화해 검색하기 쉽게 만든다."""
    text = str(text or "")
    replacements = {
        "\u00a0": " ",
        "\u200b": "",
        "\ufeff": "",
        "～": "~",
        "∼": "~",
        "〜": "~",
        "：": ":",
        "％": "%",
    }
    for a, b in replacements.items():
        text = text.replace(a, b)
    return re.sub(r"\s+", "", text)


def _extract_wave_summary_text_from_pdf(pdf_bytes: bytes):
    """
    장기파랑 검토서 PDF에서 '파랑에 의한 비작업일수 산정' 결과를 자동 추출한다.

    우선적으로 찾는 항목
    - 사석공: 유의파고 0.8m 이상 -> 약 XX일(YY%)
    - 지반개량공/DCM선: 1.0~1.5m 중 주기 8초 이상 + 1.5m 이상 -> 약 XX일(YY%)

    이 함수는 텍스트가 포함된 PDF를 대상으로 한다. 스캔 이미지 PDF는 별도 OCR 없이는
    자동 추출이 어려우므로 명확한 오류 메시지를 반환한다.
    """
    if not pdf_bytes:
        return {"ok": False, "message": "PDF 파일이 없습니다.", "results": [], "page_count": 0}
    if PdfReader is None:
        return {
            "ok": False,
            "message": "pypdf 패키지가 설치되지 않았습니다. 'pip install pypdf'를 실행하세요.",
            "results": [],
            "page_count": 0,
        }

    try:
        reader = PdfReader(io.BytesIO(pdf_bytes))
    except Exception as exc:
        return {"ok": False, "message": f"PDF를 열 수 없습니다: {exc}", "results": [], "page_count": 0}

    page_texts = []
    for i, page in enumerate(reader.pages, start=1):
        try:
            txt = page.extract_text() or ""
        except Exception:
            txt = ""
        page_texts.append((i, txt))

    extracted_chars = sum(len(t.strip()) for _, t in page_texts)
    if extracted_chars < 20:
        return {
            "ok": False,
            "message": "PDF에서 읽을 수 있는 텍스트가 거의 없습니다. 스캔 이미지 PDF일 가능성이 큽니다.",
            "results": [],
            "page_count": len(page_texts),
        }

    targets = [
        ("사석공", ["사석공", "사석"]),
        ("지반개량공", ["지반개량공", "DCM선", "DCM"]),
    ]
    results = []

    for kind, keywords in targets:
        found = None
        for page_no, page_text in page_texts:
            compact = _compact_pdf_text(page_text)
            for keyword in keywords:
                pos = compact.find(keyword)
                if pos < 0:
                    continue
                # 기준 설명에 숫자(0.8m, 1.5m 등)가 먼저 나오므로 '숫자+일' 형태만 찾는다.
                chunk = compact[pos:pos + 500]
                m = re.search(r"(?:약)?(?P<days>\d+(?:\.\d+)?)일(?:\((?P<rate>\d+(?:\.\d+)?)%\))?", chunk)
                if not m:
                    continue
                days = float(m.group("days"))
                rate = float(m.group("rate")) if m.group("rate") else days / 365.0 * 100.0
                # 사람이 확인할 수 있도록 원문 일부도 보관
                raw_page = re.sub(r"\s+", " ", page_text).strip()
                raw_pos = raw_page.find(keyword)
                if raw_pos >= 0:
                    snippet = raw_page[raw_pos:raw_pos + 180]
                else:
                    snippet = chunk[:180]
                found = {
                    "kind": kind,
                    "keyword": keyword,
                    "annual_days": days,
                    "rate_pct": rate,
                    "page": page_no,
                    "snippet": snippet,
                }
                break
            if found:
                break
        if found:
            results.append(found)

    if not results:
        # 문서에 최종 산정문구가 있는지 확인해 사용자에게 진단 메시지를 더 정확히 제공
        full_compact = _compact_pdf_text("\n".join(t for _, t in page_texts))
        section_found = "파랑에의한비작업일수산정" in full_compact
        if section_found:
            msg = "'파랑에 의한 비작업일수 산정' 문구는 찾았지만 '약 ○○일(○○%)' 결과를 자동 인식하지 못했습니다."
        else:
            msg = "PDF에서 사석공/지반개량공의 파랑 비작업일수 결과 문구를 찾지 못했습니다."
        return {"ok": False, "message": msg, "results": [], "page_count": len(page_texts)}

    return {
        "ok": True,
        "message": f"PDF {len(page_texts)}페이지에서 파랑 비작업일수 결과 {len(results)}건을 찾았습니다.",
        "results": results,
        "page_count": len(page_texts),
    }


def _wave_interval(value):
    text = re.sub(r"\s+", "", str("" if value is None else value).replace("\x00", ""))
    text = re.sub(r"[∼～–—−]", "~", text).replace("-", "~")
    text = re.sub(r"[ms秒米()]", "", text)
    num = r"\d+(?:\.\d+)?"
    m = re.fullmatch(rf"({num})~({num})", text)
    if m:
        lo, hi = map(float, m.groups())
        return (lo, hi) if hi > lo else None
    m = re.fullmatch(rf"(?:~|<|≤)?({num})(?:미만|이하)", text) or re.fullmatch(rf"[~<≤]({num})", text)
    if m:
        return (0.0, float(m.group(1)))
    m = re.fullmatch(rf"({num})(?:~|이상|초과|\+)", text) or re.fullmatch(rf"[>≥]({num})", text)
    return (float(m.group(1)), float("inf")) if m else None


def _wave_count(value):
    text = re.sub(r"\s+", "", str("" if value is None else value).replace("\x00", "")).replace(",", "")
    if text in ("-", "–", "—"):
        return 0.0
    if re.fullmatch(r"\d+(?:\.0+)?", text):
        return float(text)
    return None


def _wave_parse_grid(grid, context, page_no):
    """가변 계급과 축 방향을 판독하고 합계가 일치하는 출현횟수표만 반환한다."""
    context = context.replace("\x00", "")
    for transpose in (False, True):
        rows = [list(r) for r in grid]
        if transpose:
            rows = list(map(list, zip(*rows)))
        for header_index in range(min(4, len(rows))):
            header = rows[header_index]
            joined = " ".join(str(v or "") for r in rows[:header_index + 1] for v in r)
            # 파고와 주기 축이 명시된 표만 사용한다.
            if not re.search(r"파고|wave.?height|\bHs\b", joined, re.I) or not re.search(r"주기|period|\bTp\b", joined, re.I):
                continue
            columns = [(j, _wave_interval(v)) for j, v in enumerate(header)]
            columns = [(j, v) for j, v in columns if v is not None]
            if len(columns) < 2:
                continue
            first = columns[0][0]
            if first == 0:
                continue
            label_col = first - 1
            intervals = [v for _, v in columns]
            if any(abs(intervals[i][1] - intervals[i+1][0]) > 1e-6 for i in range(len(intervals)-1)):
                continue
            data, labels, periods = [], [], []
            total_row = None
            sums = []
            valid = True
            for row in rows[header_index + 1:]:
                if len(row) <= columns[-1][0]:
                    continue
                label = str(row[label_col] or "").replace("\x00", "").strip()
                period = _wave_interval(label)
                if period:
                    vals = [_wave_count(row[j]) for j, _ in columns]
                    if any(v is None for v in vals):
                        valid = False
                        break
                    data.append(vals); labels.append(re.sub(r"\s+", "", label)); periods.append(period)
                    sum_col = columns[-1][0] + 1
                    sums.append(_wave_count(row[sum_col]) if sum_col < len(row) else None)
                elif re.fullmatch(r"sum|total|합계|계|합 계", label, re.I):
                    total_row = row
                    break
            if not valid or len(data) < 2 or total_row is None:
                continue
            matrix = np.asarray(data, dtype=float)
            declared = [_wave_count(total_row[j]) for j, _ in columns]
            if any(v is None for v in declared) or not np.allclose(matrix.sum(axis=0), declared, atol=0.01, rtol=0):
                continue
            if any(v is not None and abs(v - matrix[i].sum()) > .01 for i,v in enumerate(sums)):
                continue
            total = float(matrix.sum())
            sum_col = columns[-1][0] + 1
            grand = _wave_count(total_row[sum_col]) if sum_col < len(total_row) else None
            if total <= 0 or (grand is not None and abs(grand-total) > .01):
                continue
            if len(set(labels)) != len(labels):
                continue
            # 대각선 머리글은 위쪽 열 축, 아래쪽 행 축의 순서를 따른다.
            axis = " ".join(str(r[label_col] or "") for r in rows[:header_index+1])
            height_rows = bool(re.search(r"주기.*파고|period.*height", axis, re.I | re.S))
            if height_rows:
                matrix = matrix.T
                intervals, periods = periods, intervals
                labels = [str(header[j]).replace("\n", "").replace("\x00", "") for j,_ in columns]
                heights = [str(r[label_col]).replace("\n", "").replace("\x00", "") for r in rows[header_index+1:] if _wave_interval(r[label_col])]
            else:
                heights = [str(header[j]).replace("\n", "").replace("\x00", "") for j,_ in columns]
            if any(abs(periods[i][1] - periods[i+1][0]) > 1e-6 for i in range(len(periods)-1)):
                continue
            frame = pd.DataFrame(matrix, index=labels, columns=heights)
            return {"page":page_no, "title":context.strip()[-240:], "matrix":frame,
                    "height_intervals":intervals, "period_intervals":periods,
                    "total":total, "verified":True}
    return None


@st.cache_data(show_spinner=False)
def extract_wave_frequency_tables(pdf_bytes):
    try:
        import pdfplumber
    except ImportError:
        return {"tables":[], "message":"분류표 인식에는 pdfplumber가 필요합니다: pip install pdfplumber"}
    found, seen = [], set()
    try:
        with pdfplumber.open(io.BytesIO(pdf_bytes)) as doc:
            for page_no, page in enumerate(doc.pages, 1):
                page_text = (page.extract_text() or "").replace("\x00", "")
                if not re.search(r"파고|wave.?height|\bHs\b", page_text, re.I) or not re.search(r"주기|period|\bTp\b", page_text, re.I):
                    continue
                words = page.extract_words()
                for settings in ({}, {"vertical_strategy":"text", "horizontal_strategy":"text", "min_words_vertical":2}):
                    for table in page.find_tables(settings):
                        grid = table.extract()
                        # 테두리가 없는 첫 열/마지막 열도 글자 좌표로 복원한다.
                        for ri, row in enumerate(table.rows):
                            for ci, cell in enumerate(row.cells):
                                if cell is None:
                                    reference = next((r.cells[ci] for r in table.rows if ci < len(r.cells) and r.cells[ci]), None)
                                    if reference:
                                        x0, _, x1, _ = reference
                                        _, top, _, bottom = row.bbox
                                        grid[ri][ci] = " ".join(w["text"] for w in words if x0 <= (w["x0"]+w["x1"])/2 < x1 and top <= (w["top"]+w["bottom"])/2 < bottom)
                        top = table.bbox[1]
                        context = page.crop((0,max(0,top-65),page.width,top)).extract_text() or ""
                        result = _wave_parse_grid(grid, context, page_no)
                        if result:
                            signature=(page_no, result["matrix"].to_csv())
                            if signature not in seen:
                                seen.add(signature);found.append(result)
        return {"tables":found,"message":f"검산을 통과한 파고×주기 출현횟수표 {len(found)}개" if found else "검산 가능한 출현횟수표를 찾지 못했습니다. 스캔·복잡한 병합표·페이지 분할표는 표를 별도로 확인해 주세요. 요약 일수로 세부 횟수를 추정하지 않습니다."}
    except Exception as exc:
        return {"tables":found,"message":f"표 인식 중 오류: {exc}"}


def _wave_table_calculation(table, criterion):
    matrix=table["matrix"]
    mask=np.zeros(matrix.shape,dtype=bool)
    dcm="DCM" in criterion or "지반개량" in criterion
    for i,(t0,t1) in enumerate(table["period_intervals"]):
        for j,(h0,h1) in enumerate(table["height_intervals"]):
            if dcm:
                full = h0 >= 1.5 or (h0 >= 1 and t0 >= 8)
                possible = h1 > 1.5 or (h1 > 1 and t1 > 8)
            else:
                full, possible = h0 >= .8, h1 > .8
            if possible and not full and float(matrix.iloc[i,j]) > 0:
                return {"ok":False,"message":"기준값이 계급 구간 내부에 있어 정확히 분리할 수 없습니다. 원시자료 또는 더 세분된 표가 필요합니다."}
            mask[i,j]=full
    count=float(matrix.to_numpy()[mask].sum())
    rate=count/table["total"]*100
    return {"ok":True,"count":count,"rate_pct":rate,"annual_days":rate/100*365,"mask":mask}


def _wave_table_display(table):
    frame=table["matrix"].copy()
    frame["Sum"]=frame.sum(axis=1)
    frame["Prop(%)"]=frame["Sum"]/table["total"]*100
    frame.loc["Sum"]=frame.sum(axis=0)
    frame.loc["Prop(%)"]=list(table["matrix"].sum(axis=0)/table["total"]*100)+[100.0,np.nan]
    frame.index.name="주기(s) / 파고(m)"
    return frame


def extract_wave_summary_from_pdf(pdf_bytes):
    result=_extract_wave_summary_text_from_pdf(pdf_bytes)
    detected=extract_wave_frequency_tables(pdf_bytes)
    result["tables"]=detected["tables"]
    result["table_message"]=detected["message"]
    if detected["tables"]:
        result["ok"]=True
        result["message"]=detected["message"]
    return result


def select_wave_pdf_result(parse_result: dict, criterion: str):
    """선택한 개정 파랑 기준에 맞는 PDF 추출 결과를 고른다."""
    tables = (parse_result or {}).get("tables", [])
    if tables:
        index = int(parse_result.get("selected_table", 0))
        table = tables[min(index, len(tables)-1)]
        calc = _wave_table_calculation(table, criterion)
        if calc["ok"]:
            return {**calc, "kind":"지반개량공" if ("DCM" in criterion or "지반개량" in criterion) else "사석공",
                    "page":table["page"], "snippet":table["title"], "frequency_table":table,
                    "reported_results":parse_result.get("results", [])}
        return None
    results = (parse_result or {}).get("results", [])
    if not results:
        return None

    if "사석공" in str(criterion) or "대선" in str(criterion):
        preferred = ["사석공"]
    elif "DCM" in str(criterion) or "지반개량" in str(criterion):
        preferred = ["지반개량공"]
    else:
        preferred = []

    for name in preferred:
        for item in results:
            if item.get("kind") == name:
                return item

    return results[0]


def build_manual_wave_monthly(input_mode: str, raw_value: str, criterion: str):
    """
    개정 작업일수용 장기파랑 비작업일수를 월별 값으로 만든다.

    현재 UI에서는 PDF 자동추출 결과(연간 비작업일수)를 넘겨주며,
    과거 버전 호환을 위해 기존 직접입력 모드도 내부적으로 지원한다.
    연간값은 기준 엑셀과 같이 12개월에 균등배분한다.
    """
    months = pd.Index(range(1, 13), name="월")
    empty = pd.Series(np.nan, index=months, dtype=float)
    raw = str(raw_value or "").strip()

    if not raw:
        return empty, {
            "ok": False,
            "message": "장기파랑 PDF에서 적용할 비작업일수를 찾지 못했습니다.",
            "criterion": criterion,
            "annual_days": np.nan,
        }

    try:
        if input_mode in ("연간 비작업일수(일/년)", "PDF 자동추출"):
            annual_days = float(raw.replace(",", ""))
            if not 0 <= annual_days <= 365:
                raise ValueError("연간 비작업일수는 0~365일 범위여야 합니다.")
            monthly = pd.Series(annual_days / 12.0, index=months, dtype=float)
            msg = f"연간 {annual_days:.2f}일을 월 {annual_days/12.0:.2f}일씩 균등배분"

        elif input_mode == "연간 출현율(%)":
            rate = float(raw.replace("%", "").replace(",", ""))
            if not 0 <= rate <= 100:
                raise ValueError("연간 출현율은 0~100% 범위여야 합니다.")
            annual_days = 365.0 * rate / 100.0
            monthly = pd.Series(annual_days / 12.0, index=months, dtype=float)
            msg = (
                f"연간 출현율 {rate:.4f}% → 연간 {annual_days:.2f}일 → "
                f"월 {annual_days/12.0:.2f}일씩 균등배분"
            )

        else:
            parts = [p.strip() for p in re.split(r"[,\n\t]+", raw) if p.strip()]
            if len(parts) != 12:
                raise ValueError("월별 입력은 1월~12월 순서로 정확히 12개 값을 입력해야 합니다.")
            vals = [float(p.replace(",", "")) for p in parts]
            if any(v < 0 or v > 31 for v in vals):
                raise ValueError("월별 비작업일수는 각 월 0~31일 범위여야 합니다.")
            monthly = pd.Series(vals, index=months, dtype=float)
            annual_days = float(monthly.sum())
            msg = f"월별 12개 직접입력 / 연간 합계 {annual_days:.2f}일"

        return monthly, {
            "ok": True,
            "message": msg,
            "criterion": criterion,
            "annual_days": float(annual_days),
        }
    except Exception as exc:
        return empty, {
            "ok": False,
            "message": str(exc),
            "criterion": criterion,
            "annual_days": np.nan,
        }


