def _wink_port_info_by_name(port_name: str):
    for region, ports in WINK_PORT_GROUPS.items():
        for info in ports:
            if info.get("name") == port_name:
                return region, info
    return None, None



def _safe_float_text(value):
    if value is None:
        return np.nan
    text = str(value).strip().replace(",", "")
    if not text or text.lower() in {"nan", "none", "null", "-", "--"}:
        return np.nan
    m = re.search(r"[-+]?\d+(?:\.\d+)?", text)
    if not m:
        return np.nan
    try:
        return float(m.group(0))
    except Exception:
        return np.nan


def _normalize_wave_col(col: str) -> str:
    text = str(col or "").strip().lower()
    return re.sub(r"[^0-9a-z가-힣]+", "", text)


def _read_tabular_bytes(raw: bytes, filename: str) -> pd.DataFrame:
    """WINK에서 내려받은 csv/txt/xlsx/zip 중 첫 번째 표를 DataFrame으로 읽는다."""
    name = str(filename or "wink_wave.dat")
    suffix = Path(name).suffix.lower()

    if suffix == ".zip":
        with zipfile.ZipFile(io.BytesIO(raw)) as zf:
            candidates = [
                n for n in zf.namelist()
                if Path(n).suffix.lower() in {".csv", ".txt", ".dat", ".xlsx", ".xls"}
                and not n.endswith("/")
            ]
            if not candidates:
                raise ValueError("WINK ZIP 안에서 CSV/TXT/XLSX 원자료를 찾지 못했습니다.")
            candidates.sort(key=lambda n: zf.getinfo(n).file_size, reverse=True)
            inner = candidates[0]
            return _read_tabular_bytes(zf.read(inner), inner)

    if suffix == ".7z":
        try:
            import py7zr
        except Exception as exc:
            raise ValueError(
                "WINK에서 7z 파일을 내려받았습니다. PowerShell에서 'pip install py7zr'을 한 번 실행하세요."
            ) from exc
        with tempfile.TemporaryDirectory(prefix="wink_7z_") as td:
            archive_path = Path(td) / "wink_wave.7z"
            archive_path.write_bytes(raw)
            with py7zr.SevenZipFile(archive_path, mode="r") as zf:
                zf.extractall(path=td)
            candidates = [
                p for p in Path(td).rglob("*")
                if p.is_file() and p.suffix.lower() in {".csv", ".txt", ".dat", ".xlsx", ".xls"}
            ]
            if not candidates:
                raise ValueError("WINK 7z 안에서 CSV/TXT/XLSX 원자료를 찾지 못했습니다.")
            candidates.sort(key=lambda p: p.stat().st_size, reverse=True)
            inner = candidates[0]
            return _read_tabular_bytes(inner.read_bytes(), inner.name)

    if suffix in {".xlsx", ".xls"}:
        return pd.read_excel(io.BytesIO(raw))

    last_exc = None
    for enc in ("utf-8-sig", "cp949", "euc-kr", "utf-8"):
        try:
            text = raw.decode(enc)
        except Exception as exc:
            last_exc = exc
            continue

        lines = text.splitlines()
        header_candidates = []
        for idx, line in enumerate(lines[:80]):
            compact = _normalize_wave_col(line)
            if any(k in compact for k in ("일시", "날짜", "date", "time", "datetime")) and any(
                k in compact for k in ("유의파고", "파고", "waveheight", "hs", "swh")
            ):
                header_candidates.append(idx)
        if not header_candidates:
            header_candidates = list(range(0, min(10, len(lines))))

        for header in header_candidates:
            for sep in (",", "\t", ";", r"\s+"):
                try:
                    kwargs = {"sep": sep, "engine": "python"} if sep == r"\s+" else {"sep": sep}
                    df = pd.read_csv(io.StringIO(text), header=header, **kwargs)
                    if df.shape[1] >= 2 and len(df) >= 1:
                        return df
                except Exception as exc:
                    last_exc = exc
                    continue

    raise ValueError(f"WINK 원자료 표를 읽지 못했습니다: {last_exc}")


def parse_wink_wave_bytes(raw: bytes, filename: str = "wink_wave.dat"):
    """WINK 장기후측파랑 파일에서 일시/유의파고/주기 열을 자동 탐지한다.

    WINK 원자료에서 자주 쓰이는 분리형 열
    YY, MM, DD, HR, MIN, HS, TMM10, MDIR, WS, WD 형식도 지원한다.
    """
    try:
        df = _read_tabular_bytes(raw, filename)
    except Exception as exc:
        return pd.DataFrame(), {"ok": False, "message": str(exc)}

    if df.empty:
        return pd.DataFrame(), {"ok": False, "message": "WINK 원자료가 비어 있습니다."}

    # 열 이름 앞뒤 공백/BOM 등을 제거
    df = df.copy()
    df.columns = [str(c).replace("\ufeff", "").strip() for c in df.columns]
    norm = {c: _normalize_wave_col(c) for c in df.columns}

    def exact_col(*aliases):
        aliases_n = {_normalize_wave_col(a) for a in aliases}
        for c, n in norm.items():
            if n in aliases_n:
                return c
        return None

    def choose_col(groups, exclude=()):
        best = None
        best_score = -1
        for c, n in norm.items():
            if any(_normalize_wave_col(x) in n for x in exclude):
                continue
            score = 0
            for priority, keys in enumerate(groups[::-1], start=1):
                for key in keys:
                    key_n = _normalize_wave_col(key)
                    if n == key_n:
                        score = max(score, 100 + priority)
                    elif key_n and key_n in n:
                        score = max(score, 10 + priority)
            if score > best_score:
                best_score = score
                best = c
        return best if best_score > 0 else None

    # -----------------------------------------------------------------
    # 1) 날짜/시간
    # -----------------------------------------------------------------
    dt_col = (
        exact_col("관측일시", "일시", "datetime", "date_time", "obsrvndt")
        or choose_col([
            ["관측일시", "일시", "datetime", "date_time", "obsrvnDt"],
            ["날짜", "date", "time", "시간"],
        ])
    )

    work = df.copy()

    if dt_col is not None:
        dt = pd.to_datetime(work[dt_col], errors="coerce")
        date_source = str(dt_col)
    else:
        # WINK 실제 장기후측파랑 원자료 형식: YY MM DD HR MIN ...
        year_col = exact_col("YY", "YYYY", "YEAR", "YR", "연도", "년도")
        month_col = exact_col("MM", "MONTH", "MON", "월")
        day_col = exact_col("DD", "DAY", "일")
        hour_col = exact_col("HR", "HH", "HOUR", "시", "시간")
        minute_col = exact_col("MIN", "MINUTE", "MI", "분")
        second_col = exact_col("SS", "SEC", "SECOND", "초")

        # 다른 이름의 파일도 기존의 느슨한 탐색으로 보완
        year_col = year_col or choose_col([["연도", "년도", "year", "yyyy", "yy"]])
        month_col = month_col or choose_col([["월", "month", "mon", "mm"]])
        day_col = day_col or choose_col([["일", "day", "dd"]])
        hour_col = hour_col or choose_col([["시간", "hour", "hr", "hh"]])
        minute_col = minute_col or choose_col([["minute", "min", "분"]])
        second_col = second_col or choose_col([["second", "sec", "초"]])

        if year_col is None or month_col is None or day_col is None:
            return pd.DataFrame(), {
                "ok": False,
                "message": (
                    "WINK 파일에서 날짜/일시 열을 찾지 못했습니다. "
                    f"현재 열: {list(df.columns)}"
                ),
            }

        year = pd.to_numeric(work[year_col], errors="coerce")
        # YY가 2자리인 경우 70~99 → 19xx, 00~69 → 20xx로 해석
        year = year.where(~year.between(0, 99), np.where(year >= 70, year + 1900, year + 2000))

        parts = pd.DataFrame({
            "year": year,
            "month": pd.to_numeric(work[month_col], errors="coerce"),
            "day": pd.to_numeric(work[day_col], errors="coerce"),
            "hour": pd.to_numeric(work[hour_col], errors="coerce") if hour_col else 0,
            "minute": pd.to_numeric(work[minute_col], errors="coerce") if minute_col else 0,
            "second": pd.to_numeric(work[second_col], errors="coerce") if second_col else 0,
        })
        dt = pd.to_datetime(parts, errors="coerce")
        date_source = "/".join(
            str(c) for c in (year_col, month_col, day_col, hour_col, minute_col, second_col) if c
        )

    # -----------------------------------------------------------------
    # 2) 파고 / 주기
    # -----------------------------------------------------------------
    # WINK: HS = 유의파고, TMM10 = 평균 절대파주기(Tm-1,0)
    hs_col = (
        exact_col("HS", "HSIGN", "HSIG", "SWH", "HM0")
        or choose_col([
            ["유의파고", "유의파고(m)", "hs", "hsig", "swh", "significant wave height"],
            ["파고", "wave height", "wvhgt"],
        ], exclude=("최대", "max"))
    )

    tp_col = (
        exact_col("TMM10", "TM-10", "TM10", "TP", "TPS", "TM01", "TM02", "WVPD")
        or choose_col([
            ["tmm10", "tm-10", "첨두주기", "피크주기", "tp", "tps", "peak period"],
            ["유의파주기", "파주기", "주기", "period", "wvpd", "tm01", "tm02"],
        ], exclude=("최대", "max"))
    )

    if hs_col is None:
        return pd.DataFrame(), {
            "ok": False,
            "message": f"WINK 파일에서 유의파고 열을 찾지 못했습니다. 현재 열: {list(df.columns)}",
        }

    out = pd.DataFrame({
        "일시": dt,
        "유의파고": work[hs_col].map(_safe_float_text),
    })
    out["주기"] = work[tp_col].map(_safe_float_text) if tp_col is not None else np.nan

    # 음수는 WINK/모델 자료의 결측 플래그일 가능성이 있으므로 결측 처리
    out.loc[out["유의파고"] < 0, "유의파고"] = np.nan
    out.loc[out["주기"] < 0, "주기"] = np.nan

    out = out.dropna(subset=["일시", "유의파고"]).sort_values("일시").reset_index(drop=True)
    if out.empty:
        return pd.DataFrame(), {
            "ok": False,
            "message": (
                "WINK 파일의 열은 찾았지만 유효한 파랑 시계열을 만들지 못했습니다. "
                f"인식 열: 날짜={date_source}, 파고={hs_col}, 주기={tp_col or '없음'}"
            ),
        }

    return out, {
        "ok": True,
        "message": f"WINK 파랑 원자료 {len(out):,}건 인식",
        "datetime_col": date_source,
        "hs_col": str(hs_col),
        "period_col": str(tp_col or "없음"),
        "coverage": f"{out['일시'].min()} ~ {out['일시'].max()}",
        "source_columns": list(df.columns),
    }

def build_wave_occurrence_table(wave_df: pd.DataFrame):
    """사진의 장기파랑 표와 같은 파고×주기 계급별 출현회수 표를 만든다.

    파고 계급(m): ~0.5, 0.5~0.6, 0.6~0.8, 0.8~1.0,
                  1.0~1.5, 1.5~2.0, 2.0~2.5, 2.5~
    주기 계급(s): 0~3, 3~4, ..., 11~12, 12~25

    사석공/대선 비작업률은 표의 Hs>=0.8m 열에 들어간 '회수'를 합한 뒤
    전체 유효회수로 나누어 계산한다. 화면에 보이는 Prop(%) 반올림값을
    다시 더하지 않기 때문에 반올림 누적오차가 생기지 않는다.
    """
    empty = pd.DataFrame()
    if wave_df is None or wave_df.empty:
        return empty, {"ok": False, "message": "WINK 원시 파랑자료가 없습니다."}
    if "유의파고" not in wave_df.columns or "주기" not in wave_df.columns:
        return empty, {"ok": False, "message": "WINK 원시자료에 유의파고/주기 열이 없습니다."}

    d = wave_df[["유의파고", "주기"]].copy()
    d["유의파고"] = pd.to_numeric(d["유의파고"], errors="coerce")
    d["주기"] = pd.to_numeric(d["주기"], errors="coerce")
    d = d.dropna(subset=["유의파고", "주기"])
    d = d[(d["유의파고"] >= 0) & (d["주기"] >= 0) & (d["주기"] <= 25)].copy()
    if d.empty:
        return empty, {"ok": False, "message": "0~25초 범위의 유효 파고/주기 자료가 없습니다."}

    h_bins = [0.0, 0.5, 0.6, 0.8, 1.0, 1.5, 2.0, 2.5, np.inf]
    h_labels = ["~0.5", "0.5~0.6", "0.6~0.8", "0.8~1.0", "1.0~1.5", "1.5~2.0", "2.0~2.5", "2.5~"]
    # 25.0초가 마지막 계급에 포함되도록 아주 작은 여유를 둔다.
    p_bins = [0.0, 3.0, 4.0, 5.0, 6.0, 7.0, 8.0, 9.0, 10.0, 11.0, 12.0, np.nextafter(25.0, np.inf)]
    p_labels = ["0~3", "3~4", "4~5", "5~6", "6~7", "7~8", "8~9", "9~10", "10~11", "11~12", "12~25"]

    d["파고계급"] = pd.cut(d["유의파고"], bins=h_bins, labels=h_labels, right=False, include_lowest=True)
    d["주기계급"] = pd.cut(d["주기"], bins=p_bins, labels=p_labels, right=False, include_lowest=True)
    d = d.dropna(subset=["파고계급", "주기계급"])
    if d.empty:
        return empty, {"ok": False, "message": "계급 분류 후 유효 파랑자료가 없습니다."}

    counts = pd.crosstab(d["주기계급"], d["파고계급"], dropna=False)
    counts = counts.reindex(index=p_labels, columns=h_labels, fill_value=0).astype(int)
    row_sum = counts.sum(axis=1)
    col_sum = counts.sum(axis=0)
    total = int(col_sum.sum())
    if total <= 0:
        return empty, {"ok": False, "message": "파랑 계급표의 전체 회수가 0입니다."}

    row_prop = row_sum / total * 100.0
    col_prop = col_sum / total * 100.0

    display = counts.copy().reset_index().rename(columns={"주기계급": "주기(s)"})
    display["Sum"] = row_sum.values.astype(int)
    display["Prop"] = [f"{x:.1f}%" for x in row_prop.values]

    sum_row = {"주기(s)": "Sum"}
    for c in h_labels:
        sum_row[c] = int(col_sum[c])
    sum_row["Sum"] = total
    sum_row["Prop"] = "100.0%"

    prop_row = {"주기(s)": "Prop(%)"}
    for c in h_labels:
        prop_row[c] = f"{float(col_prop[c]):.1f}%"
    prop_row["Sum"] = "100.0%"
    prop_row["Prop"] = ""
    display = pd.concat([display, pd.DataFrame([sum_row, prop_row])], ignore_index=True)

    hs08_cols = ["0.8~1.0", "1.0~1.5", "1.5~2.0", "2.0~2.5", "2.5~"]
    hs08_count = int(col_sum[hs08_cols].sum())
    hs08_rate = float(hs08_count / total * 100.0)
    hs08_annual_days = float(hs08_count / total * 365.0)

    return display, {
        "ok": True,
        "message": f"파고×주기 계급표 {total:,}회 분류 완료",
        "counts": counts,
        "height_counts": col_sum,
        "height_prop_pct": col_prop,
        "period_counts": row_sum,
        "period_prop_pct": row_prop,
        "total_count": total,
        "hs08_count": hs08_count,
        "hs08_rate_pct": hs08_rate,
        "hs08_annual_days": hs08_annual_days,
        "hs08_columns": hs08_cols,
    }


def calculate_wink_wave_monthly(wave_df: pd.DataFrame, start_year: int, end_year: int, criterion: str):
    """WINK 원시 파랑자료를 장기 출현율 → 연간 비작업일수 → 월 균등값으로 환산한다.

    사석공/대선은 사용자가 제시한 장기파랑 표 방식과 동일하게
      Hs>=0.8m 회수 / 전체 회수 × 365
    로 계산한 뒤 12개월에 균등 배분한다.

    DCM은 기존 기준(Hs>=1.5m 또는 1.0~1.5m & T>=8s)을 원시자료에서
    직접 판정하되, 마찬가지로 전체 출현율×365 후 12개월 균등 배분한다.
    """
    months = pd.Index(range(1, 13), name="월")
    empty = pd.Series(np.nan, index=months, dtype=float)
    if wave_df is None or wave_df.empty:
        return empty, {"ok": False, "message": "WINK 파랑 시계열이 없습니다.", "annual_days": np.nan}

    d = wave_df.copy()
    d["일시"] = pd.to_datetime(d["일시"], errors="coerce")
    d = d[d["일시"].notna()].copy()
    d = d[(d["일시"].dt.year >= int(start_year)) & (d["일시"].dt.year <= int(end_year))].copy()
    if d.empty:
        return empty, {
            "ok": False,
            "message": f"WINK 원자료에 선택한 {start_year}~{end_year}년 자료가 없습니다.",
            "annual_days": np.nan,
        }

    occurrence_table, occurrence_status = build_wave_occurrence_table(d)

    criterion_text = str(criterion or "")
    if "DCM" in criterion_text or "지반개량" in criterion_text:
        if "주기" not in d.columns or d["주기"].notna().sum() == 0:
            return empty, {
                "ok": False,
                "message": "DCM 기준에는 파주기 자료가 필요하지만 WINK 자료에 주기값이 없습니다.",
                "annual_days": np.nan,
                "occurrence_table": occurrence_table,
                "occurrence_status": occurrence_status,
            }
        valid = d["유의파고"].notna() & d["주기"].notna()
        dd = d.loc[valid].copy()
        cond = (dd["유의파고"] >= 1.5) | (
            (dd["유의파고"] >= 1.0) & (dd["유의파고"] < 1.5) & (dd["주기"] >= 8.0)
        )
        total_count = int(len(dd))
        nonwork_count = int(cond.sum())
        rate = float(nonwork_count / total_count * 100.0) if total_count else np.nan
        annual_days = float(nonwork_count / total_count * 365.0) if total_count else np.nan
        formula = f"DCM 기준 충족 {nonwork_count:,}회 / 유효 {total_count:,}회 × 365"
    else:
        if not occurrence_status.get("ok"):
            return empty, {
                "ok": False,
                "message": occurrence_status.get("message", "파고·주기 계급표 생성 실패"),
                "annual_days": np.nan,
                "occurrence_table": occurrence_table,
                "occurrence_status": occurrence_status,
            }
        total_count = int(occurrence_status["total_count"])
        nonwork_count = int(occurrence_status["hs08_count"])
        rate = float(occurrence_status["hs08_rate_pct"])
        annual_days = float(occurrence_status["hs08_annual_days"])
        formula = f"Hs≥0.8m {nonwork_count:,}회 / 전체 {total_count:,}회 × 365"

    if pd.isna(annual_days):
        return empty, {"ok": False, "message": "파랑 비작업일수를 계산하지 못했습니다.", "annual_days": np.nan}

    monthly_value = annual_days / 12.0
    monthly = pd.Series([monthly_value] * 12, index=months, dtype=float)
    detail = pd.DataFrame({
        "월": list(range(1, 13)),
        "파랑_비작업일수": [monthly_value] * 12,
        "적용출현율_pct": [rate] * 12,
    })

    return monthly.round(3), {
        "ok": True,
        "message": f"WINK 출현율 {rate:.3f}% → 연간 {annual_days:.2f}일 → 월 {monthly_value:.2f}일 균등배분",
        "occurrence_rate_pct": rate,
        "annual_days": annual_days,
        "monthly_days": monthly_value,
        "total_count": total_count,
        "nonwork_count": nonwork_count,
        "formula": formula,
        "coverage": f"{d['일시'].min()} ~ {d['일시'].max()}",
        "records": int(len(d)),
        "monthly_detail": detail,
        "occurrence_table": occurrence_table,
        "occurrence_status": occurrence_status,
    }


def _wink_prepare_longterm_layer(driver, log: list[str]) -> bool:
    """WINK 파랑인프라DB에서 장기후측파랑 레이어를 켠 상태로 준비한다."""
    try:
        result = driver.execute_script(
            """
            const cb=document.querySelector('#legendGrid');
            let changed=false;
            if(cb && !cb.checked){
                const label=document.querySelector('label[for="legendGrid"]');
                if(label){label.click(); changed=true;}
                else {cb.click(); changed=true;}
            }
            const close=document.querySelector('#pop_longterm_all_close');
            if(close){
                const p=document.querySelector('#pop_longterm_all');
                if(p && getComputedStyle(p).display!=='none'){
                    try{close.click();}catch(e){}
                }
            }
            return {found:!!cb, checked:cb?cb.checked:null, changed:changed};
            """
        )
        log.append(f"장기후측파랑 레이어 상태: {result}")
        return bool(result and result.get("found") and result.get("checked"))
    except Exception as exc:
        log.append(f"장기후측파랑 레이어 준비 오류: {exc}")
        return False


def _wink_prepare_port_target(driver, port_name: str, log: list[str]) -> dict:
    """WINK 좌측 항만 목록의 data-layer-search를 이용해 해당 항만 영역으로 이동한다.

    위·경도 직접입력 대신 WINK가 자체 제공하는 항만 geometry를 사용한다.
    이동 후 현재 지도의 중심점을 장기후측파랑 격자 탐색 기준점으로 저장한다.
    """
    try:
        result = driver.execute_script(
            """
            const portName=String(arguments[0]||'').trim();
            const anchors=[...document.querySelectorAll('a[data-layer-type="SPOT"][data-layer-search]')];
            const a=anchors.find(x=>(x.getAttribute('data-layer-search')||'').trim()===portName);
            if(!a) return {ok:false,message:'port anchor not found',port:portName,count:anchors.length};
            const geom=a.getAttribute('data-layer-geom')||'';
            const code=a.getAttribute('data-layer-value')||'';
            if(!geom) return {ok:false,message:'port geometry missing',port:portName,code:code};

            // WINK 자체 동작과 동일하게 항만(SPOT) 영역으로 이동한다.
            try{
                if(typeof commonMap!=='undefined' && commonMap && typeof commonMap.mapMoveTo==='function'){
                    commonMap.mapMoveTo('SPOT', geom);
                }else{
                    a.click();
                }
            }catch(e){
                try{a.click();}catch(e2){}
            }

            const seen=new Set();
            function isMap(o){
                return !!(o && typeof o.getView==='function' &&
                    typeof o.getPixelFromCoordinate==='function' &&
                    typeof o.getViewport==='function');
            }
            function walk(o,path,depth){
                if(!o || depth>4) return null;
                if(typeof o!=='object' && typeof o!=='function') return null;
                if(seen.has(o)) return null;
                seen.add(o);
                if(isMap(o)) return {obj:o,path:path};
                let keys=[];
                try{keys=Object.keys(o);}catch(e){}
                const preferred=['map','_map','olMap','mapObj','mapObject','commonMap'];
                keys=[...preferred,...keys.filter(k=>!preferred.includes(k))].slice(0,140);
                for(const k of keys){
                    let v=null; try{v=o[k];}catch(e){continue;}
                    if(v===window || v===document) continue;
                    const r=walk(v,path+'.'+k,depth+1);
                    if(r) return r;
                }
                return null;
            }
            let roots=[];
            try{ if(typeof commonMap!=='undefined' && commonMap) roots.push([commonMap,'commonMap']); }catch(e){}
            for(const k of ['commonMap','map','olMap','gMap','mapObj']){
                try{ if(window[k]) roots.push([window[k],'window.'+k]); }catch(e){}
            }
            let found=null;
            for(const [o,p] of roots){found=walk(o,p,0);if(found) break;}
            if(!found) return {ok:false,message:'OpenLayers map not found',port:portName,code:code};

            const m=found.obj;
            try{m.updateSize();m.renderSync();}catch(e){}
            const view=m.getView();
            const center=view.getCenter();
            const pixel=center ? m.getPixelFromCoordinate(center) : null;
            window.__wink_auto_map=m;
            window.__wink_auto_coord=center;
            return {
                ok:!!center,
                port:portName,
                code:code,
                path:found.path,
                geom:geom,
                zoom:view.getZoom(),
                center:center,
                pixel:pixel,
                size:(typeof m.getSize==='function')?m.getSize():null
            };
            """,
            str(port_name),
        )
        log.append(f"WINK 항만 영역 이동: {result}")
        return result or {}
    except Exception as exc:
        log.append(f"WINK 항만 영역 이동 오류: {exc}")
        return {"ok": False, "message": str(exc)}


def _wink_popup_state(driver) -> dict:
    try:
        return driver.execute_script(
            """
            function visible(e){
                if(!e) return false;
                const s=getComputedStyle(e), r=e.getBoundingClientRect();
                return s.display!=='none' && s.visibility!=='hidden' && r.width>2 && r.height>2;
            }
            const intro=document.querySelector('#pop_longterm_all');
            const popupContents=[...document.querySelectorAll('.ol-popup-content,.pop-contents,.popup-content,[class*="longterm"]')]
                .filter(e=>visible(e) && (!intro || !intro.contains(e)));
            let text=popupContents.map(e=>e.innerText||'').join(' ').replace(/\\s+/g,' ').trim();
            const candidates=[...document.querySelectorAll('a,button,input')]
                .filter(e=>visible(e) && (!intro || !intro.contains(e)));
            const downs=candidates.filter(e=>/다운로드|내려받기|자료받기|csv|excel|xlsx|xls|txt|7z|zip/i.test(
                (e.innerText||e.value||e.title||e.getAttribute('download')||'').trim()
            ));
            return {visible:popupContents.length>0, text:text.slice(0,800), downloadCount:downs.length};
            """
        ) or {}
    except Exception:
        return {}


def _wink_dispatch_map_pixel(driver, x: float, y: float) -> bool:
    """OpenLayers viewport에 마우스 이벤트를 전달한다(보조 경로)."""
    try:
        return bool(driver.execute_script(
            """
            const m=window.__wink_auto_map;
            if(!m) return false;
            const vp=m.getViewport();
            const r=vp.getBoundingClientRect();
            const cx=r.left+Number(arguments[0]), cy=r.top+Number(arguments[1]);
            const down={bubbles:true,cancelable:true,clientX:cx,clientY:cy,button:0,buttons:1,view:window,pointerId:1,pointerType:'mouse',isPrimary:true};
            const up={...down,buttons:0};
            try{vp.dispatchEvent(new PointerEvent('pointermove',up));}catch(e){}
            try{vp.dispatchEvent(new MouseEvent('mousemove',up));}catch(e){}
            try{vp.dispatchEvent(new PointerEvent('pointerdown',down));}catch(e){}
            try{vp.dispatchEvent(new MouseEvent('mousedown',down));}catch(e){}
            try{vp.dispatchEvent(new PointerEvent('pointerup',up));}catch(e){}
            try{vp.dispatchEvent(new MouseEvent('mouseup',up));}catch(e){}
            try{vp.dispatchEvent(new MouseEvent('click',up));}catch(e){}
            return true;
            """,
            float(x), float(y),
        ))
    except Exception:
        return False


def _wink_real_click_pixel(driver, x: float, y: float, log: list[str]) -> bool:
    """Selenium WebDriver의 실제 포인터 액션으로 지도 픽셀을 클릭한다.

    JS로 만든 synthetic click보다 OpenLayers singleclick 이벤트에서 훨씬 안정적이다.
    """
    try:
        from selenium.webdriver.common.action_chains import ActionChains
        from selenium.webdriver.common.by import By
        el = driver.find_element(By.ID, "map_article")
        rect = el.rect
        # Selenium move_to_element_with_offset은 요소의 중앙을 기준으로 offset을 적용한다.
        ox = float(x) - float(rect.get("width", 0)) / 2.0
        oy = float(y) - float(rect.get("height", 0)) / 2.0
        ActionChains(driver).move_to_element_with_offset(el, ox, oy).click().perform()
        log.append(f"WebDriver 실제 지도 클릭: pixel=({x:.1f},{y:.1f})")
        return True
    except Exception as exc:
        log.append(f"WebDriver 실제 클릭 실패 → JS 클릭 보조경로 사용: {exc}")
        return _wink_dispatch_map_pixel(driver, x, y)


def _wink_find_red_grid_pixel(driver, log: list[str], radius: Optional[int] = None) -> Optional[Tuple[float, float]]:
    """지도 캔버스에서 대상 좌표와 가장 가까운 '진한 빨간색' 장기후측파랑 격자점을 찾는다.

    v13은 대상 주변 160px만 찾았지만 WINK는 전국 축척에서 격자점이 가장 안정적으로
    렌더링되므로 v13은 기본적으로 현재 지도 전체를 검색한다. 주황색 인프라 표시는
    제외하도록 색상 조건도 더 엄격하게 했다.
    """
    try:
        result = driver.execute_script(
            """
            const m=window.__wink_auto_map, coord=window.__wink_auto_coord;
            if(!m||!coord) return null;
            const vp=m.getViewport(), mapRect=vp.getBoundingClientRect();
            const p=m.getPixelFromCoordinate(coord);
            if(!p) return null;
            const rad=arguments[0]===null ? null : Number(arguments[0]);
            let best=null, bestCanvas=null;
            function isRed(r,g,b,a){
                // WINK 장기후측파랑 = 진한 빨간 점. 주황색 상세역 표식은 최대한 제외.
                return a>130 && r>175 && g<90 && b<115 && r>g*2.0 && r>b*1.55;
            }
            for(const cv of vp.querySelectorAll('canvas')){
                const rect=cv.getBoundingClientRect();
                if(rect.width<10||rect.height<10) continue;
                let ctx=null; try{ctx=cv.getContext('2d',{willReadFrequently:true});}catch(e){continue;}
                if(!ctx) continue;
                const sx=cv.width/rect.width, sy=cv.height/rect.height;
                const targetClientX=mapRect.left+p[0], targetClientY=mapRect.top+p[1];
                const tcx=(targetClientX-rect.left)*sx, tcy=(targetClientY-rect.top)*sy;
                let x0=0,y0=0,x1=cv.width-1,y1=cv.height-1;
                if(rad!==null){
                    const rr=Math.max(10,rad*Math.max(sx,sy));
                    x0=Math.max(0,Math.floor(tcx-rr)); y0=Math.max(0,Math.floor(tcy-rr));
                    x1=Math.min(cv.width-1,Math.ceil(tcx+rr)); y1=Math.min(cv.height-1,Math.ceil(tcy+rr));
                }
                let data=null;
                try{data=ctx.getImageData(x0,y0,x1-x0+1,y1-y0+1);}catch(e){continue;}
                const w=data.width,h=data.height, arr=data.data;
                for(let yy=0;yy<h;yy++){
                    for(let xx=0;xx<w;xx++){
                        const i=(yy*w+xx)*4, r=arr[i],g=arr[i+1],b=arr[i+2],a=arr[i+3];
                        if(!isRed(r,g,b,a)) continue;
                        const cx=(x0+xx)/sx+rect.left-mapRect.left;
                        const cy=(y0+yy)/sy+rect.top-mapRect.top;
                        const d2=(cx-p[0])*(cx-p[0])+(cy-p[1])*(cy-p[1]);
                        if(!best || d2<best.d2){
                            best={x:cx,y:cy,d2:d2,cv:cv,rect:rect,sx:sx,sy:sy,rawX:x0+xx,rawY:y0+yy};
                            bestCanvas=cv;
                        }
                    }
                }
            }
            if(!best) return null;

            // 점 하나의 가장자리 픽셀 대신 주변 빨간 픽셀의 무게중심을 눌러 클릭 안정성 향상
            try{
                const cv=bestCanvas, ctx=cv.getContext('2d',{willReadFrequently:true});
                const rr=8*Math.max(best.sx,best.sy);
                const x0=Math.max(0,Math.floor(best.rawX-rr)), y0=Math.max(0,Math.floor(best.rawY-rr));
                const x1=Math.min(cv.width-1,Math.ceil(best.rawX+rr)), y1=Math.min(cv.height-1,Math.ceil(best.rawY+rr));
                const data=ctx.getImageData(x0,y0,x1-x0+1,y1-y0+1), arr=data.data;
                let sxm=0,sym=0,n=0;
                for(let yy=0;yy<data.height;yy++) for(let xx=0;xx<data.width;xx++){
                    const i=(yy*data.width+xx)*4;
                    if(isRed(arr[i],arr[i+1],arr[i+2],arr[i+3])){sxm+=x0+xx;sym+=y0+yy;n++;}
                }
                if(n>0){
                    best.x=(sxm/n)/best.sx+best.rect.left-mapRect.left;
                    best.y=(sym/n)/best.sy+best.rect.top-mapRect.top;
                }
            }catch(e){}
            return {x:best.x,y:best.y,d2:best.d2,targetX:p[0],targetY:p[1]};
            """,
            None if radius is None else int(radius),
        )
        if result and result.get("x") is not None:
            dist=(float(result.get("d2",0))**0.5)
            log.append(
                f"WINK 빨간 격자점 탐지: target=({result.get('targetX',0):.1f},{result.get('targetY',0):.1f}), "
                f"grid=({result['x']:.1f},{result['y']:.1f}), 화면거리={dist:.1f}px"
            )
            return float(result["x"]), float(result["y"])
    except Exception as exc:
        log.append(f"빨간 격자점 캔버스 탐색 실패: {exc}")
    return None


def _wink_click_nearest_grid_for_port(driver, port_name: str, log: list[str]) -> bool:
    """선택한 WINK 항만 영역으로 이동한 뒤 지도 중심과 가장 가까운 장기후측파랑 격자점을 클릭한다."""
    prep = _wink_prepare_port_target(driver, port_name, log)
    if not prep.get("ok"):
        return False

    # 항만영역 이동 후 WMS/캔버스와 장기후측파랑 격자가 다시 그려질 시간을 확보한다.
    time.sleep(4.0)

    # 1순위: 항만 영역 화면 전체에서 중심점과 가장 가까운 빨간 장기후측파랑 점 탐색
    red = _wink_find_red_grid_pixel(driver, log, radius=None)
    if red:
        _wink_real_click_pixel(driver, red[0], red[1], log)
        for _ in range(8):
            time.sleep(0.45)
            state = _wink_popup_state(driver)
            if state.get("downloadCount", 0) > 0 or (
                state.get("visible") and ("다운" in state.get("text", "") or "위치" in state.get("text", ""))
            ):
                log.append(f"장기후측파랑 격자 팝업 열림(항만 중심 최근접): {state}")
                return True

    # 2순위: 현재 지도 중심점 주변의 OpenLayers 피처 탐색
    try:
        hit = driver.execute_script(
            """
            const m=window.__wink_auto_map, coord=window.__wink_auto_coord;
            if(!m||!coord || typeof m.forEachFeatureAtPixel!=='function') return null;
            const p=m.getPixelFromCoordinate(coord); if(!p) return null;
            let found=null;
            for(const tol of [8,16,28,45,70,110,160,220,300]){
                try{
                    m.forEachFeatureAtPixel(p,function(f,l){
                        if(found) return f;
                        let c=null;
                        try{const g=f.getGeometry(); if(g){c=(g.getClosestPoint?g.getClosestPoint(coord):(g.getCoordinates?g.getCoordinates():null));}}catch(e){}
                        if(c){found={coord:c,props:(f.getProperties?f.getProperties():{})};return f;}
                    },{hitTolerance:tol});
                }catch(e){}
                if(found) break;
            }
            if(!found) return null;
            const pp=m.getPixelFromCoordinate(found.coord);
            return pp?{x:pp[0],y:pp[1],keys:Object.keys(found.props||{}).slice(0,30)}:null;
            """
        )
        if hit:
            log.append(
                f"OpenLayers 항만 주변 피처 후보: pixel=({hit.get('x'):.1f},{hit.get('y'):.1f}), 속성={hit.get('keys')}"
            )
            _wink_real_click_pixel(driver, float(hit.get("x")), float(hit.get("y")), log)
            time.sleep(1.5)
            state = _wink_popup_state(driver)
            if state.get("downloadCount", 0) > 0 or (state.get("visible") and "다운" in state.get("text", "")):
                log.append(f"장기후측파랑 격자 팝업 열림(항만 주변 벡터): {state}")
                return True
    except Exception as exc:
        log.append(f"OpenLayers 항만 주변 피처 탐색 실패: {exc}")

    # 3순위: 중심점 반경 360px 재탐색
    red = _wink_find_red_grid_pixel(driver, log, radius=360)
    if red:
        _wink_real_click_pixel(driver, red[0], red[1], log)
        time.sleep(1.5)
        state = _wink_popup_state(driver)
        if state.get("downloadCount", 0) > 0 or (state.get("visible") and "다운" in state.get("text", "")):
            log.append(f"장기후측파랑 격자 팝업 열림(항만 국소 재탐색): {state}")
            return True

    log.append(f"선택 항만({port_name}) 주변에서 장기후측파랑 개별 다운로드 팝업을 열지 못함")
    return False


def _wink_click_download(driver, download_dir: Path, log: list[str]) -> Path:
    started = time.time()
    clicked = driver.execute_script(
        """
        function visible(e){
            if(!e) return false;
            const s=getComputedStyle(e),r=e.getBoundingClientRect();
            return s.display!=='none'&&s.visibility!=='hidden'&&r.width>2&&r.height>2;
        }
        const intro=document.querySelector('#pop_longterm_all');
        const els=[...document.querySelectorAll('a,button,input,span')].filter(e=>visible(e) && (!intro || !intro.contains(e)));
        function d(e){return [e.innerText,e.value,e.title,e.alt,e.getAttribute('aria-label')].filter(Boolean).join(' ');}
        const ranked=[];
        for(const e of els){
            const t=d(e),u=t.toUpperCase(); let score=0;
            if(u.includes('CSV')) score+=12;
            if(u.includes('TXT')||u.includes('DAT')) score+=11;
            if(u.includes('EXCEL')||t.includes('엑셀')||u.includes('XLS')) score+=10;
            if(t.includes('다운로드')||t.includes('자료받기')||t.includes('내려받기')) score+=8;
            if(t.includes('장기')||t.includes('후측')) score+=2;
            if(score>0) ranked.push([score,e,t]);
        }
        ranked.sort((a,b)=>b[0]-a[0]);
        for(const [score,e,t] of ranked){
            const c=e.closest('a,button')||e;
            try{c.click();return t;}catch(err){}
        }
        return '';
        """
    )
    if not clicked:
        raise RuntimeError("WINK 격자 팝업에서 개별자료 다운로드 버튼을 찾지 못했습니다.")
    log.append(f"WINK 개별 격자 다운로드 클릭: {str(clicked)[:100]}")

    path = _wait_download(download_dir, started, timeout=55)
    if path is None:
        try:
            driver.execute_script(
                """
                function visible(e){const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>2&&r.height>2;}
                const els=[...document.querySelectorAll('a,button,input,span')].filter(visible);
                const e=els.find(x=>/확인|저장|다운로드/.test((x.innerText||x.value||'').trim()));
                if(e){(e.closest('a,button')||e).click();}
                """
            )
        except Exception:
            pass
        path = _wait_download(download_dir, started, timeout=35)
    if path is None:
        raise RuntimeError("WINK 개별자료 다운로드 버튼은 눌렀지만 파일을 확인하지 못했습니다.")
    return path


def auto_download_wink_longterm_wave(port_name: str, port_code: str, start_year: int, end_year: int, headless: bool = True) -> dict:
    """WINK 장기후측파랑 웹 화면에서 선택한 항만 영역의 최근접 격자 원자료를 자동 다운로드한다."""
    log = []
    driver = None
    with tempfile.TemporaryDirectory(prefix="wink_wave_") as tmp:
        tmpdir = Path(tmp)
        try:
            driver, browser_name = _make_portal_driver(tmpdir, headless=headless)
            log.append(f"자동 브라우저: {browser_name}")
            driver.get(WINK_LONGTERM_URL)
            WebDriverWait = _selenium_imports()["WebDriverWait"]
            WebDriverWait(driver, 25).until(lambda d: d.execute_script("return document.readyState") == "complete")
            log.append("WINK 파랑인프라DB 접속")

            if not _wink_prepare_longterm_layer(driver, log):
                raise RuntimeError("WINK 화면에서 장기후측파랑 레이어(legendGrid)를 확인하지 못했습니다.")
            time.sleep(2.0)

            if not _wink_click_nearest_grid_for_port(driver, port_name, log):
                raise RuntimeError(
                    f"선택한 항만({port_name}) 주변의 WINK 장기후측파랑 격자점을 자동 선택하지 못했습니다. "
                    "브라우저 화면 표시를 켜 위치를 확인하거나 WINK 원자료 수동 업로드를 사용하세요."
                )
            time.sleep(0.8)

            # WINK 개별 격자 원자료는 보유기간 전체를 내려받고,
            # 사용자가 선택한 연도바는 다운로드 후 로컬에서 필터링한다.
            log.append(f"WINK 선택 항만: {port_name} ({port_code})")
            log.append(f"WINK 분석기간(로컬 필터): {start_year}~{end_year}")
            downloaded = _wink_click_download(driver, tmpdir, log)
            raw = downloaded.read_bytes()
            parsed_df, parsed_status = parse_wink_wave_bytes(raw, downloaded.name)
            if not parsed_status.get("ok"):
                raise RuntimeError(parsed_status.get("message"))

            safe_name = re.sub(r"[^0-9A-Za-z가-힣_.-]+", "_", downloaded.name)
            safe_port = re.sub(r"[^0-9A-Za-z가-힣_.-]+", "_", port_name)
            out_name = f"wink_{port_code}_{safe_port}_{start_year}_{end_year}_{safe_name}"
            (WINK_CACHE_DIR / out_name).write_bytes(raw)
            log.append(f"WINK 원자료 캐시 저장: {out_name}")
            return {
                "ok": True,
                "message": f"WINK {port_name} 주변 장기후측파랑 원자료 자동수집 성공: {downloaded.name}",
                "raw": raw,
                "filename": downloaded.name,
                "data": parsed_df,
                "parse_status": parsed_status,
                "port_name": port_name,
                "port_code": port_code,
                "log": log,
            }
        except Exception as exc:
            debug_html = BASE_DIR / "wink_debug_longterm.html"
            debug_png = BASE_DIR / "wink_debug_longterm.png"
            try:
                if driver is not None:
                    debug_html.write_text(driver.page_source, encoding="utf-8")
                    driver.save_screenshot(str(debug_png))
            except Exception:
                pass
            return {
                "ok": False,
                "message": str(exc),
                "debug_html": str(debug_html),
                "debug_png": str(debug_png),
                "log": log,
            }
        finally:
            if driver is not None:
                try:
                    driver.quit()
                except Exception:
                    pass


# =============================================================================
# 5-3. WINK 관측지점 선택 방식 (v17)
# =============================================================================
# WINK의 "파랑 관측자료" 화면을 장기후측파랑 모드로 열면 좌측에 관측지점 목록이
# 표시된다. 이 목록의 지점을 위치 기준점으로 사용하고, 지도에서 가장 가까운
# 장기후측파랑 격자(빨간 + 표시)를 선택해 원자료를 다운로드한다.
WINK_LONGTERM_STATION_URL = "https://www.wink.go.kr/map/selectMapVw.do?mapType=longterm"

# WINK 사이트 일시 장애/DOM 변경 시에도 선택창 자체가 사라지지 않도록 최소 fallback 제공.
# 정상 상황에서는 아래 목록이 아니라 WINK 페이지의 현재 좌측 목록을 Selenium으로 읽는다.
WINK_STATION_FALLBACK = [
    "가거도", "가거도항", "군산항", "덕적도", "부안", "새만금신항",
    "서해(170)", "서해(190)", "서해(206)", "안마도", "외연도", "인천",
    "인천신항", "칠발도", "태안(흑도)", "홍도", "흑산도",
    "목포", "완도", "여수", "거문도", "통영", "부산", "울산",
    "포항", "후포", "동해", "묵호", "강릉", "속초", "울릉도",
    "제주", "서귀포", "성산", "고산",
]


def _wink_normalize_station_labels(values):
    """WINK 좌측메뉴 DOM에서 얻은 문자열 중 실제 관측지점명 후보만 정리한다."""
    ignore = {
        "", "전체", "서해안", "남해안", "동해안", "HOME", "WINK소개",
        "바람장자료", "장기 후측파랑 자료", "과거 단기파랑 관측자료", "파랑 인프라 DB",
        "자료실", "의견수렴", "도움말", "정보보기", "확대", "축소", "전체보기",
        "거리측정", "면적측정", "초기화", "인쇄", "일반지도",
    }
    out = []
    seen = set()
    for value in values or []:
        t = re.sub(r"\s+", " ", str(value or "")).strip()
        if not t or t in ignore or len(t) > 40:
            continue
        if t.startswith("검색") or "여러개 검색" in t:
            continue
        if re.fullmatch(r"\d+(?:[-:]\d+)?", t):
            continue
        if t not in seen:
            seen.add(t)
            out.append(t)
    return out


@st.cache_data(ttl=60 * 60 * 12, show_spinner=False)
def fetch_wink_station_catalog():
    """WINK 장기후측파랑 화면의 좌측 관측지점명을 동적으로 읽는다."""
    driver = None
    with tempfile.TemporaryDirectory(prefix="wink_station_list_") as td:
        try:
            driver, browser_name = _make_portal_driver(Path(td), headless=True)
            driver.get(WINK_LONGTERM_STATION_URL)
            S = _selenium_imports()
            S["WebDriverWait"](driver, 30).until(
                lambda d: d.execute_script("return document.readyState") == "complete"
            )
            time.sleep(2.5)
            # 해역별 목록이 접혀 있어도 전국 지점을 얻기 위해 세 해역 헤더를 한 번씩 펼친다.
            try:
                driver.execute_script(
                    r"""
                    const names=['서해안','남해안','동해안'];
                    for(const name of names){
                        const els=[...document.querySelectorAll('a,button,div,span')].filter(e=>
                            ((e.innerText||e.textContent||'').replace(/\s+/g,' ').trim()===name));
                        if(els.length){
                            const c=els[0].closest('a,button,[role=\"button\"],[onclick]')||els[0];
                            try{c.click();}catch(e){}
                        }
                    }
                    """
                )
                time.sleep(1.0)
            except Exception:
                pass

            raw = driver.execute_script(
                r"""
                const roots=[
                    document.querySelector('.map-lside'),
                    document.querySelector('.map-lside-box'),
                    document.querySelector('[class*="lside-contents"]'),
                    document.querySelector('[class*="left"]')
                ].filter(Boolean);
                const root=roots[0] || document.body;
                const vals=[];
                // 숨겨진(접힌) 해역의 항목도 textContent로 읽는다.
                for(const e of root.querySelectorAll('li, a, button, [role="button"]')){
                    let t=(e.innerText||e.textContent||'').replace(/\s+/g,' ').trim();
                    if(!t || t.length>40) continue;
                    vals.push(t);
                }
                for(const e of root.querySelectorAll('span, div')){
                    const t=(e.innerText||e.textContent||'').replace(/\s+/g,' ').trim();
                    if(t && t.length<=30 && e.children.length<=2) vals.push(t);
                }
                return vals;
                """
            ) or []
            stations = _wink_normalize_station_labels(raw)
            if len(stations) < 8:
                raise RuntimeError(f"WINK 좌측 지점 목록을 충분히 읽지 못했습니다({len(stations)}개).")
            return {
                "ok": True,
                "stations": stations,
                "message": f"WINK 좌측 관측지점 {len(stations)}개 자동확인",
                "browser": browser_name,
            }
        except Exception as exc:
            return {
                "ok": False,
                "stations": list(WINK_STATION_FALLBACK),
                "message": f"WINK 지점목록 자동확인 실패 → 기본 목록 사용: {exc}",
            }
        finally:
            if driver is not None:
                try:
                    driver.quit()
                except Exception:
                    pass


def _suggest_wink_station_name(asos_station_name: str, station_options: list[str]) -> str:
    """해안 ASOS 명칭과 WINK 좌측 지점명을 느슨하게 매칭해 기본 선택값을 정한다."""
    base = _station_base_name(asos_station_name)
    options = [str(x) for x in station_options if str(x).strip()]
    if not options:
        return ""
    inland = {"서울", "수원", "광주", "전주", "청주", "대전", "대구", "안동", "진주", "원주", "춘천", "상주", "추풍령", "파주", "동두천", "대관령"}
    if base in inland:
        return ""
    for cand in (base, base + "항"):
        if cand in options:
            return cand
    for x in options:
        if base and (x.startswith(base) or base in x):
            return x
    return ""


def _wink_bind_map_reference(driver, log: list[str]) -> dict:
    """현재 WINK OpenLayers 지도와 중심점을 window.__wink_auto_*에 저장한다."""
    try:
        result = driver.execute_script(
            r"""
            const seen=new Set();
            function isMap(o){
                return !!(o && typeof o.getView==='function' &&
                    typeof o.getPixelFromCoordinate==='function' &&
                    typeof o.getViewport==='function');
            }
            function walk(o,path,depth){
                if(!o || depth>4) return null;
                if(typeof o!=='object' && typeof o!=='function') return null;
                if(seen.has(o)) return null;
                seen.add(o);
                if(isMap(o)) return {obj:o,path:path};
                let keys=[]; try{keys=Object.keys(o);}catch(e){}
                const preferred=['map','_map','olMap','mapObj','mapObject','commonMap'];
                keys=[...preferred,...keys.filter(k=>!preferred.includes(k))].slice(0,160);
                for(const k of keys){
                    let v=null; try{v=o[k];}catch(e){continue;}
                    if(v===window || v===document) continue;
                    const r=walk(v,path+'.'+k,depth+1); if(r) return r;
                }
                return null;
            }
            const roots=[];
            for(const k of ['commonMap','map','olMap','gMap','mapObj']){
                try{ if(window[k]) roots.push([window[k],'window.'+k]); }catch(e){}
            }
            try{ if(typeof commonMap!=='undefined' && commonMap) roots.unshift([commonMap,'commonMap']); }catch(e){}
            let found=null;
            for(const [o,p] of roots){ found=walk(o,p,0); if(found) break; }
            if(!found) return {ok:false,message:'OpenLayers map not found'};
            const m=found.obj;
            try{m.updateSize();m.renderSync();}catch(e){}
            const view=m.getView(), center=view.getCenter();
            window.__wink_auto_map=m;
            window.__wink_auto_coord=center;
            return {ok:!!center,path:found.path,center:center,zoom:view.getZoom(),size:m.getSize?m.getSize():null};
            """
        ) or {}
        log.append(f"WINK 지도 객체 연결: {result}")
        return result
    except Exception as exc:
        log.append(f"WINK 지도 객체 연결 실패: {exc}")
        return {"ok": False, "message": str(exc)}


def _wink_close_visible_dialogs(driver):
    try:
        driver.execute_script(
            r"""
            const selectors=['.modal.show .btn-close','.modal.show [data-bs-dismiss="modal"]',
                '.pop-wrap:not([style*="display: none"]) [id$="_close"]',
                '.ol-popup .closeBox','.swal2-close'];
            for(const sel of selectors){
                for(const e of document.querySelectorAll(sel)){try{e.click();}catch(err){}}
            }
            """
        )
    except Exception:
        pass


def _wink_select_left_station(driver, station_name: str, log: list[str]) -> dict:
    """WINK mapType=longterm 좌측 관측지점 목록에서 이름으로 지점을 선택한다."""
    S = _selenium_imports()
    By, Keys = S["By"], S["Keys"]

    if not _wink_bind_map_reference(driver, log).get("ok"):
        return {"ok": False, "message": "WINK 지도 객체를 찾지 못했습니다."}

    def center_now():
        try:
            return driver.execute_script(
                "const m=window.__wink_auto_map; const c=m&&m.getView?m.getView().getCenter():null; return c?c.slice():null;"
            )
        except Exception:
            return None

    before = center_now()
    try:
        search_inputs = driver.find_elements(By.CSS_SELECTOR, 'input[type="text"]')
        search = None
        for e in search_inputs:
            try:
                meta = " ".join([
                    e.get_attribute("placeholder") or "", e.get_attribute("title") or "",
                    e.get_attribute("id") or "", e.get_attribute("class") or ""
                ])
                if "검색" in meta or "search" in meta.lower():
                    search = e
                    break
            except Exception:
                continue
        if search is not None:
            search.clear()
            search.send_keys(str(station_name))
            search.send_keys(Keys.ENTER)
            log.append(f"WINK 좌측 검색어 입력: {station_name}")
            time.sleep(1.2)
    except Exception as exc:
        log.append(f"WINK 검색창 입력 보조경로 실패: {exc}")

    clicked = driver.execute_script(
        r"""
        const name=String(arguments[0]||'').trim();
        function visible(e){
            if(!e) return false;
            const s=getComputedStyle(e),r=e.getBoundingClientRect();
            return s.display!=='none'&&s.visibility!=='hidden'&&r.width>2&&r.height>2;
        }
        const root=document.querySelector('.map-lside')||document.querySelector('.map-lside-box')||document.body;
        let matches=[...root.querySelectorAll('a,button,span,div,li')].filter(e=>{
            if(!visible(e)) return false;
            const t=(e.innerText||e.textContent||'').replace(/\s+/g,' ').trim();
            return t===name;
        });
        matches.sort((a,b)=>{
            const ra=a.getBoundingClientRect(),rb=b.getBoundingClientRect();
            return (ra.width*ra.height)-(rb.width*rb.height);
        });
        if(!matches.length) return {ok:false,message:'exact station text not found'};
        const e=matches[0];
        const row=e.closest('li') || e.parentElement || e;
        const attrs={};
        for(const node of [e,row]){
            if(!node||!node.attributes) continue;
            for(const a of node.attributes){
                if(a.name.startsWith('data-')||a.name==='onclick'||a.name==='href') attrs[a.name]=a.value;
            }
        }
        const c=e.closest('a,button,[role="button"],[onclick]') || e;
        try{c.scrollIntoView({block:'center'}); c.click(); return {ok:true,attrs:attrs,tag:c.tagName};}
        catch(err){return {ok:false,message:String(err),attrs:attrs};}
        """,
        str(station_name),
    ) or {}
    log.append(f"WINK 좌측 지점 1차 클릭: {clicked}")
    time.sleep(2.0)

    after = center_now()
    moved = bool(before and after and len(before)>=2 and len(after)>=2 and (abs(float(before[0])-float(after[0])) + abs(float(before[1])-float(after[1])) > 1e-6))

    if not moved:
        try:
            candidates = driver.execute_script(
                r"""
                const name=String(arguments[0]||'').trim();
                function visible(e){const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>2&&r.height>2;}
                const root=document.querySelector('.map-lside')||document.querySelector('.map-lside-box')||document.body;
                const exact=[...root.querySelectorAll('span,div,a,button,li')].filter(e=>visible(e)&&((e.innerText||e.textContent||'').replace(/\s+/g,' ').trim()===name));
                if(!exact.length) return [];
                const row=exact[0].closest('li')||exact[0].parentElement;
                if(!row) return [];
                const els=[...row.querySelectorAll('a,button,[role="button"],[onclick]')].filter(visible);
                return els.map((e,i)=>({i:i,txt:(e.innerText||e.title||e.getAttribute('aria-label')||'').trim(),html:e.outerHTML.slice(0,260)}));
                """,
                str(station_name),
            ) or []
            for item in candidates[:6]:
                _wink_close_visible_dialogs(driver)
                old = center_now()
                result = driver.execute_script(
                    r"""
                    const name=String(arguments[0]||'').trim(), idx=Number(arguments[1]);
                    function visible(e){const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>2&&r.height>2;}
                    const root=document.querySelector('.map-lside')||document.querySelector('.map-lside-box')||document.body;
                    const exact=[...root.querySelectorAll('span,div,a,button,li')].filter(e=>visible(e)&&((e.innerText||e.textContent||'').replace(/\s+/g,' ').trim()===name));
                    if(!exact.length) return false;
                    const row=exact[0].closest('li')||exact[0].parentElement;if(!row)return false;
                    const els=[...row.querySelectorAll('a,button,[role="button"],[onclick]')].filter(visible);
                    if(!els[idx]) return false;
                    try{els[idx].click();return true;}catch(e){return false;}
                    """,
                    str(station_name), int(item.get("i", 0)),
                )
                if not result:
                    continue
                time.sleep(1.3)
                new = center_now()
                if old and new and len(old)>=2 and len(new)>=2 and (abs(float(old[0])-float(new[0])) + abs(float(old[1])-float(new[1])) > 1e-6):
                    moved = True
                    log.append(f"WINK 지점 행 버튼으로 지도 이동 성공: {item}")
                    break
        except Exception as exc:
            log.append(f"WINK 지점 행 버튼 탐색 실패: {exc}")

    if not moved:
        log.append(f"WINK 좌측 지점({station_name})은 찾았지만 지도 이동 동작을 확인하지 못했습니다.")
        return {"ok": False, "message": f"WINK 좌측 지점({station_name}) 선택 후 지도가 이동하지 않았습니다."}

    bind = _wink_bind_map_reference(driver, log)
    if bind.get("ok"):
        return {"ok": True, "station": station_name, "moved": moved, "center": bind.get("center"), "zoom": bind.get("zoom")}
    return {"ok": False, "message": f"WINK 지점({station_name}) 선택 후 지도 중심을 확인하지 못했습니다."}


def _wink_click_nearest_grid_for_station(driver, station_name: str, log: list[str]) -> bool:
    """좌측에서 선택한 관측지점 위치를 기준으로 가장 가까운 장기후측파랑 격자점을 클릭한다."""
    prep = _wink_select_left_station(driver, station_name, log)
    if not prep.get("ok"):
        log.append(f"WINK 지점 선택 실패: {prep}")
        return False
    time.sleep(3.0)

    for radius in (260, 420, None):
        red = _wink_find_red_grid_pixel(driver, log, radius=radius)
        if not red:
            continue
        _wink_real_click_pixel(driver, red[0], red[1], log)
        for _ in range(8):
            time.sleep(0.45)
            state = _wink_popup_state(driver)
            if state.get("downloadCount", 0) > 0 or (
                state.get("visible") and ("다운" in state.get("text", "") or "위치" in state.get("text", ""))
            ):
                log.append(f"장기후측파랑 격자 팝업 열림({station_name} 기준): {state}")
                return True
    log.append(f"선택 지점({station_name}) 주변에서 장기후측파랑 격자 다운로드 팝업을 열지 못함")
    return False


def auto_download_wink_longterm_wave_by_station(station_name: str, start_year: int, end_year: int, headless: bool = True) -> dict:
    """WINK 좌측 관측지점 선택 → 최근접 장기후측파랑 격자 → 원자료 다운로드."""
    log = []
    driver = None
    with tempfile.TemporaryDirectory(prefix="wink_wave_station_") as tmp:
        tmpdir = Path(tmp)
        try:
            driver, browser_name = _make_portal_driver(tmpdir, headless=headless)
            log.append(f"자동 브라우저: {browser_name}")
            driver.get(WINK_LONGTERM_STATION_URL)
            S = _selenium_imports()
            S["WebDriverWait"](driver, 30).until(
                lambda d: d.execute_script("return document.readyState") == "complete"
            )
            log.append("WINK 장기후측파랑 관측지점 화면 접속")
            time.sleep(2.5)

            if not _wink_click_nearest_grid_for_station(driver, station_name, log):
                raise RuntimeError(
                    f"WINK 좌측 지점({station_name})을 기준으로 장기후측파랑 격자점을 자동 선택하지 못했습니다. "
                    "브라우저 화면 표시를 켜 실제 선택 동작을 확인하거나 WINK 원자료 수동 업로드를 사용하세요."
                )
            time.sleep(0.8)

            log.append(f"WINK 선택 기준지점: {station_name}")
            log.append(f"WINK 분석기간(다운로드 후 필터): {start_year}~{end_year}")
            downloaded = _wink_click_download(driver, tmpdir, log)
            raw = downloaded.read_bytes()
            parsed_df, parsed_status = parse_wink_wave_bytes(raw, downloaded.name)
            if not parsed_status.get("ok"):
                raise RuntimeError(parsed_status.get("message"))

            safe_name = re.sub(r"[^0-9A-Za-z가-힣_.-]+", "_", downloaded.name)
            safe_station = re.sub(r"[^0-9A-Za-z가-힣_.-]+", "_", station_name)
            out_name = f"wink_station_{safe_station}_{start_year}_{end_year}_{safe_name}"
            (WINK_CACHE_DIR / out_name).write_bytes(raw)
            log.append(f"WINK 원자료 캐시 저장: {out_name}")
            return {
                "ok": True,
                "message": f"WINK {station_name} 기준 장기후측파랑 원자료 자동수집 성공: {downloaded.name}",
                "raw": raw,
                "filename": downloaded.name,
                "data": parsed_df,
                "parse_status": parsed_status,
                "station_name": station_name,
                "log": log,
            }
        except Exception as exc:
            debug_html = BASE_DIR / "wink_debug_longterm.html"
            debug_png = BASE_DIR / "wink_debug_longterm.png"
            try:
                if driver is not None:
                    debug_html.write_text(driver.page_source, encoding="utf-8")
                    driver.save_screenshot(str(debug_png))
            except Exception:
                pass
            return {
                "ok": False,
                "message": str(exc),
                "debug_html": str(debug_html),
                "debug_png": str(debug_png),
                "log": log,
            }
        finally:
            if driver is not None:
                try:
                    driver.quit()
                except Exception:
                    pass


# =============================================================================
# 6. 피벗/풍향 함수
# =============================================================================



# =============================================================================
# 5-4. WINK 관측지점 파고·주기 계급별 출현율 자동수집 (v18)
# =============================================================================
# 중요: 이 방식은 빨간 + 기호(장기후측파랑 격자)가 아니라
# WINK 파랑관측자료 화면의 노랑/하늘/분홍 등 색이 채워진 원형 관측점을 사용한다.
# 관측점 선택 → '파랑정보' → '파고주기 계급별 출현율 다운로드' Excel을 사용한다.
WINK_OBS_URL = "https://www.wink.go.kr/map/selectMapVw.do"

# WINK 출현율 Excel 다운로드 시 사이트가 요구하는 소속기관 유형.
# 사용자가 사이드바에서 직접 선택한 값을 그대로 전달한다.
WINK_DOWNLOAD_ORG_TYPES = {
    "선택하세요": "",
    "정부기관": "01",
    "공공기관": "02",
    "대학교": "03",
    "시공사": "04",
    "엔지니어링 설계사": "05",
    "해양조사 전문기업": "06",
    "수치모델링 전문기업": "07",
    "기타": "99",
}



def _wink_excel_kind(raw: bytes) -> tuple[str, str]:
    """WINK 다운로드 바이트가 실제 Excel인지 파일 확장자와 무관하게 판정한다."""
    if not raw:
        return "empty", "빈 파일"

    # XLSX = ZIP 컨테이너. 단순 PK 파일이 아니라 실제 Excel workbook인지 확인.
    if raw[:4] == b"PK\x03\x04":
        try:
            with zipfile.ZipFile(io.BytesIO(raw), "r") as zf:
                names = set(zf.namelist())
                if "xl/workbook.xml" in names and "[Content_Types].xml" in names:
                    return "xlsx", "정상 XLSX"
                return "zip", "ZIP이지만 Excel workbook 구조가 아님"
        except Exception as exc:
            return "zip_bad", f"손상된 ZIP/XLSX: {exc}"

    # 구형 BIFF .xls = OLE Compound File
    if raw[:8] == b"\xD0\xCF\x11\xE0\xA1\xB1\x1A\xE1":
        return "xls", "정상 OLE/XLS"

    head = raw[:4096].lstrip().lower()
    if (
        head.startswith(b"<!doctype html")
        or head.startswith(b"<html")
        or b"<html" in head[:1000]
    ):
        return "html", "Excel 대신 HTML 응답을 받음"

    if head.startswith(b"{") or head.startswith(b"["):
        return "json", "Excel 대신 JSON 응답을 받음"

    return "unknown", f"알 수 없는 파일 형식 (magic={raw[:12]!r})"


def _wink_wait_valid_excel_download(
    download_dir: Path,
    started_at: float,
    timeout: float = 120.0,
) -> tuple[Optional[Path], list[str]]:
    """
    다운로드 폴더에서 '실제 Excel' 파일만 기다린다.

    Chrome이 오류 HTML/중간파일을 먼저 만들더라도 그것을 Excel로 오인하지 않는다.
    """
    download_dir = Path(download_dir)
    end = time.time() + float(timeout)
    invalid_seen = []
    stable = {}

    while time.time() < end:
        try:
            paths = [p for p in download_dir.iterdir() if p.is_file()]
        except Exception:
            paths = []

        # 다운로드 중 파일이 있으면 기다린다.
        partial_names = {
            p.name for p in paths
            if p.suffix.lower() in {".crdownload", ".part", ".tmp"}
        }

        candidates = []
        for p in paths:
            if p.name in partial_names or p.suffix.lower() in {".crdownload", ".part", ".tmp"}:
                continue
            try:
                if p.stat().st_mtime >= started_at - 3 and p.stat().st_size > 20:
                    candidates.append(p)
            except Exception:
                pass

        candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)

        for p in candidates:
            try:
                size = p.stat().st_size
                prev = stable.get(str(p))
                if prev == size:
                    raw = p.read_bytes()
                    kind, desc = _wink_excel_kind(raw)
                    if kind in {"xlsx", "xls"}:
                        return p, invalid_seen
                    marker = f"{p.name}: {desc}"
                    if marker not in invalid_seen:
                        invalid_seen.append(marker)
                stable[str(p)] = size
            except Exception:
                pass

        time.sleep(0.5)

    return None, invalid_seen


def _wink_safe_cache_write(raw: bytes, preferred_path: Path, log: list[str]) -> Optional[Path]:
    """
    캐시 파일이 Excel에서 열려 있어 PermissionError가 나도 전체 수집은 실패시키지 않는다.
    잠겨 있으면 타임스탬프가 붙은 다른 이름으로 저장하고, 그래도 실패하면 캐시만 생략한다.
    """
    preferred_path = Path(preferred_path)
    try:
        preferred_path.write_bytes(raw)
        return preferred_path
    except PermissionError as exc:
        log.append(f"WINK 캐시 원본명 저장 실패(파일 잠김): {exc}")
        alt = preferred_path.with_name(
            f"{preferred_path.stem}_{pd.Timestamp.now():%Y%m%d_%H%M%S}{preferred_path.suffix}"
        )
        try:
            alt.write_bytes(raw)
            log.append(f"WINK 캐시 대체명 저장: {alt.name}")
            return alt
        except Exception as exc2:
            log.append(f"WINK 캐시 저장 생략: {exc2}")
            return None
    except Exception as exc:
        log.append(f"WINK 캐시 저장 생략: {exc}")
        return None



def _wink_read_occurrence_excel(raw: bytes, filename: str = "wink_occurrence.xlsx"):
    """WINK '파고주기 계급별 출현율 다운로드' Excel을 읽는다.

    v32 핵심 수정:
    - 행 라벨인 '주기(s)'를 일반 데이터 열로 남기지 않고 DataFrame index로 설정
    - 파고 계급명 중복이 생기면 같은 계급끼리 합산해 열 index를 유일하게 유지
    - 이 구조가 calculate_wink_occurrence_nonwork / 화면표 생성 함수가 기대하는 형식

    반환 matrix 예:
        index = ['0.0~2.0', '2.0~4.0', ...]
        columns = ['0.0~0.5','0.5~1.0', ...]
    """
    if not raw:
        return pd.DataFrame(), {
            "ok": False,
            "message": "WINK 출현율 Excel이 비어 있습니다.",
        }

    kind, desc = _wink_excel_kind(raw)
    if kind not in {"xlsx", "xls"}:
        return pd.DataFrame(), {
            "ok": False,
            "message": (
                f"WINK 다운로드 결과가 실제 Excel이 아닙니다: {desc}. "
                "사이트가 오류페이지/중간응답을 내려줬을 가능성이 있습니다."
            ),
            "file_kind": kind,
        }

    try:
        engine = "openpyxl" if kind == "xlsx" else "xlrd"
        book = pd.read_excel(
            io.BytesIO(raw),
            sheet_name=None,
            header=None,
            engine=engine,
        )
    except Exception as exc:
        return pd.DataFrame(), {
            "ok": False,
            "message": (
                f"WINK 출현율 Excel을 읽지 못했습니다 "
                f"({kind}/{engine}): {type(exc).__name__}: {exc}"
            ),
            "file_kind": kind,
        }

    chosen = None
    header_row = None
    last_col = None
    for sh_name, df in book.items():
        if df is None or df.empty:
            continue
        for r in range(min(len(df), 20)):
            vals = [
                str(x).strip() if pd.notna(x) else ""
                for x in df.iloc[r].tolist()
            ]
            bin_count = sum(
                1 for x in vals
                if "~" in x and re.search(r"\d", x)
            )
            if bin_count >= 3 and any(x.lower() == "sum" for x in vals):
                chosen = df.copy()
                header_row = r
                try:
                    sum_idx = next(
                        i for i, x in enumerate(vals)
                        if x.lower() == "sum"
                    )
                except Exception:
                    sum_idx = len(vals) - 1
                last_col = sum_idx - 1
                break
        if chosen is not None:
            break

    if chosen is None or header_row is None or last_col is None or last_col < 1:
        return pd.DataFrame(), {
            "ok": False,
            "message": "WINK 출현율 Excel에서 파고/주기 계급표를 찾지 못했습니다.",
            "file_kind": kind,
        }

    # 파고계급 헤더 정리
    wave_labels = []
    for c in range(1, last_col + 1):
        label = str(chosen.iloc[header_row, c]).strip()
        label = label.replace("∼", "~").replace("～", "~")
        label = re.sub(r"\s*~\s*", "~", label)
        wave_labels.append(label)

    rows = []
    r = header_row + 1
    while r < len(chosen):
        period_label = (
            str(chosen.iloc[r, 0]).strip()
            if pd.notna(chosen.iloc[r, 0]) else ""
        )
        period_label = period_label.replace("∼", "~").replace("～", "~")
        period_label = re.sub(r"\s*~\s*", "~", period_label)

        if not period_label:
            r += 1
            continue
        if period_label.lower() == "sum" or period_label.startswith("*"):
            break
        if "~" not in period_label or not re.search(r"\d", period_label):
            r += 1
            continue

        vals = []
        for c in range(1, last_col + 1):
            v = pd.to_numeric(chosen.iloc[r, c], errors="coerce")
            vals.append(float(v) if pd.notna(v) else np.nan)
        rows.append([period_label] + vals)
        r += 1

    if not rows:
        return pd.DataFrame(), {
            "ok": False,
            "message": "WINK 출현율 Excel에서 주기 계급 행을 읽지 못했습니다.",
            "file_kind": kind,
        }

    matrix = pd.DataFrame(rows, columns=["주기(s)"] + wave_labels)

    # 중요: 주기 라벨은 열이 아니라 index로 사용한다.
    # 이전 v31은 '주기(s)' 열을 남긴 채 후속 함수에서 reset_index()를 하면서
    # 동일한 '주기(s)' 열이 2개가 되어 InvalidIndexError가 발생했다.
    matrix = matrix.set_index("주기(s)")
    matrix.index = matrix.index.astype(str)
    matrix.index.name = "주기(s)"

    # 값은 출현율(%) 숫자만 유지
    matrix = matrix.apply(pd.to_numeric, errors="coerce")

    # WINK 파일 구조 변경 등으로 동일 파고계급 열이 중복되어도 후속 concat/reindex가
    # 실패하지 않도록 중복 열을 같은 계급별 합으로 통합한다.
    if not matrix.columns.is_unique:
        ordered_cols = list(dict.fromkeys([str(c) for c in matrix.columns]))
        collapsed = {}
        for c in ordered_cols:
            part = matrix.loc[:, matrix.columns.astype(str) == c]
            collapsed[c] = part.sum(axis=1, min_count=1)
        matrix = pd.DataFrame(collapsed, index=matrix.index)

    # 혹시 WINK가 같은 주기계급 행을 중복 제공하면 같은 계급끼리 합산
    if not matrix.index.is_unique:
        order = list(dict.fromkeys(matrix.index.astype(str).tolist()))
        matrix = matrix.groupby(level=0, sort=False).sum(min_count=1)
        matrix = matrix.reindex(order)

    # 관측기간 추출
    coverage_start = coverage_end = None
    coverage = ""
    for _, df in book.items():
        for val in df.astype(str).fillna("").to_numpy().ravel():
            s = str(val)
            m = re.search(
                r"관측기간\s*[:：]?\s*"
                r"(\d{4})[.\-/ ]+(\d{1,2})[.\-/ ]+(\d{1,2})"
                r"\s*~\s*"
                r"(\d{4})[.\-/ ]+(\d{1,2})[.\-/ ]+(\d{1,2})",
                s,
            )
            if m:
                try:
                    coverage_start = pd.Timestamp(
                        int(m.group(1)), int(m.group(2)), int(m.group(3))
                    )
                    coverage_end = pd.Timestamp(
                        int(m.group(4)), int(m.group(5)), int(m.group(6))
                    )
                    coverage = f"{coverage_start.date()}~{coverage_end.date()}"
                except Exception:
                    pass
                break
        if coverage:
            break

    return matrix, {
        "ok": True,
        "message": (
            f"WINK 출현율 Excel 파싱 완료 ({kind}) · "
            f"주기계급 {len(matrix.index)}개 × 파고계급 {len(matrix.columns)}개"
        ),
        "filename": filename,
        "file_kind": kind,
        "coverage": coverage,
        "coverage_start": coverage_start,
        "coverage_end": coverage_end,
        "period_classes": list(matrix.index),
        "height_classes": list(matrix.columns),
    }

def _wink_parse_class_interval(label: str):
    """'0.5~1.0', '6.0~', ' 8.0~10.0' 등을 (하한, 상한)으로 변환."""
    text = str(label or "").replace("∼", "~").replace("～", "~").strip()
    nums = re.findall(r"[-+]?\d+(?:\.\d+)?", text)
    if not nums:
        return None
    lo = float(nums[0])
    if len(nums) >= 2:
        hi = float(nums[1])
    else:
        hi = float("inf")
    return lo, hi


def calculate_wink_occurrence_nonwork(matrix: pd.DataFrame, parse_status: dict, criterion: str):
    """WINK 파고-주기 출현율(%)을 연간 파랑 비작업일수로 환산한다.

    DCM 기준은 WINK 계급 경계(1.0/1.5m, 8s)와 정확히 일치한다.
    사석공/대선 Hs>=0.8m는 제공 Excel이 0.5m 간격인 경우 0.5~1.0m 계급 안에
    경계가 위치하므로, 그 한 계급만 선형 비례(균등분포 가정)로 추정한다.
    이 추정은 화면/엑셀에 명시한다.
    """
    empty = pd.Series(np.nan, index=range(1, 13), dtype=float)
    if matrix is None or matrix.empty:
        return empty, {"ok": False, "message": "WINK 파고·주기 출현율표가 없습니다.", "annual_days": np.nan}

    # v32: 계산기는 index=주기계급, columns=파고계급 규격만 사용한다.
    matrix = matrix.copy()
    if "주기(s)" in matrix.columns:
        locs = [i for i, c in enumerate(matrix.columns) if str(c) == "주기(s)"]
        if locs:
            period = matrix.iloc[:, locs[0]].astype(str)
            keep = [i for i in range(matrix.shape[1]) if i not in locs]
            matrix = matrix.iloc[:, keep].copy()
            matrix.index = period.values
            matrix.index.name = "주기(s)"
    matrix.index = matrix.index.astype(str)
    matrix = matrix.apply(pd.to_numeric, errors="coerce")

    if not matrix.columns.is_unique:
        ordered_cols = list(dict.fromkeys([str(c) for c in matrix.columns]))
        collapsed = {}
        for c in ordered_cols:
            part = matrix.loc[:, matrix.columns.astype(str) == c]
            collapsed[c] = part.sum(axis=1, min_count=1)
        matrix = pd.DataFrame(collapsed, index=matrix.index)

    if not matrix.index.is_unique:
        order = list(dict.fromkeys(matrix.index.tolist()))
        matrix = matrix.groupby(level=0, sort=False).sum(min_count=1).reindex(order)

    rate = 0.0
    crossing_used = False
    used_cells = []
    criterion_text = str(criterion or "")

    for p_label, row in matrix.iterrows():
        p_int = _wink_parse_class_interval(p_label)
        if not p_int:
            continue
        p_lo, p_hi = p_int
        for h_label, value in row.items():
            if pd.isna(value):
                continue
            h_int = _wink_parse_class_interval(h_label)
            if not h_int:
                continue
            h_lo, h_hi = h_int
            w = 0.0

            if "DCM" in criterion_text:
                # Hs >= 1.5m : 주기 전체
                if h_lo >= 1.5:
                    w = 1.0
                # 1.0 <= Hs < 1.5m 이면서 T >= 8s
                elif h_lo >= 1.0 and h_hi <= 1.5 + 1e-9 and p_lo >= 8.0:
                    w = 1.0
            else:
                # Hs >= 0.8m
                threshold = 0.8
                if h_lo >= threshold:
                    w = 1.0
                elif h_hi <= threshold:
                    w = 0.0
                elif np.isfinite(h_hi) and h_lo < threshold < h_hi:
                    # WINK 고정계급이 0.5~1.0처럼 0.8을 가로지르면
                    # 계급 내부 균등분포 가정으로 0.8~상한의 비율만 반영.
                    w = max(0.0, min(1.0, (h_hi - threshold) / (h_hi - h_lo)))
                    crossing_used = True

            if w > 0:
                contrib = float(value) * w
                rate += contrib
                used_cells.append({
                    "주기계급": str(p_label), "파고계급": str(h_label),
                    "원출현율(%)": float(value), "반영비율": float(w), "반영출현율(%)": contrib,
                })

    rate = float(max(0.0, min(100.0, rate)))
    annual_days = 365.0 * rate / 100.0
    monthly = pd.Series([annual_days / 12.0] * 12, index=range(1, 13), dtype=float)
    detail = pd.DataFrame({
        "월": list(range(1, 13)),
        "파랑_비작업일수": [annual_days / 12.0] * 12,
        "적용출현율_pct": [rate] * 12,
    })
    used_df = pd.DataFrame(used_cells)
    coverage = parse_status.get("coverage", "") if isinstance(parse_status, dict) else ""

    note = ""
    if crossing_used:
        note = " / Hs 0.8m 경계는 WINK 0.5m 계급표 내부에 있어 0.5~1.0m 계급을 선형비례 추정"

    return monthly.round(3), {
        "ok": True,
        "message": f"WINK 출현율 {rate:.3f}% → 연간 파랑 비작업일수 {annual_days:.2f}일{note}",
        "occurrence_rate_pct": rate,
        "annual_days": annual_days,
        "coverage": coverage,
        "monthly_detail": detail,
        "used_cells": used_df,
        "matrix": matrix.copy(),
        "approximation": crossing_used,
        "approximation_note": note.strip(" /"),
    }



def build_wink_occurrence_percent_display(matrix: pd.DataFrame) -> pd.DataFrame:
    """WINK 출현율(%) matrix를 화면용 표로 정리한다.

    matrix 규격:
      index   = 주기계급
      columns = 파고계급

    v32는 index/columns 중복을 먼저 제거해 pandas InvalidIndexError를 방지한다.
    """
    if matrix is None or matrix.empty:
        return pd.DataFrame()

    mx = matrix.copy()

    # 구버전 matrix가 들어와 '주기(s)'가 열로 남아 있으면 여기서도 복구
    if "주기(s)" in mx.columns:
        # 중복 이름까지 있을 수 있어 첫 번째 주기(s) 열만 index 후보로 사용
        locs = [i for i, c in enumerate(mx.columns) if str(c) == "주기(s)"]
        if locs:
            period = mx.iloc[:, locs[0]].astype(str)
            keep = [i for i in range(mx.shape[1]) if i not in locs]
            mx = mx.iloc[:, keep].copy()
            mx.index = period.values
            mx.index.name = "주기(s)"

    mx.index = mx.index.astype(str)
    mx.index.name = "주기(s)"
    mx = mx.apply(pd.to_numeric, errors="coerce")

    if not mx.columns.is_unique:
        ordered_cols = list(dict.fromkeys([str(c) for c in mx.columns]))
        collapsed = {}
        for c in ordered_cols:
            part = mx.loc[:, mx.columns.astype(str) == c]
            collapsed[c] = part.sum(axis=1, min_count=1)
        mx = pd.DataFrame(collapsed, index=mx.index)

    if not mx.index.is_unique:
        order = list(dict.fromkeys(mx.index.tolist()))
        mx = mx.groupby(level=0, sort=False).sum(min_count=1).reindex(order)

    row_sum = mx.sum(axis=1, min_count=1)
    col_sum = mx.sum(axis=0, min_count=1)

    out = mx.round(4).reset_index()
    out["Sum"] = row_sum.values

    sum_row = {"주기(s)": "Sum"}
    for c in mx.columns:
        sum_row[c] = float(col_sum[c]) if pd.notna(col_sum[c]) else np.nan
    sum_row["Sum"] = float(np.nansum(mx.to_numpy(dtype=float)))

    # out의 열 이름은 여기서 반드시 유일함을 보장
    out = pd.concat(
        [out, pd.DataFrame([sum_row], columns=out.columns)],
        ignore_index=True,
    )

    for c in out.columns[1:]:
        out[c] = pd.to_numeric(out[c], errors="coerce").round(4)

    return out

def fetch_wink_observation_station_catalog():
    """WINK 파랑관측자료(selectMapVw.do) 좌측의 실제 관측지점 목록을 읽는다."""
    driver = None
    with tempfile.TemporaryDirectory(prefix="wink_obs_station_list_") as td:
        try:
            driver, browser_name = _make_portal_driver(Path(td), headless=True)
            driver.get(WINK_OBS_URL)
            S = _selenium_imports()
            S["WebDriverWait"](driver, 30).until(
                lambda d: d.execute_script("return document.readyState") == "complete"
            )
            time.sleep(2.5)
            # 해역 그룹을 펼친다.
            try:
                driver.execute_script(
                    r"""
                    for(const name of ['서해안','남해안','동해안']){
                        const el=[...document.querySelectorAll('a,button,div,span')].find(e=>
                            ((e.innerText||e.textContent||'').replace(/\s+/g,' ').trim()===name));
                        if(el){const c=el.closest('a,button,[role="button"],[onclick]')||el;try{c.click();}catch(e){}}
                    }
                    """
                )
                time.sleep(0.8)
            except Exception:
                pass

            raw = driver.execute_script(
                r"""
                const root=document.querySelector('.map-lside')||document.querySelector('.map-lside-box')||document.body;
                const vals=[];
                for(const e of root.querySelectorAll('li, a, button, span')){
                    const t=(e.innerText||e.textContent||'').replace(/\s+/g,' ').trim();
                    if(t && t.length<=40) vals.push(t);
                }
                return vals;
                """
            ) or []
            stations = _wink_normalize_station_labels(raw)
            # 장기후측파랑 관련 숫자 격자/메뉴명이 끼지 않도록 추가 정리
            stations = [x for x in stations if not re.fullmatch(r"\d+(?:[-:]\d+)?", x)]
            if len(stations) < 8:
                raise RuntimeError(f"WINK 파랑관측 지점목록을 충분히 읽지 못했습니다({len(stations)}개).")
            return {"ok": True, "stations": stations, "message": f"WINK 관측지점 {len(stations)}개 자동확인", "browser": browser_name}
        except Exception as exc:
            return {"ok": False, "stations": list(WINK_STATION_FALLBACK), "message": f"WINK 지점목록 자동확인 실패 → 기본목록 사용: {exc}"}
        finally:
            if driver is not None:
                try: driver.quit()
                except Exception: pass


def _wink_visible_text_click(driver, exact_text: str, contains: bool = False):
    """보이는 버튼/링크/역할버튼 중 텍스트로 클릭."""
    try:
        return bool(driver.execute_script(
            r"""
            const q=String(arguments[0]||'').trim(), contains=Boolean(arguments[1]);
            function vis(e){const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>2&&r.height>2;}
            let els=[...document.querySelectorAll('button,a,[role="button"],input[type="button"],input[type="submit"],div,span')].filter(vis);
            els=els.filter(e=>{const t=(e.innerText||e.value||e.textContent||'').replace(/\s+/g,' ').trim();return contains?t.includes(q):t===q;});
            els.sort((a,b)=>{const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();return ar.width*ar.height-br.width*br.height;});
            for(const e of els){
                const c=e.closest('button,a,[role="button"],[onclick],input')||e;
                try{c.scrollIntoView({block:'center'});c.click();return true;}catch(err){}
            }
            return false;
            """,
            str(exact_text), bool(contains)
        ))
    except Exception:
        return False


def _wink_select_observation_station(driver, station_name: str, log: list[str]) -> dict:
    """좌측 지점명으로 지도 이동 후, 같은 이름의 색이 채워진 관측원형 점을 클릭한다."""
    S = _selenium_imports()
    By, Keys = S["By"], S["Keys"]

    if not _wink_bind_map_reference(driver, log).get("ok"):
        return {"ok": False, "message": "WINK 지도 객체를 찾지 못했습니다."}

    # 1) 좌측 검색창으로 지점을 좁힌다.
    try:
        search = None
        for e in driver.find_elements(By.CSS_SELECTOR, 'input[type="text"]'):
            meta = " ".join([e.get_attribute("placeholder") or "", e.get_attribute("title") or "", e.get_attribute("id") or ""])
            if "검색" in meta or "search" in meta.lower():
                search = e; break
        if search is not None:
            search.clear(); search.send_keys(str(station_name)); search.send_keys(Keys.ENTER)
            log.append(f"WINK 관측지점 검색: {station_name}")
            time.sleep(1.2)
    except Exception as exc:
        log.append(f"WINK 지점 검색창 입력 실패(보조경로 계속): {exc}")

    # 2) 좌측 목록의 정확한 지점명을 클릭하여 해당 위치로 이동.
    try:
        clicked = driver.execute_script(
            r"""
            const name=String(arguments[0]||'').trim();
            function vis(e){const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>2&&r.height>2;}
            const root=document.querySelector('.map-lside')||document.querySelector('.map-lside-box')||document.body;
            let els=[...root.querySelectorAll('a,button,span,div,li')].filter(e=>vis(e)&&((e.innerText||e.textContent||'').replace(/\s+/g,' ').trim()===name));
            els.sort((a,b)=>{const x=a.getBoundingClientRect(),y=b.getBoundingClientRect();return x.width*x.height-y.width*y.height;});
            if(!els.length)return false;
            const e=els[0], c=e.closest('a,button,[role="button"],[onclick]')||e;
            try{c.scrollIntoView({block:'center'});c.click();return true;}catch(err){return false;}
            """, str(station_name))
        log.append(f"WINK 좌측 관측지점 클릭: {clicked}")
        time.sleep(2.0)
    except Exception as exc:
        log.append(f"WINK 좌측 관측지점 클릭 오류: {exc}")

    _wink_bind_map_reference(driver, log)

    # 3) OpenLayers vector feature 중 속성에 지점명이 들어있는 Point를 직접 찾는다.
    hit = None
    try:
        hit = driver.execute_script(
            r"""
            const name=String(arguments[0]||'').trim();
            const m=window.__wink_auto_map;if(!m)return null;
            const found=[];
            function scanLayer(layer){
                try{
                    if(layer.getLayers){for(const sub of layer.getLayers().getArray())scanLayer(sub);}
                    const src=layer.getSource&&layer.getSource();
                    if(src&&src.getFeatures){
                        for(const f of src.getFeatures()){
                            let props={};try{props=f.getProperties?f.getProperties():{};}catch(e){}
                            let txt='';try{txt=JSON.stringify(props);}catch(e){txt=String(props);}
                            if(!txt.includes(name))continue;
                            const g=f.getGeometry&&f.getGeometry();if(!g)continue;
                            let c=null;
                            try{if(g.getCoordinates)c=g.getCoordinates();}catch(e){}
                            if(Array.isArray(c)&&typeof c[0]==='number'){
                                const p=m.getPixelFromCoordinate(c);
                                if(p)found.push({x:p[0],y:p[1],props:txt.slice(0,700)});
                            }
                        }
                    }
                }catch(e){}
            }
            try{for(const l of m.getLayers().getArray())scanLayer(l);}catch(e){}
            if(!found.length)return null;
            const size=m.getSize()||[1,1],cx=size[0]/2,cy=size[1]/2;
            found.sort((a,b)=>(a.x-cx)**2+(a.y-cy)**2-((b.x-cx)**2+(b.y-cy)**2));
            return found[0];
            """, str(station_name))
    except Exception as exc:
        log.append(f"WINK 지도 feature 탐색 실패: {exc}")

    candidates=[]
    if hit and hit.get("x") is not None:
        candidates.append((float(hit["x"]), float(hit["y"]), "feature"))
        log.append(f"WINK 관측점 feature 발견: {hit}")

    # 4) feature 속성명이 사이트 변경으로 노출되지 않으면, 지도 중심 주변의 색이 채워진 원형점 탐색.
    try:
        colored = driver.execute_script(
            r"""
            const m=window.__wink_auto_map;if(!m)return [];
            try{m.renderSync();}catch(e){}
            const vp=m.getViewport(), canv=[...vp.querySelectorAll('canvas')].filter(c=>c.width>100&&c.height>100);
            const size=m.getSize()||[vp.clientWidth,vp.clientHeight],cx=size[0]/2,cy=size[1]/2;
            const pts=[];
            for(const c of canv){
                let ctx=null,img=null;try{ctx=c.getContext('2d',{willReadFrequently:true});img=ctx.getImageData(0,0,c.width,c.height);}catch(e){continue;}
                const sx=c.width/size[0],sy=c.height/size[1],data=img.data;
                for(let y=2;y<c.height-2;y+=2){for(let x=2;x<c.width-2;x+=2){
                    const i=(y*c.width+x)*4,r=data[i],g=data[i+1],b=data[i+2],a=data[i+3]; if(a<150)continue;
                    const yellow=(r>210&&g>190&&b<90);
                    const cyan=(r<90&&g>150&&b>150);
                    const pink=(r>200&&g<130&&b>120);
                    if(!(yellow||cyan||pink))continue;
                    const px=x/sx,py=y/sy;
                    if(Math.abs(px-cx)>360||Math.abs(py-cy)>360)continue;
                    pts.push({x:px,y:py,d:(px-cx)*(px-cx)+(py-cy)*(py-cy)});
                }}
            }
            pts.sort((a,b)=>a.d-b.d);
            const out=[];
            for(const p of pts){if(out.every(q=>(q.x-p.x)**2+(q.y-p.y)**2>100))out.push(p);if(out.length>=12)break;}
            return out;
            """) or []
        for p in colored:
            candidates.append((float(p["x"]), float(p["y"]), "color"))
        if colored: log.append(f"WINK 색 원형 관측점 후보 {len(colored)}개 탐색")
    except Exception as exc:
        log.append(f"WINK 색 원형 관측점 탐색 실패: {exc}")

    # 중복 제거 후 순차 클릭. popup에 지점명 + 파랑정보가 나타나야 성공.
    unique=[]
    for x,y,src in candidates:
        if not any((x-a)**2+(y-b)**2 < 64 for a,b,_ in unique): unique.append((x,y,src))
    for x,y,src in unique[:12]:
        _wink_real_click_pixel(driver, x, y, log)
        time.sleep(0.7)
        try:
            state = driver.execute_script(
                r"""
                const name=String(arguments[0]||'');
                const els=[...document.querySelectorAll('.ol-popup,.ol-popup-content,[class*="popup"],[class*="pop-"]')];
                for(const e of els){const s=getComputedStyle(e),r=e.getBoundingClientRect();if(s.display==='none'||s.visibility==='hidden'||r.width<2||r.height<2)continue;
                    const t=(e.innerText||e.textContent||'').replace(/\s+/g,' ').trim();
                    if(t.includes(name)&&t.includes('파랑정보'))return {ok:true,text:t.slice(0,500)};
                }
                return {ok:false};
                """, str(station_name)) or {}
        except Exception:
            state={}
        if state.get("ok"):
            log.append(f"WINK 색 원형 관측점 선택 성공({src}): {state.get('text','')[:220]}")
            return {"ok": True, "station": station_name, "pixel": (x,y), "source": src}

    return {"ok": False, "message": f"WINK 지도에서 {station_name}의 색 원형 관측점을 열지 못했습니다."}


def _wink_open_wave_info_panel(driver, log: list[str]) -> dict:
    if not _wink_visible_text_click(driver, "파랑정보"):
        return {"ok": False, "message": "관측지점 팝업에서 '파랑정보' 버튼을 찾지 못했습니다."}
    log.append("WINK 관측지점 팝업 → 파랑정보 클릭")
    for _ in range(30):
        time.sleep(0.35)
        try:
            text = driver.execute_script("return document.body ? document.body.innerText : ''") or ""
        except Exception:
            text = ""
        if "파랑정보 개요" in text or "파고주기 계급별 출현율 다운로드" in text:
            log.append("WINK 파랑정보 개요 화면 확인")
            return {"ok": True}
    return {"ok": False, "message": "'파랑정보 개요' 화면이 열리지 않았습니다."}


def _wink_set_observation_query_period(driver, start_year: int, end_year: int, log: list[str]) -> dict:
    """파랑정보 화면의 조회기간을 연도바에 맞춘다. 전체 제공기간 밖이면 자동으로 잘라낸다."""
    requested_start = pd.Timestamp(int(start_year),1,1)
    requested_end = pd.Timestamp(int(end_year),12,31)
    try:
        body = driver.execute_script("return document.body ? document.body.innerText : ''") or ""
    except Exception:
        body = ""

    cov_start=cov_end=None
    m=re.search(r"전체자료\s*제공기간\s*(\d{4}-\d{2}-\d{2})\s*~\s*(\d{4}-\d{2}-\d{2})", body)
    if m:
        try:
            cov_start=pd.Timestamp(m.group(1));cov_end=pd.Timestamp(m.group(2))
        except Exception: pass
    eff_start=max(requested_start,cov_start) if cov_start is not None else requested_start
    eff_end=min(requested_end,cov_end) if cov_end is not None else requested_end
    if eff_start>eff_end:
        return {"ok":False,"message":f"선택 연도 {start_year}~{end_year}가 이 WINK 지점의 제공기간과 겹치지 않습니다.","coverage_start":cov_start,"coverage_end":cov_end}

    start_s=eff_start.strftime('%Y-%m-%d'); end_s=eff_end.strftime('%Y-%m-%d')
    result=driver.execute_script(
        r"""
        const start=arguments[0],end=arguments[1];
        function vis(e){const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>2&&r.height>2;}
        let inputs=[...document.querySelectorAll('input')].filter(e=>vis(e));
        let dates=inputs.filter(e=>/^\d{4}-\d{2}-\d{2}$/.test((e.value||'').trim()) || /date|day|dt/i.test((e.id||'')+' '+(e.name||'')+' '+(e.className||'')));
        // 가장 가능성이 높은 두 날짜 입력칸
        if(dates.length<2)return {ok:false,count:dates.length,all:inputs.map(e=>({id:e.id,name:e.name,value:e.value,type:e.type})).slice(0,40)};
        dates=dates.slice(0,2);
        function setv(e,v){
            const proto=Object.getPrototypeOf(e),desc=Object.getOwnPropertyDescriptor(proto,'value');
            if(desc&&desc.set)desc.set.call(e,v);else e.value=v;
            e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));
        }
        setv(dates[0],start);setv(dates[1],end);
        return {ok:true,startId:dates[0].id,endId:dates[1].id,vals:[dates[0].value,dates[1].value]};
        """, start_s,end_s) or {}
    log.append(f"WINK 조회기간 입력: {result}")

    # 조회/검색 버튼이 있으면 실행한다. 없으면 변경 이벤트만으로 반영되는 UI일 수 있다.
    for text in ["조회","검색","적용"]:
        if _wink_visible_text_click(driver,text):
            log.append(f"WINK 파랑정보 기간 {text} 버튼 클릭")
            time.sleep(1.5)
            break

    return {"ok":bool(result.get('ok')),"start":eff_start,"end":eff_end,"start_text":start_s,"end_text":end_s,"coverage_start":cov_start,"coverage_end":cov_end,"dom":result}



def _wink_download_occurrence_excel(
    driver,
    download_dir: Path,
    log: list[str],
    institution_code: str,
    institution_other: str,
    use_purpose: str,
    agree: bool,
) -> Path:
    """WINK 출현율 다운로드 UI를 실행하고 '실제 Excel' 파일만 반환한다."""
    if not str(institution_code or "").strip():
        raise RuntimeError("WINK 다운로드 소속기관 유형을 선택하세요.")
    if str(institution_code) == "99" and not str(institution_other or "").strip():
        raise RuntimeError("WINK 소속기관 유형이 '기타'이면 구체적인 기관 유형을 입력하세요.")
    if not str(use_purpose or "").strip():
        raise RuntimeError("WINK 자료 사용목적을 입력하세요.")
    if not agree:
        raise RuntimeError("WINK 자료 이용 책임고지에 동의해야 출현율 Excel을 자동 다운로드할 수 있습니다.")

    if not _wink_visible_text_click(
        driver, "파고주기 계급별 출현율 다운로드", contains=True
    ):
        raise RuntimeError(
            "WINK 파랑정보 화면에서 '파고주기 계급별 출현율 다운로드' 버튼을 찾지 못했습니다."
        )
    log.append("WINK 파고주기 계급별 출현율 다운로드 클릭")

    S = _selenium_imports()
    By, WebDriverWait = S["By"], S["WebDriverWait"]
    try:
        WebDriverWait(driver, 15).until(
            lambda d: len(d.find_elements(By.ID, "regist")) > 0
        )
    except Exception:
        # 모달 없이 바로 다운로드되는 구조라면 실제 Excel만 기다린다.
        p, invalid = _wink_wait_valid_excel_download(
            download_dir, time.time() - 5, timeout=20.0
        )
        if p is not None:
            return p
        raise RuntimeError(
            "WINK 출현율 다운로드 입력창(#regist)을 찾지 못했습니다. "
            + (f"감지된 비정상 파일: {invalid}" if invalid else "")
        )

    # 최종 다운로드 클릭 직전 시간을 기록해야 빠른 다운로드도 놓치지 않는다.
    started = time.time()
    result = driver.execute_script(
        r"""
        const orgCode=String(arguments[0]||'');
        const orgOther=String(arguments[1]||'');
        const purpose=String(arguments[2]||'');
        function setChecked(el){
            if(!el) return false;
            el.checked=true;
            el.dispatchEvent(new Event('input',{bubbles:true}));
            el.dispatchEvent(new Event('change',{bubbles:true}));
            return true;
        }
        function setValue(el,v){
            if(!el) return false;
            const proto=Object.getPrototypeOf(el);
            const desc=Object.getOwnPropertyDescriptor(proto,'value');
            if(desc&&desc.set) desc.set.call(el,v); else el.value=v;
            el.dispatchEvent(new Event('input',{bubbles:true}));
            el.dispatchEvent(new Event('change',{bubbles:true}));
            return true;
        }
        const org=document.querySelector(`input[name="ogdpInstCd"][value="${orgCode}"]`);
        const other=document.querySelector('#ogdpInstEtcNm');
        const use=document.querySelector('#usePrps');
        const agreeY=document.querySelector('#agreYnY');
        const regist=document.querySelector('#regist');
        const state={
            org:setChecked(org),
            other: orgCode==='99' ? setValue(other,orgOther) : true,
            purpose:setValue(use,purpose),
            agree:setChecked(agreeY),
            regist:!!regist
        };
        if(regist){regist.scrollIntoView({block:'center'});regist.click();}
        return state;
        """,
        str(institution_code),
        str(institution_other or ""),
        str(use_purpose),
    ) or {}
    log.append(f"WINK 다운로드 입력/동의 및 최종 다운로드 클릭: {result}")

    if not all(
        bool(result.get(k))
        for k in ("org", "other", "purpose", "agree", "regist")
    ):
        raise RuntimeError(
            f"WINK 다운로드 입력값 자동설정에 실패했습니다: {result}"
        )

    p, invalid = _wink_wait_valid_excel_download(
        download_dir, started, timeout=120.0
    )
    if p is None:
        try:
            body = driver.execute_script(
                "return document.body ? document.body.innerText : ''"
            ) or ""
        except Exception:
            body = ""

        if "입력값을 확인" in body or "필수 입력" in body:
            raise RuntimeError(
                "WINK 다운로드 입력값 검증을 통과하지 못했습니다. "
                "소속기관/사용목적/동의를 확인하세요."
            )

        extra = (
            " / 감지된 비정상 다운로드: " + " | ".join(invalid[-3:])
            if invalid else ""
        )
        raise RuntimeError(
            "출현율 다운로드를 요청했지만 정상 Excel(.xlsx/.xls) 파일을 확인하지 못했습니다."
            + extra
        )

    kind, desc = _wink_excel_kind(p.read_bytes())
    log.append(f"WINK 정상 Excel 확인: {p.name} / {kind} / {desc}")
    return p

def auto_download_wink_observation_occurrence(
    station_name: str,
    headless: bool = True,
    institution_code: str = "",
    institution_other: str = "",
    use_purpose: str = "",
    agree: bool = False,
) -> dict:
    """WINK 색 원형 관측점 → 파랑정보 → '파고주기 계급별 출현율' Excel 자동 다운로드.

    주의: WINK 화면 안내와 실제 다운로드 로직상 이 Excel은 사용자가 입력한 조회기간이 아니라
    해당 관측지점의 '전체자료 제공기간'에 대한 통계자료다. 따라서 연도별 반복조회는 하지 않는다.
    """
    log=[];driver=None
    with tempfile.TemporaryDirectory(prefix='wink_obs_occ_') as tmp:
        tmpdir=Path(tmp)
        try:
            driver,browser_name=_make_portal_driver(tmpdir,headless=headless)
            log.append(f"자동 브라우저: {browser_name}")
            driver.get(WINK_OBS_URL)
            S=_selenium_imports()
            S['WebDriverWait'](driver,30).until(lambda d:d.execute_script('return document.readyState')=='complete')
            time.sleep(2.5)
            log.append('WINK 파랑관측자료 화면 접속')

            selected=_wink_select_observation_station(driver,station_name,log)
            if not selected.get('ok'):
                raise RuntimeError(selected.get('message'))
            opened=_wink_open_wave_info_panel(driver,log)
            if not opened.get('ok'):
                raise RuntimeError(opened.get('message'))

            cov_start,cov_end=_wink_extract_observation_coverage(driver)
            if cov_start is not None and cov_end is not None:
                log.append(f"WINK 전체자료 제공기간: {cov_start.date()}~{cov_end.date()}")
            log.append("파고주기 계급별 출현율 Excel은 WINK 전체자료 제공기간 통계를 다운로드")

            downloaded=_wink_download_occurrence_excel(
                driver,tmpdir,log,
                institution_code=institution_code,
                institution_other=institution_other,
                use_purpose=use_purpose,
                agree=agree,
            )
            raw=downloaded.read_bytes()
            matrix,parse_status=_wink_read_occurrence_excel(raw,downloaded.name)
            if not parse_status.get('ok'):
                raise RuntimeError(parse_status.get('message'))

            actual_start=parse_status.get('coverage_start') or cov_start
            actual_end=parse_status.get('coverage_end') or cov_end
            if actual_start is not None and actual_end is not None:
                log.append(f"WINK 출현율 Excel 관측기간: {actual_start.date()}~{actual_end.date()}")

            safe_station=re.sub(r'[^0-9A-Za-z가-힣_.-]+','_',station_name)
            safe_name=re.sub(r'[^0-9A-Za-z가-힣_.-]+','_',downloaded.name)
            out_name=f"wink_occurrence_{safe_station}_FULL_{safe_name}"
            cache_path=WINK_CACHE_DIR/out_name
            _saved_cache_path = _wink_safe_cache_write(raw, cache_path, log)
            if _saved_cache_path is not None:
                log.append(f"WINK 출현율 Excel 캐시 저장: {_saved_cache_path.name}")
            return {
                'ok':True,
                'message':f"WINK {station_name} 파고·주기 계급별 출현율 Excel 자동수집 성공: {downloaded.name}",
                'raw':raw,'filename':downloaded.name,'matrix':matrix,'parse_status':parse_status,
                'station_name':station_name,'coverage_start':actual_start,'coverage_end':actual_end,
                'source_mode':'WINK 파고주기 계급별 출현율 Excel(전체자료 제공기간)',
                'cache_path':str(_saved_cache_path) if _saved_cache_path is not None else '','log':log,
            }
        except Exception as exc:
            debug_html=BASE_DIR/'wink_debug_observation.html';debug_png=BASE_DIR/'wink_debug_observation.png'
            try:
                if driver is not None:
                    debug_html.write_text(driver.page_source,encoding='utf-8')
                    driver.save_screenshot(str(debug_png))
            except Exception: pass
            return {'ok':False,'message':str(exc),'log':log,'debug_html':str(debug_html),'debug_png':str(debug_png)}
        finally:
            if driver is not None:
                try: driver.quit()
                except Exception: pass


def _wink_extract_observation_coverage(driver):
    """현재 열린 WINK 파랑정보 화면의 전체자료 제공기간을 읽는다."""
    try:
        result = driver.execute_script(
            r"""
            const minEl=document.querySelector('[name="minDate"]');
            const maxEl=document.querySelector('[name="maxDate"]');
            const minDate=minEl ? (minEl.textContent||minEl.innerText||'').trim() : '';
            const maxDate=maxEl ? (maxEl.textContent||maxEl.innerText||'').trim() : '';
            return {minDate,maxDate};
            """
        ) or {}
    except Exception:
        result={}
    start=end=None
    try:
        if result.get('minDate'): start=pd.Timestamp(result['minDate'])
        if result.get('maxDate'): end=pd.Timestamp(result['maxDate'])
    except Exception:
        start=end=None
    if start is None or end is None:
        try:
            body=driver.execute_script("return document.body ? document.body.innerText : ''") or ''
        except Exception:
            body=''
        m=re.search(r"전체자료\s*제공기간\s*(\d{4}-\d{2}-\d{2})\s*~\s*(\d{4}-\d{2}-\d{2})", body)
        if m:
            try:
                start=pd.Timestamp(m.group(1)); end=pd.Timestamp(m.group(2))
            except Exception:
                pass
    return start,end


def _wink_fetch_graph_period(driver, start_date, end_date, log: list[str]):
    """WINK가 화면 그래프에 사용하는 내부 조회를 1개 기간에 대해 호출한다.

    WINK 페이지의 searchForm/searchDate1/searchDate2와 동일한 값을 사용하고,
    화면 자체가 사용하는 /obsv/selectGraph.do 응답을 받아 원시 파고/주기 시계열로 변환한다.
    """
    start_s=pd.Timestamp(start_date).strftime('%Y-%m-%d')
    end_s=pd.Timestamp(end_date).strftime('%Y-%m-%d')
    try:
        driver.set_script_timeout(70)
    except Exception:
        pass

    result=driver.execute_async_script(
        r"""
        const start=arguments[0], end=arguments[1], done=arguments[2];
        try{
            const q=(sel)=>document.querySelector(sel);
            const cond=q('#searchCondition');
            if(cond){cond.value='period'; cond.dispatchEvent(new Event('change',{bubbles:true}));}
            const s1=q('#searchDate1'), s2=q('#searchDate2'), cur=q('#currentCondition');
            if(s1)s1.value=start;
            if(s2)s2.value=end;
            if(cur)cur.value='period';
            const vs=q('#searchDateS'), ve=q('#searchDateE');
            if(vs)vs.value=start;
            if(ve)ve.value=end;

            if(typeof commonUtils==='undefined' || typeof commonUtils.formToObject!=='function'){
                done({ok:false,message:'commonUtils.formToObject 없음'}); return;
            }
            const params=commonUtils.formToObject('searchForm');
            const success=function(res){
                try{
                    const arr=(res&&res.resultData&&res.resultData.obsvChart)||[];
                    done({ok:true,records:arr});
                }catch(e){done({ok:false,message:String(e)});}
            };
            const error=function(xhr,status,err){
                done({ok:false,message:'AJAX '+String(status||'')+' '+String(err||''),httpStatus:xhr&&xhr.status});
            };
            if(typeof commonUtils.ajax==='function'){
                commonUtils.ajax({url:'/obsv/selectGraph.do',data:params,success:success,error:error});
            }else if(typeof $!=='undefined' && $.ajax){
                $.ajax({url:'/obsv/selectGraph.do',data:params,success:success,error:error});
            }else{
                done({ok:false,message:'AJAX 함수 없음'});
            }
        }catch(e){done({ok:false,message:String(e)});}
        """,
        start_s,end_s
    ) or {}

    if not result.get('ok'):
        raise RuntimeError(f"WINK {start_s}~{end_s} 조회 실패: {result.get('message','알 수 없는 오류')}")

    rows=result.get('records') or []
    if not rows:
        log.append(f"WINK {start_s}~{end_s}: 자료 0건")
        return pd.DataFrame(columns=['일시','유의파고','주기'])

    out=[]
    for row in rows:
        if not isinstance(row,dict):
            continue
        dt=row.get('obsvDt') or row.get('obsrvnDt') or row.get('date') or row.get('datetime')
        hs=row.get('sgnfctWvhgtVl0')
        if hs is None: hs=row.get('sgnfctWvhgtVl')
        if hs is None: hs=row.get('hs')
        tp=row.get('pkprdVl0')
        if tp is None: tp=row.get('pkprdVl')
        if tp is None: tp=row.get('tp')
        out.append((dt,hs,tp))
    df=pd.DataFrame(out,columns=['일시','유의파고','주기'])
    if df.empty:
        return df
    df['일시']=pd.to_datetime(df['일시'],errors='coerce')
    df['유의파고']=pd.to_numeric(df['유의파고'],errors='coerce')
    df['주기']=pd.to_numeric(df['주기'],errors='coerce')
    df.loc[df['유의파고']<0,'유의파고']=np.nan
    df.loc[df['주기']<0,'주기']=np.nan
    df=df.dropna(subset=['일시','유의파고']).copy()
    df=df[(df['일시']>=pd.Timestamp(start_s)) & (df['일시']<pd.Timestamp(end_s)+pd.Timedelta(days=1))]
    log.append(f"WINK {start_s}~{end_s}: 원시 파랑자료 {len(df):,}건")
    return df.reset_index(drop=True)


def auto_fetch_wink_observation_yearly(station_name: str, start_year: int, end_year: int, headless: bool=True) -> dict:
    """WINK 관측지점의 파랑 원시자료를 최대 1년 단위로 나눠 자동수집한다.

    WINK 화면은 조회기간을 최대 1년으로 제한하므로, 선택한 연도범위를 연도별로 쪼개
    /obsv/selectGraph.do를 호출한다. 각 연도의 유의파고/첨두주기 시계열을 합친 뒤
    앱 내부에서 정확한 Hs/주기 기준으로 비작업일수를 계산한다.
    """
    log=[]; driver=None
    try:
        with tempfile.TemporaryDirectory(prefix='wink_obs_yearly_') as td:
            driver,browser_name=_make_portal_driver(Path(td),headless=headless)
            log.append(f"자동 브라우저: {browser_name}")
            driver.get(WINK_OBS_URL)
            S=_selenium_imports()
            S['WebDriverWait'](driver,30).until(lambda d:d.execute_script('return document.readyState')=='complete')
            time.sleep(2.5)
            log.append('WINK 파랑관측자료 화면 접속')

            selected=_wink_select_observation_station(driver,station_name,log)
            if not selected.get('ok'):
                raise RuntimeError(selected.get('message'))
            opened=_wink_open_wave_info_panel(driver,log)
            if not opened.get('ok'):
                raise RuntimeError(opened.get('message'))

            cov_start,cov_end=_wink_extract_observation_coverage(driver)
            req_start=pd.Timestamp(int(start_year),1,1)
            req_end=pd.Timestamp(int(end_year),12,31)
            eff_start=max(req_start,cov_start) if cov_start is not None else req_start
            eff_end=min(req_end,cov_end) if cov_end is not None else req_end
            if eff_start>eff_end:
                raise RuntimeError(
                    f"선택 연도 {start_year}~{end_year}가 {station_name}의 WINK 제공기간과 겹치지 않습니다."
                )

            yearly=[]; status_rows=[]
            for year in range(int(eff_start.year), int(eff_end.year)+1):
                ys=max(pd.Timestamp(year,1,1),eff_start)
                ye=min(pd.Timestamp(year,12,31),eff_end)
                if ys>ye:
                    continue
                # Jan 1~Dec 31도 날짜 차이는 365일이므로 WINK 최대 1년 제한을 만족한다.
                try:
                    dfy=_wink_fetch_graph_period(driver,ys,ye,log)
                    if not dfy.empty:
                        dfy['조회연도']=year
                        yearly.append(dfy)
                    status_rows.append({
                        '연도':year,'조회시작':ys.date(),'조회종료':ye.date(),
                        '자료건수':int(len(dfy)),'상태':'성공' if len(dfy)>0 else '자료없음','오류':''
                    })
                except Exception as exc:
                    log.append(f"WINK {year}년 조회 오류: {exc}")
                    status_rows.append({
                        '연도':year,'조회시작':ys.date(),'조회종료':ye.date(),
                        '자료건수':0,'상태':'오류','오류':str(exc)
                    })
                time.sleep(0.35)

            combined=pd.concat(yearly,ignore_index=True) if yearly else pd.DataFrame(columns=['일시','유의파고','주기','조회연도'])
            if not combined.empty:
                combined=combined.drop_duplicates(subset=['일시'],keep='last').sort_values('일시').reset_index(drop=True)
                safe_station=re.sub(r'[^0-9A-Za-z가-힣_.-]+','_',station_name)
                cache_path=WINK_CACHE_DIR/f"wink_observation_{safe_station}_{start_year}_{end_year}.csv"
                try:
                    combined.to_csv(cache_path,index=False,encoding='utf-8-sig')
                    log.append(f"WINK 연도별 원시자료 캐시 저장: {cache_path.name}")
                except Exception as exc:
                    log.append(f"WINK 캐시 저장 실패: {exc}")

            status_df=pd.DataFrame(status_rows)
            success_years=status_df.loc[status_df['자료건수']>0,'연도'].astype(int).tolist() if not status_df.empty else []
            error_years=status_df.loc[status_df['상태']=='오류','연도'].astype(int).tolist() if not status_df.empty else []
            if combined.empty:
                raise RuntimeError(
                    f"WINK {station_name}에서 {eff_start.date()}~{eff_end.date()} 기간의 원시 파랑자료를 가져오지 못했습니다."
                )

            return {
                'ok':True,
                'message':(
                    f"WINK {station_name} 연도별 자동수집 성공: {len(success_years)}개 연도 / "
                    f"원시자료 {len(combined):,}건" + (f" / 오류연도 {error_years}" if error_years else '')
                ),
                'wave_df':combined,
                'year_status':status_df,
                'coverage_start':cov_start,'coverage_end':cov_end,
                'effective_start':eff_start,'effective_end':eff_end,
                'success_years':success_years,'error_years':error_years,
                'station_name':station_name,'log':log,
            }
    except Exception as exc:
        debug_html=BASE_DIR/'wink_debug_observation.html';debug_png=BASE_DIR/'wink_debug_observation.png'
        try:
            if driver is not None:
                debug_html.write_text(driver.page_source,encoding='utf-8')
                driver.save_screenshot(str(debug_png))
        except Exception:
            pass
        return {'ok':False,'message':str(exc),'log':log,'debug_html':str(debug_html),'debug_png':str(debug_png)}
    finally:
        if driver is not None:
            try: driver.quit()
            except Exception: pass

AIRKOREA_FINAL_URL = "https://www.airkorea.or.kr/web/last_amb_hour_data?pMENU_NO=123"
AIRKOREA_FIRST_YEAR = 2001

# 에어코리아 연도 ZIP은 '전국 전체 측정소 + 1~12월' 자료이다.
# 따라서 사이트에서 측정망/지역/측정소/조회기간을 고르지 않는다.
# 연도 ZIP을 먼저 받은 뒤 앱 내부에서 선택 ASOS 지점에 해당하는 지역과 측정소를 필터링한다.
